// Genererad: sektion 2 och framåt (enhet 13+), alla fyra språk.
import type { Lesson, UnitDef } from '../types';
export const NEWC: Record<string, Lesson> = {"x13": {"t": "Diagramtyper", "c": [{"t": "Linjediagram", "d": "Ett linjediagram binder ihop stängningspriserna med en linje. Trenden syns tydligt, men du ser inte högsta och lägsta pris.", "fig": "line"}, {"t": "Stapeldiagram", "d": "Ett stapeldiagram visar samma fyra priser som ett ljus: ett streck från lägsta till högsta, ett litet streck åt vänster för öppning och ett åt höger för stängning."}, {"t": "Heikin-Ashi", "d": "Heikin-Ashi är ljus som räknas fram av medelvärden. Trenden blir lugnare att se, men priserna i ljusen är inte de verkliga priserna."}], "q": [{"q": "Vilken diagramtyp visar bara stängningspriserna?", "o": ["Linjediagram", "Candlestick", "Stapeldiagram", "Heikin-Ashi"], "why": "Linjediagrammet drar en linje mellan stängningspriserna och visar inte högsta eller lägsta."}, {"q": "Vad är en nackdel med Heikin-Ashi?", "o": ["Priserna i ljusen är inte de verkliga priserna", "Det går inte att se trender", "Det visar inga färger", "Det fungerar bara på veckografer"], "why": "Heikin-Ashi räknar fram medelvärden, så öppning och stängning i ljuset är inte det som faktiskt handlades."}, {"q": "I ett stapeldiagram, vad visar det lilla strecket till höger?", "o": ["Stängningspriset", "Öppningspriset", "Volymen", "Högsta priset"], "why": "Strecket till vänster är öppning och strecket till höger är stängning."}, {"q": "Varför använder många traders candlestick-diagram?", "o": ["Färg och kropp gör rörelsen lätt att se", "De visar framtida priser", "De har ingen volym", "De är de enda som visar trender"], "why": "Candlestick visar samma fyra priser som staplar, men färgen och kroppen gör det lättare att se vem som vann perioden."}, {"m": [["Linjediagram", "Bara stängningspriser"], ["Stapeldiagram", "Fyra priser med streck"], ["Candlestick", "Fyra priser med kropp"], ["Heikin-Ashi", "Ljus av medelvärden"]]}]}, "x14": {"t": "Trendlinjer och kanaler", "c": [{"t": "Trendlinje", "d": "En trendlinje dras genom minst två bottnar i en upptrend, eller två toppar i en nedtrend. Ju fler gånger priset rör linjen, desto viktigare blir den.", "fig": "chan"}, {"t": "Kanal", "d": "En kanal är två parallella linjer. Priset studsar mellan den undre och den övre linjen medan trenden fortsätter.", "fig": "chan"}, {"t": "Brott mot trendlinjen", "d": "När priset stänger tydligt på fel sida om trendlinjen kan trenden vara på väg att ta slut. Vänta gärna på bekräftelse."}], "q": [{"q": "Hur många bottnar behövs minst för att dra en trendlinje i en upptrend?", "o": ["2", "1", "5", "10"], "why": "Två punkter räcker för att dra en linje. En tredje beröring gör den mer pålitlig."}, {"q": "Priset rör sig uppåt mellan två parallella linjer. Vad kallas det?", "o": ["En stigande kanal", "Ett gap", "En doji", "En dubbeltopp"]}, {"q": "Vad kan det betyda när priset stänger under en stigande trendlinje?", "o": ["Upptrenden kan vara på väg att ta slut", "Upptrenden blir garanterat starkare", "Ingenting, linjer betyder inget", "Att aktien har delat ut pengar"], "why": "Ett brott är en varning. Många väntar på bekräftelse innan de agerar."}, {"q": "Var i en stigande kanal finns oftast stödet?", "o": ["Vid den undre linjen", "Vid den övre linjen", "Mitt i kanalen", "Utanför kanalen"]}, {"m": [["Trendlinje", "Linje genom bottnar eller toppar"], ["Kanal", "Två parallella linjer"], ["Brott", "Priset stänger på fel sida"], ["Beröring", "Priset rör linjen"]]}]}, "x15": {"t": "Huvud och axlar", "c": [{"t": "Huvud och axlar", "d": "Huvud och axlar består av tre toppar: en vänster axel, ett högre huvud och en höger axel. Det är ett vanligt vändningsmönster efter en uppgång.", "fig": "hs"}, {"t": "Halslinjen", "d": "Halslinjen dras genom bottnarna mellan topparna. Mönstret räknas som klart först när priset stänger under halslinjen.", "fig": "hs"}, {"t": "Omvänd huvud och axlar", "d": "Omvänd huvud och axlar är samma mönster upp och ner. Det kan visa en vändning uppåt efter en nedgång."}], "q": [{"q": "Hur många toppar har huvud och axlar?", "o": ["3", "2", "4", "1"], "why": "Vänster axel, huvud och höger axel."}, {"q": "När räknas huvud och axlar som klart?", "o": ["När priset stänger under halslinjen", "När huvudet bildas", "När vänster axel bildas", "Direkt när du ser två toppar"], "why": "Utan en stängning under halslinjen är det bara tre toppar. Bekräftelsen kommer med brottet."}, {"q": "Vad signalerar huvud och axlar oftast?", "o": ["Möjlig vändning nedåt", "Möjlig vändning uppåt", "Fortsättning uppåt", "Ingenting"]}, {"q": "Vad kallas mönstret upp och ner efter en nedgång?", "o": ["Omvänd huvud och axlar", "Dubbeltopp", "Stjärnfall", "Flagga"]}, {"m": [["Vänster axel", "Första toppen"], ["Huvud", "Den högsta toppen"], ["Höger axel", "Tredje toppen"], ["Halslinje", "Linje genom bottnarna"]]}]}, "x16": {"t": "Dubbeltopp och dubbelbotten", "c": [{"t": "Dubbeltopp", "d": "En dubbeltopp är två toppar på ungefär samma nivå, som ett M. Köparna misslyckas två gånger med att ta sig förbi samma tak.", "fig": "dtop"}, {"t": "Dubbelbotten", "d": "En dubbelbotten är två bottnar på ungefär samma nivå, som ett W. Säljarna misslyckas två gånger med att pressa priset lägre.", "fig": "dbot"}, {"t": "Bekräftelse av M och W", "d": "En dubbeltopp bekräftas när priset stänger under botten mellan topparna. En dubbelbotten bekräftas när priset stänger över toppen mellan bottnarna."}], "q": [{"q": "Vilken bokstav liknar en dubbeltopp?", "o": ["M", "W", "V", "U"]}, {"q": "Vad signalerar en dubbelbotten oftast?", "o": ["Möjlig vändning uppåt", "Möjlig vändning nedåt", "Fortsättning nedåt", "Obeslutsamhet"]}, {"q": "När bekräftas en dubbeltopp?", "o": ["När priset stänger under botten mellan topparna", "När den andra toppen bildas", "När volymen är låg", "När priset når en ny topp"]}, {"q": "Vad betyder det om priset tar sig över båda topparna i en dubbeltopp?", "o": ["Mönstret misslyckades", "Mönstret blev starkare", "Det blev en dubbelbotten", "Ingenting alls"], "why": "Bryter priset upp över topparna har köparna vunnit, och då gäller inte dubbeltoppen längre."}, {"m": [["Dubbeltopp", "Två toppar, som ett M"], ["Dubbelbotten", "Två bottnar, som ett W"], ["Mellanbotten", "Nivån mellan topparna"], ["Bekräftelse", "Stängning förbi mellannivån"]]}]}, "x17": {"t": "Trianglar", "c": [{"t": "Stigande triangel", "d": "En stigande triangel har ett platt tak och stigande bottnar. Köparna blir allt ivrigare, och ofta bryter priset uppåt.", "fig": "tri"}, {"t": "Fallande triangel", "d": "En fallande triangel har ett platt golv och fallande toppar. Säljarna trycker på, och ofta bryter priset nedåt."}, {"t": "Symmetrisk triangel", "d": "I en symmetrisk triangel blir topparna lägre och bottnarna högre. Priset trycks ihop och kan bryta åt båda hållen."}], "q": [{"q": "Vilken triangel har platt tak och stigande bottnar?", "o": ["Stigande triangel", "Fallande triangel", "Symmetrisk triangel", "Ingen triangel"]}, {"q": "Åt vilket håll bryter en symmetrisk triangel?", "o": ["Det kan bli åt båda hållen", "Alltid uppåt", "Alltid nedåt", "Aldrig"]}, {"q": "Vad händer med prissvängningarna inne i en triangel?", "o": ["De blir mindre", "De blir större", "Priset står helt still", "De blir slumpmässiga"]}, {"q": "Vad är klokt innan man handlar ett utbrott ur en triangel?", "o": ["Vänta på en stängning utanför triangeln", "Köpa mitt i triangeln", "Strunta i stop-loss", "Satsa hela kontot"], "why": "Många utbrott är falska. En stängning utanför triangeln ger en tydligare signal."}, {"m": [["Stigande triangel", "Platt tak, stigande bottnar"], ["Fallande triangel", "Platt golv, fallande toppar"], ["Symmetrisk triangel", "Båda linjerna lutar mot varandra"], ["Utbrott", "Priset lämnar mönstret"]]}]}, "x18": {"t": "Flaggor och vimplar", "c": [{"t": "Flaggstång", "d": "En flagga börjar med en snabb och stark rörelse. Den kallas flaggstång.", "fig": "flag"}, {"t": "Flagga", "d": "Efter stången vilar priset i en liten kanal som lutar lite mot trenden. Det är flaggan, en paus innan rörelsen ofta fortsätter.", "fig": "flag"}, {"t": "Vimpel", "d": "En vimpel liknar en flagga, men pausen ser ut som en liten symmetrisk triangel."}], "q": [{"q": "Vad kallas den första snabba rörelsen i en flagga?", "o": ["Flaggstång", "Huvud", "Halslinje", "Gap"]}, {"q": "Vad signalerar en flagga oftast?", "o": ["Att trenden fortsätter", "Att trenden vänder", "Att aktien delas", "Ingenting"]}, {"q": "Hur ser pausen ut i en vimpel?", "o": ["Som en liten symmetrisk triangel", "Som ett M", "Som en lång röd kropp", "Som en rak linje"]}, {"q": "En flagga bildas efter en kraftig uppgång. När bekräftas den?", "o": ["När priset bryter upp ur flaggan", "När priset faller under stångens början", "Mitt i flaggan", "Den behöver inte bekräftas"]}, {"m": [["Flaggstång", "Snabb, stark rörelse"], ["Flagga", "Liten lutande kanal"], ["Vimpel", "Liten triangel efter stången"], ["Fortsättning", "Trenden går vidare"]]}]}, "x19": {"t": "Kilar och rektanglar", "c": [{"t": "Stigande kil", "d": "En stigande kil har stigande toppar och bottnar, men linjerna närmar sig varandra. Uppgången tappar kraft och kilen bryts ofta nedåt.", "fig": "wedge"}, {"t": "Fallande kil", "d": "En fallande kil är motsatsen: fallande linjer som närmar sig varandra. Den bryts ofta uppåt."}, {"t": "Rektangel", "d": "I en rektangel studsar priset mellan ett platt golv och ett platt tak. Det är ett intervall som till slut bryts åt något håll.", "fig": "sr"}], "q": [{"q": "Åt vilket håll bryts en stigande kil oftast?", "o": ["Nedåt", "Uppåt", "Den bryts aldrig", "Åt sidan"]}, {"q": "Vad skiljer en kil från en kanal?", "o": ["I en kil närmar sig linjerna varandra", "En kil har bara en linje", "En kanal har inga linjer", "Det finns ingen skillnad"]}, {"q": "Priset studsar mellan ett platt golv och ett platt tak. Vad kallas det?", "o": ["Rektangel", "Kil", "Flagga", "Huvud och axlar"]}, {"q": "Vad visar en stigande kil om uppgången?", "o": ["Att den tappar kraft", "Att den blir starkare", "Att den aldrig tar slut", "Ingenting"], "why": "Topparna stiger allt mindre för varje gång. Köparna orkar inte lika mycket längre."}, {"m": [["Stigande kil", "Bryts ofta nedåt"], ["Fallande kil", "Bryts ofta uppåt"], ["Rektangel", "Platt golv och platt tak"], ["Linjer som möts", "Rörelsen tappar kraft"]]}]}, "x20": {"t": "Gap", "c": [{"t": "Gap", "d": "Ett gap är ett tomrum i grafen där ingen handel har skett. Det uppstår ofta när priset öppnar långt från gårdagens stängning, till exempel efter nyheter.", "fig": "gap"}, {"t": "Utbrottsgap", "d": "Ett gap som bryter ut ur ett intervall på hög volym kan vara början på en ny trend."}, {"t": "Stängda gap", "d": "Ibland går priset tillbaka och fyller gapet. Det kallas att gapet stängs. Det händer ofta, men inte alltid."}], "q": [{"q": "Vad är ett gap?", "o": ["Ett tomrum i grafen där ingen handel skett", "Ett mycket långt ljus", "En linje genom bottnar", "En avgift"]}, {"q": "Vad orsakar ofta ett gap?", "o": ["Nyheter medan börsen är stängd", "Att grafen är trasig", "Låg spread", "En trendlinje"]}, {"q": "Vad betyder det att ett gap stängs?", "o": ["Priset går tillbaka och fyller tomrummet", "Börsen stänger", "Gapet blir större", "Aktien tas bort från börsen"]}, {"q": "Varför är gap en risk för den som har stop-loss?", "o": ["Priset kan hoppa förbi stoppen", "Gap tar bort stop-loss", "Gap gör stoppen gratis", "Det är ingen risk"], "why": "Öppnar priset långt under din stopp säljs aktien till nästa tillgängliga pris, som kan vara mycket lägre."}, {"m": [["Gap", "Tomrum i grafen"], ["Gap uppåt", "Öppnar över gårdagens högsta"], ["Gap nedåt", "Öppnar under gårdagens lägsta"], ["Stängt gap", "Priset fyller tomrummet"]]}]}, "x21": {"t": "Fibonacci", "c": [{"t": "Rekyl", "d": "Efter en rörelse går priset ofta tillbaka en bit innan trenden fortsätter. Det kallas en rekyl.", "fig": "fib"}, {"t": "Fibonacci-nivåer", "d": "Många traders ritar ut nivåerna 38,2 %, 50 % och 61,8 % av rörelsen. De används som möjliga stöd under en rekyl.", "fig": "fib"}, {"t": "Ingen magi", "d": "Nivåerna fungerar delvis för att så många tittar på dem. Se dem som zoner att vara uppmärksam på, inte som exakta löften."}], "q": [{"q": "Vilken av dessa är en vanlig Fibonacci-nivå?", "o": ["61,8 %", "73 %", "12 %", "99 %"]}, {"q": "Priset steg från 100 till 120 kr. Var ligger 50 %-rekylen?", "o": ["110 kr", "105 kr", "115 kr", "100 kr"], "why": "Rörelsen är 20 kr. Hälften är 10 kr, och 120 − 10 = 110 kr."}, {"q": "Vad är en rekyl?", "o": ["När priset går tillbaka en bit i trenden", "När företaget köper tillbaka aktier", "Ett gap", "En avgift"]}, {"q": "Hur bör man se på Fibonacci-nivåer?", "o": ["Som zoner att vara uppmärksam på", "Som garanterade vändpunkter", "Som avgifter", "Som nyheter"]}, {"m": [["Rekyl", "Priset går tillbaka en bit"], ["38,2 %", "Grund rekyl"], ["61,8 %", "Djup rekyl"], ["50 %", "Halva rörelsen"]]}]}, "x22": {"t": "Pivotpunkter och jämna nivåer", "c": [{"t": "Jämna tal", "d": "Jämna priser som 100 kr eller 50 kr fungerar ofta som stöd eller motstånd, eftersom många lägger sina ordrar där.", "fig": "round"}, {"t": "Pivotpunkt", "d": "En pivotpunkt räknas fram från gårdagens högsta, lägsta och stängning: (H + L + C) ÷ 3. Den används som en mittpunkt för dagen."}, {"t": "Gårdagens nivåer", "d": "Gårdagens högsta och lägsta pris är nivåer som många daytraders håller koll på."}], "q": [{"q": "Gårdagens högsta var 110, lägsta 100 och stängning 105. Vad är pivotpunkten?", "o": ["105", "110", "100", "315"], "why": "(110 + 100 + 105) ÷ 3 = 315 ÷ 3 = 105."}, {"q": "Varför kan 100 kr bli en viktig nivå?", "o": ["Många lägger ordrar vid jämna tal", "Börsen bestämmer det", "Det är en avgift", "Det står i lagen"]}, {"q": "Vilka priser används för att räkna pivotpunkten?", "o": ["Högsta, lägsta och stängning", "Bara öppningen", "Volym och spread", "Bara stängningen"]}, {"q": "Är pivotpunkter en garanti för att priset vänder?", "o": ["Nej, de är nivåer att vara uppmärksam på", "Ja, alltid", "Bara på fredagar", "Ja, om volymen är låg"]}, {"m": [["Pivotpunkt", "(H + L + C) ÷ 3"], ["Jämnt tal", "Till exempel 100 kr"], ["Gårdagens högsta", "Nivå som många bevakar"], ["Mittpunkt", "Dagens referensnivå"]]}]}, "x23": {"t": "EMA och SMA", "c": [{"t": "SMA", "d": "SMA är ett enkelt glidande medelvärde. Alla dagar i perioden väger lika mycket.", "fig": "ma"}, {"t": "EMA", "d": "EMA är ett exponentiellt glidande medelvärde. Nyare priser väger tyngre, så linjen reagerar snabbare än en SMA."}, {"t": "Korsningar", "d": "När ett kort medelvärde korsar över ett långt, till exempel 50 över 200 dagar, kallas det ofta gyllene kors. Korsar det under kallas det dödskors."}], "q": [{"q": "Vilket medelvärde reagerar snabbast på nya priser?", "o": ["EMA", "SMA", "Båda lika", "Inget av dem"], "why": "EMA ger de senaste priserna mer vikt och vänder därför snabbare."}, {"q": "50-dagars medelvärdet korsar över 200-dagars. Vad kallas det ofta?", "o": ["Gyllene kors", "Dödskors", "Doji", "Gap"]}, {"q": "Hur väger SMA dagarna i perioden?", "o": ["Alla dagar lika mycket", "Nyaste dagen mest", "Äldsta dagen mest", "Bara fredagar"]}, {"q": "Varför släpar alla medelvärden efter priset?", "o": ["De räknas på gamla priser", "De är felräknade", "De visar framtiden", "De bygger på volym"]}, {"m": [["SMA", "Alla dagar väger lika"], ["EMA", "Nya priser väger tyngre"], ["Gyllene kors", "Kort medelvärde korsar över långt"], ["Dödskors", "Kort medelvärde korsar under långt"]]}]}, "x24": {"t": "MACD", "c": [{"t": "MACD-linjen", "d": "MACD-linjen är skillnaden mellan två EMA, oftast 12 och 26 perioder. Är den över noll ligger det korta medelvärdet över det långa."}, {"t": "Signallinjen", "d": "Signallinjen är ett medelvärde av MACD-linjen, oftast 9 perioder. När MACD korsar över signallinjen ses det som ökande styrka uppåt."}, {"t": "Histogrammet", "d": "Histogrammet visar avståndet mellan MACD och signallinjen. Växande staplar betyder att rörelsen får mer fart."}], "q": [{"q": "Vilka två medelvärden används oftast i MACD?", "o": ["12 och 26 perioder", "5 och 500 perioder", "1 och 2 perioder", "50 och 200 år"]}, {"q": "MACD korsar över signallinjen. Hur tolkas det ofta?", "o": ["Som ökande styrka uppåt", "Som en garanterad vinst", "Som ökande styrka nedåt", "Som att börsen stänger"]}, {"q": "Vad visar MACD-histogrammet?", "o": ["Avståndet mellan MACD och signallinjen", "Volymen", "Utdelningen", "Spreaden"]}, {"q": "MACD-linjen ligger över noll. Vad betyder det?", "o": ["Det korta medelvärdet ligger över det långa", "Aktien är gratis", "Volymen är noll", "Priset måste falla"]}, {"m": [["MACD-linje", "Skillnaden mellan två EMA"], ["Signallinje", "Medelvärde av MACD"], ["Histogram", "Avståndet mellan linjerna"], ["Nollinjen", "Där medelvärdena är lika"]]}]}, "x25": {"t": "Bollingerband", "c": [{"t": "Tre linjer", "d": "Bollingerband har en mittlinje, ofta ett 20-dagars medelvärde, och ett band över och under. Banden ligger oftast två standardavvikelser från mitten."}, {"t": "Smala och breda band", "d": "Breda band betyder att priset svänger mycket. Smala band betyder lugn, och efter lugn kommer ofta en större rörelse."}, {"t": "Vid bandkanten", "d": "Att priset rör det övre bandet är ingen säljsignal i sig. I en stark trend kan priset gå längs bandet länge."}], "q": [{"q": "Vad är mittlinjen i Bollingerband oftast?", "o": ["Ett 20-dagars medelvärde", "Volymen", "Gårdagens högsta", "RSI"]}, {"q": "Banden blir väldigt smala. Vad kan det betyda?", "o": ["Lugn som ofta följs av en större rörelse", "Att aktien slutar handlas", "Att priset garanterat stiger", "Ingenting"]}, {"q": "Priset rör det övre bandet i en stark upptrend. Vad gäller?", "o": ["Det är ingen säljsignal i sig", "Sälj alltid direkt", "Köp med hävstång", "Bandet är trasigt"]}, {"q": "Vad mäter avståndet mellan banden?", "o": ["Hur mycket priset svänger", "Hur många ägare aktien har", "Utdelningen", "Courtaget"]}, {"m": [["Mittlinje", "Ofta 20-dagars medelvärde"], ["Breda band", "Priset svänger mycket"], ["Smala band", "Lugn innan rörelse"], ["Standardavvikelse", "Mått på spridning"]]}]}, "x26": {"t": "Stokastisk oscillator", "c": [{"t": "Stokastisk", "d": "Den stokastiska oscillatorn jämför stängningen med intervallet för de senaste perioderna, ofta 14. Den går från 0 till 100."}, {"t": "80 och 20", "d": "Över 80 kallas ofta överköpt och under 20 översålt. Precis som med RSI kan värdet ligga högt länge i en stark trend."}, {"t": "%K och %D", "d": "Oscillatorn har två linjer. %K är den snabba och %D är ett medelvärde av %K. Korsningar mellan dem används som signaler."}], "q": [{"q": "Den stokastiska oscillatorn visar 88. Hur beskrivs det oftast?", "o": ["Överköpt", "Översålt", "Neutralt", "Ogiltigt"]}, {"q": "Vad jämför den stokastiska oscillatorn?", "o": ["Stängningen med de senaste periodernas intervall", "Två företags vinster", "Volym och spread", "Räntan och inflationen"]}, {"q": "Vilken linje är den snabba i den stokastiska oscillatorn?", "o": ["%K", "%D", "Signallinjen", "Mittlinjen"]}, {"q": "Vilken skala har den stokastiska oscillatorn?", "o": ["0 till 100", "−1 till 1", "0 till 10", "Obegränsad"]}, {"m": [["Över 80", "Överköpt"], ["Under 20", "Översålt"], ["%K", "Snabba linjen"], ["%D", "Medelvärde av %K"]]}]}, "x27": {"t": "ATR och volatilitet", "c": [{"t": "Volatilitet", "d": "Volatilitet betyder hur mycket och hur snabbt priset svänger. Hög volatilitet ger större chanser, men också större risk."}, {"t": "ATR", "d": "ATR, Average True Range, är det genomsnittliga intervallet per period, ofta över 14 perioder. Den mäter hur mycket priset rör sig, inte åt vilket håll."}, {"t": "Stopp med ATR", "d": "Många lägger stop-loss en eller två ATR från köppriset. Då hamnar stoppen utanför det vanliga bruset."}], "q": [{"q": "Vad mäter ATR?", "o": ["Hur mycket priset rör sig", "Åt vilket håll priset går", "Utdelningen", "Antalet aktier"]}, {"q": "ATR är 2 kr och du köper på 50 kr. Var hamnar en stopp på 2 ATR?", "o": ["46 kr", "48 kr", "52 kr", "44 kr"], "why": "2 ATR = 2 × 2 = 4 kr. 50 − 4 = 46 kr."}, {"q": "Vad betyder hög volatilitet?", "o": ["Priset svänger mycket", "Priset står still", "Aktien är säker", "Spreaden är noll"]}, {"q": "Varför används ATR för att sätta stopp?", "o": ["Så att stoppen hamnar utanför vanligt brus", "Så att man aldrig förlorar", "För att slippa courtage", "För att det är lag"]}, {"m": [["Volatilitet", "Hur mycket priset svänger"], ["ATR", "Genomsnittligt intervall"], ["2 ATR-stopp", "Stopp två intervall bort"], ["Brus", "Vanliga små svängningar"]]}]}, "x28": {"t": "Volymindikatorer", "c": [{"t": "Volym bekräftar", "d": "En rörelse på hög volym visar att många är med. En rörelse på låg volym är lättare att vända.", "fig": "volume"}, {"t": "OBV", "d": "OBV, On-Balance Volume, lägger till dagens volym när priset stiger och drar ifrån den när priset faller. Stigande OBV visar att köpare dominerar."}, {"t": "VWAP", "d": "VWAP är dagens genomsnittspris vägt efter volym. Många daytraders och fonder ser det som dagens rättvisa pris."}], "q": [{"q": "Priset stiger. Vad gör OBV med dagens volym?", "o": ["Lägger till den", "Drar ifrån den", "Ignorerar den", "Delar den med två"]}, {"q": "Vad är VWAP?", "o": ["Dagens snittpris vägt efter volym", "Gårdagens stängning", "En avgift", "Ett mönster med tre ljus"]}, {"q": "Ett utbrott sker på mycket låg volym. Vad gäller?", "o": ["Var försiktig, få står bakom det", "Det är extra säkert", "Volym spelar ingen roll", "Priset måste stiga"]}, {"q": "Vad visar ett stigande OBV?", "o": ["Att köpare dominerar", "Att säljare dominerar", "Att ingen handlar", "Att aktien ger utdelning"]}, {"m": [["OBV", "Volym plus eller minus"], ["VWAP", "Volymvägt snittpris"], ["Hög volym", "Många är med"], ["Låg volym", "Lätt att vända"]]}]}, "x29": {"t": "Divergens", "c": [{"t": "Divergens", "d": "Divergens är när priset och en indikator går åt olika håll. Det kan vara ett tidigt tecken på att rörelsen tappar kraft.", "fig": "rsi"}, {"t": "Negativ divergens", "d": "Priset gör en ny topp, men RSI gör en lägre topp. Köpkraften har minskat trots att priset stigit."}, {"t": "Positiv divergens", "d": "Priset gör en ny botten, men RSI gör en högre botten. Säljtrycket har minskat. Det är en varning, inte en köpsignal i sig."}], "q": [{"q": "Priset gör ny topp men RSI gör en lägre topp. Vad kallas det?", "o": ["Negativ divergens", "Positiv divergens", "Gyllene kors", "Gap"]}, {"q": "Vad kan divergens vara ett tecken på?", "o": ["Att rörelsen tappar kraft", "Att rörelsen blir garanterat starkare", "Att börsen stänger", "Ingenting"]}, {"q": "Är positiv divergens en köpsignal i sig?", "o": ["Nej, en varning som behöver bekräftas", "Ja, köp allt direkt", "Ja, men bara med hävstång", "Det beror på vädret"]}, {"q": "Vid positiv divergens, vad gör RSI?", "o": ["Gör en högre botten", "Gör en lägre botten", "Står still på 50", "Försvinner"]}, {"m": [["Divergens", "Pris och indikator går isär"], ["Negativ divergens", "Ny pristopp, lägre RSI-topp"], ["Positiv divergens", "Ny prisbotten, högre RSI-botten"], ["Bekräftelse", "Priset vänder på riktigt"]]}]}, "x30": {"t": "Ichimoku", "c": [{"t": "Ichimoku", "d": "Ichimoku är ett japanskt system med flera linjer som visar trend, stöd och motstånd på en gång. Det ser rörigt ut först men följer tydliga regler."}, {"t": "Molnet", "d": "Molnet är ett färgat område mellan två linjer. Pris över molnet tolkas som positiv trend och pris under som negativ. Molnet fungerar också som stöd eller motstånd."}, {"t": "Tenkan och Kijun", "d": "Tenkan är en snabb linje, ofta 9 perioder, och Kijun en långsammare, ofta 26 perioder. Deras korsningar används som signaler, ungefär som medelvärden."}], "q": [{"q": "Priset ligger över molnet. Hur tolkas det ofta?", "o": ["Som en positiv trend", "Som en negativ trend", "Som att aktien är gratis", "Som ett fel"]}, {"q": "Vilket land kommer Ichimoku från?", "o": ["Japan", "Sverige", "USA", "Brasilien"]}, {"q": "Vilken Ichimoku-linje är den snabbaste?", "o": ["Tenkan", "Kijun", "Molnet", "Volymen"]}, {"q": "Vad kan molnet fungera som?", "o": ["Stöd eller motstånd", "En avgift", "En utdelning", "Ett orderslag"]}, {"m": [["Molnet", "Område mellan två linjer"], ["Tenkan", "Snabb linje"], ["Kijun", "Långsam linje"], ["Pris över molnet", "Positiv trend"]]}]}, "x31": {"t": "ADX och trendstyrka", "c": [{"t": "ADX", "d": "ADX mäter hur stark en trend är på en skala från 0 till 100. Den säger inte om trenden går upp eller ner."}, {"t": "Över 25", "d": "Ett ADX över ungefär 25 tolkas ofta som en tydlig trend. Under ungefär 20 rör sig priset oftast utan tydlig riktning."}, {"t": "+DI och −DI", "d": "Riktningen visas av två linjer. När +DI ligger över −DI dominerar köparna, och tvärtom."}], "q": [{"q": "Vad mäter ADX?", "o": ["Hur stark trenden är", "Åt vilket håll trenden går", "Utdelningen", "Spreaden"]}, {"q": "ADX är 35. Hur tolkas det ofta?", "o": ["Som en tydlig trend", "Som ingen trend alls", "Som en säljsignal", "Som ett fel"]}, {"q": "+DI ligger över −DI. Vem dominerar?", "o": ["Köparna", "Säljarna", "Ingen", "Mäklaren"]}, {"q": "ADX är 15. Vilken strategi passar ofta sämst?", "o": ["Trendföljning", "Att vänta", "Att handla i intervallet", "Att läsa på"], "why": "Ett lågt ADX betyder svag eller ingen trend, och då har trendföljare svårt att tjäna pengar."}, {"m": [["ADX", "Trendens styrka"], ["+DI", "Köparnas kraft"], ["−DI", "Säljarnas kraft"], ["Under 20", "Ingen tydlig trend"]]}]}, "x32": {"t": "Kombinera indikatorer", "c": [{"t": "Mindre är mer", "d": "Många indikatorer på samma graf gör det svårare att se, inte lättare. Två eller tre väl valda räcker oftast."}, {"t": "Olika sorter", "d": "Kombinera indikatorer som mäter olika saker: en för trend, en för styrka och kanske volym. RSI och stokastisk mäter nästan samma sak."}, {"t": "Priset först", "d": "Alla indikatorer räknas på priset och släpar efter. Titta alltid först på själva priset och nivåerna."}], "q": [{"q": "Vilka två indikatorer mäter nästan samma sak?", "o": ["RSI och stokastisk", "Volym och medelvärde", "ADX och OBV", "Pris och utdelning"]}, {"q": "Vilken kombination är bäst balanserad?", "o": ["Medelvärde, RSI och volym", "RSI, stokastisk och en till oscillator", "Tio olika medelvärden", "Inga alls, bara känsla"]}, {"q": "Varför ska man titta på priset först?", "o": ["Indikatorerna räknas på priset och släpar", "Priset ljuger alltid", "Indikatorer visar framtiden", "Det är billigare"]}, {"q": "Grafen har åtta indikatorer och du blir förvirrad. Vad är klokt?", "o": ["Ta bort de flesta och behåll två eller tre", "Lägg till fler", "Handla på slump", "Sluta titta på priset"]}, {"m": [["Trend", "Till exempel medelvärde"], ["Styrka", "Till exempel RSI"], ["Volym", "Till exempel OBV"], ["Släpar efter", "Bygger på gamla priser"]]}]}, "x33": {"t": "Fler ordertyper", "c": [{"t": "Stopporder", "d": "En stopporder ligger vilande tills priset når din nivå. Då blir den en marknadsorder och genomförs till nästa tillgängliga pris."}, {"t": "Stop-limit", "d": "En stop-limit blir en limitorder när nivån nås. Du får aldrig sämre pris än din gräns, men om priset hoppar förbi kanske ordern inte genomförs alls."}, {"t": "Trailing stop", "d": "En trailing stop följer med när priset stiger, med ett fast avstånd. Faller priset ligger stoppen kvar. Den skyddar vinster som redan finns."}], "q": [{"q": "Vad händer när priset når nivån för en vanlig stopporder?", "o": ["Den blir en marknadsorder", "Den raderas", "Den blir en utdelning", "Ingenting"]}, {"q": "Vad är risken med en stop-limit?", "o": ["Ordern kanske inte genomförs alls", "Du får alltid sämre pris", "Den kostar inget", "Den gäller bara på helger"]}, {"q": "Du köper på 100 kr med en trailing stop på 5 kr. Priset stiger till 120 kr. Var ligger stoppen?", "o": ["115 kr", "95 kr", "100 kr", "125 kr"], "why": "Stoppen följer med uppåt och ligger 5 kr under högsta priset: 120 − 5 = 115 kr."}, {"q": "Vad gör en trailing stop när priset faller?", "o": ["Ligger kvar", "Följer med nedåt", "Försvinner", "Köper fler aktier"]}, {"m": [["Stopporder", "Blir marknadsorder vid nivån"], ["Stop-limit", "Blir limitorder vid nivån"], ["Trailing stop", "Följer med uppåt"], ["Take profit", "Säljer vid vinstmålet"]]}]}, "x34": {"t": "Orderboken", "c": [{"t": "Orderbok", "d": "Orderboken är en lista över alla köp- och säljordrar som väntar på olika priser. Köparna står på ena sidan och säljarna på den andra."}, {"t": "Djup", "d": "Djupet visar hur många aktier som finns på varje pris. En djup orderbok kan ta emot stora ordrar utan att priset rör sig mycket."}, {"t": "Tunn orderbok", "d": "I en tunn orderbok finns få ordrar. Då kan en enda stor order flytta priset mycket. Det är vanligt i små bolag."}], "q": [{"q": "Vad visar orderboken?", "o": ["Väntande köp- och säljordrar", "Företagets vinst", "Gamla nyheter", "Skatten"]}, {"q": "Varför kan priset hoppa mycket i ett litet bolag?", "o": ["Orderboken är tunn", "Börsen är stängd", "Spreaden är noll", "Det finns för många köpare"]}, {"q": "Vad betyder det att en orderbok är djup?", "o": ["Många aktier väntar nära priset", "Priset är mycket lågt", "Aktien är förbjuden", "Ingen vill handla"]}, {"q": "Vad händer om du lägger en stor marknadsorder i en tunn orderbok?", "o": ["Du kan få allt sämre priser", "Du får alltid bästa pris", "Ordern blir gratis", "Inget händer"], "why": "Ordern äter sig igenom flera prisnivåer, och varje nivå är sämre än den förra."}, {"m": [["Orderbok", "Lista med väntande ordrar"], ["Djup", "Antal aktier per pris"], ["Likviditet", "Lätt att köpa och sälja"], ["Tunn orderbok", "Få ordrar"]]}]}, "x35": {"t": "Slippage och gap-risk", "c": [{"t": "Slippage", "d": "Slippage är skillnaden mellan priset du väntade dig och priset du faktiskt fick. Det är vanligt när det går fort eller när det finns få ordrar."}, {"t": "Gap-risk", "d": "När börsen är stängd kan nyheter komma. Nästa morgon kan priset öppna långt från gårdagens stängning, och din stopp kan hoppas över.", "fig": "gap"}, {"t": "Minska risken", "d": "Mindre positioner, limitordrar och att undvika att hålla stora positioner över viktiga nyheter minskar risken."}], "q": [{"q": "Du ville köpa på 50 kr men fick 50,40 kr. Hur stor var slippagen?", "o": ["0,40 kr", "50 kr", "4 kr", "0 kr"]}, {"q": "När är slippage vanligast?", "o": ["När det går fort eller finns få ordrar", "När allt är lugnt och likvitt", "Bara på måndagar", "Aldrig"]}, {"q": "Vilken order skyddar bäst mot slippage när du köper?", "o": ["Limitorder", "Marknadsorder", "Stopporder", "Ingen order"]}, {"q": "Varför kan nyheter på natten vara farliga för en stop-loss?", "o": ["Priset kan öppna förbi stoppen", "Stoppen raderas på natten", "Börsen höjer stoppen", "Det är inte farligt"]}, {"m": [["Slippage", "Annat pris än väntat"], ["Gap-risk", "Priset hoppar över natten"], ["Limitorder", "Skyddar priset"], ["Mindre position", "Mindre skada vid hopp"]]}]}, "x36": {"t": "Börsens öppettider", "c": [{"t": "Stockholmsbörsen", "d": "Stockholmsbörsen har öppet vardagar ungefär 09.00–17.30 svensk tid. Utanför de tiderna handlas inte aktierna där."}, {"t": "Auktioner", "d": "Börsdagen börjar och slutar ofta med en auktion. Då samlas ordrar och matchas till ett gemensamt pris, öppningskursen eller stängningskursen."}, {"t": "USA-börserna", "d": "De stora amerikanska börserna har oftast öppet 15.30–22.00 svensk tid. När sommartiden byter olika datum kan det skilja en timme några veckor."}], "q": [{"q": "Ungefär när har Stockholmsbörsen öppet?", "o": ["09.00–17.30", "Dygnet runt", "12.00–13.00", "Bara på helger"]}, {"q": "Vad händer i en stängningsauktion?", "o": ["Ordrar samlas och matchas till ett gemensamt pris", "Aktierna lottas ut", "Alla ordrar raderas", "Priset bestäms av staten"]}, {"q": "Varför uppstår gap på morgonen?", "o": ["Nyheter kom medan börsen var stängd", "Börsen glömmer gårdagen", "Alla säljer på morgonen", "Det är ett fel i grafen"]}, {"q": "Ungefär när öppnar de stora börserna i USA i svensk tid?", "o": ["15.30", "09.00", "06.00", "23.00"]}, {"m": [["Öppningsauktion", "Dagens första pris"], ["Stängningsauktion", "Dagens sista pris"], ["Stockholm", "Ungefär 09.00–17.30"], ["USA", "Oftast 15.30–22.00"]]}]}, "x37": {"t": "Market makers", "c": [{"t": "Market maker", "d": "En market maker, eller likviditetsgarant, lägger hela tiden både köp- och säljkurser. Då finns det alltid någon att handla med."}, {"t": "Spreaden som lön", "d": "Market makern tjänar ofta på spreaden: köper lite billigare och säljer lite dyrare. Därför är spreaden en kostnad för dig."}, {"t": "Var de finns", "d": "Market makers är vanliga i mindre aktier, certifikat och fonder som handlas på börsen. Utan dem skulle det ibland vara svårt att handla alls."}], "q": [{"q": "Vad gör en market maker?", "o": ["Lägger både köp- och säljkurser", "Bestämmer räntan", "Skriver nyheter", "Ger ut aktier"]}, {"q": "Hur tjänar en market maker ofta pengar?", "o": ["På spreaden", "På utdelningar", "På skatter", "På reklam"]}, {"q": "Var är market makers extra vanliga?", "o": ["I mindre aktier och certifikat", "I sparkonton", "I kontanter", "I pensionsbrev"]}, {"q": "Varför är spreaden en kostnad för dig?", "o": ["Du köper högre och säljer lägre än mittpriset", "Den dras på skatten", "Den är inte en kostnad", "Den betalas av staten"]}, {"m": [["Market maker", "Lägger köp- och säljkurser"], ["Likviditetsgarant", "Annat ord för market maker"], ["Spread", "Market makerns lön"], ["Certifikat", "Har ofta en market maker"]]}]}, "x38": {"t": "Hävstång och marginal", "c": [{"t": "Hävstång", "d": "Med hävstång handlar du för mer pengar än du har. Med tio gånger hävstång gör en rörelse på 10 % att du vinner eller förlorar hela insatsen."}, {"t": "Marginal", "d": "Marginalen är pengarna du måste ha som säkerhet för att få låna. Lånet kostar ränta."}, {"t": "Marginalkrav", "d": "Faller värdet för mycket kräver mäklaren att du sätter in mer pengar. Gör du inte det kan positionen säljas av, ofta på ett dåligt pris."}], "q": [{"q": "Du har 1 000 kr och tio gånger hävstång. Hur stor position kan du ta?", "o": ["10 000 kr", "1 000 kr", "100 kr", "100 000 kr"]}, {"q": "Med tio gånger hävstång faller priset 10 %. Vad händer med insatsen?", "o": ["Den är borta", "Den minskar 1 %", "Den växer", "Inget händer"], "why": "10 % × 10 = 100 %. Hela insatsen försvinner."}, {"q": "Vad är ett marginalkrav?", "o": ["Krav på att sätta in mer pengar", "En bonus från mäklaren", "En utdelning", "En skatteåterbäring"]}, {"q": "Vad kostar det att låna till hävstång?", "o": ["Ränta", "Ingenting", "En aktie per dag", "Bara courtage"]}, {"m": [["Hävstång", "Förstärker vinst och förlust"], ["Marginal", "Säkerhet för lånet"], ["Marginalkrav", "Sätt in mer pengar"], ["Ränta", "Kostnaden för lånet"]]}]}, "x39": {"t": "Blankning", "c": [{"t": "Blankning", "d": "Att blanka betyder att låna aktier, sälja dem direkt och senare köpa tillbaka dem. Faller priset däremellan blir det vinst."}, {"t": "Obegränsad risk", "d": "En aktie kan bara falla till noll, men den kan stiga hur mycket som helst. Därför är förlustrisken vid blankning i teorin obegränsad."}, {"t": "Short squeeze", "d": "Om priset stiger snabbt måste många blankare köpa tillbaka samtidigt. Det kan pressa priset ännu högre. Det kallas short squeeze."}], "q": [{"q": "När tjänar en blankare pengar?", "o": ["När priset faller", "När priset stiger", "När priset står still", "Aldrig"]}, {"q": "Varför är blankning extra riskabelt?", "o": ["Priset kan stiga hur mycket som helst", "Priset kan bara stiga lite", "Det är förbjudet", "Det finns ingen risk"]}, {"q": "Vad är en short squeeze?", "o": ["Blankare tvingas köpa tillbaka och priset rusar", "En sorts utdelning", "När börsen stänger tidigt", "En lugn dag"]}, {"q": "Vad måste du göra för att blanka en aktie?", "o": ["Låna aktien först", "Äga den i tio år", "Jobba på företaget", "Ingenting särskilt"]}, {"m": [["Blanka", "Sälja lånade aktier"], ["Täcka", "Köpa tillbaka aktierna"], ["Short squeeze", "Tvingade återköp driver priset"], ["Lånekostnad", "Avgift för att låna aktier"]]}]}, "x40": {"t": "Utdelningar", "c": [{"t": "Utdelning", "d": "En utdelning är en del av företagets vinst som betalas ut till aktieägarna, ofta en eller några gånger per år."}, {"t": "X-dagen", "d": "På X-dagen handlas aktien utan rätt till utdelningen. Priset sjunker då ungefär lika mycket som utdelningen."}, {"t": "Inga gratispengar", "d": "Utdelningen kommer från företagets egna pengar. Därför blir du inte rikare bara av att utdelningen betalas ut."}], "q": [{"q": "Vad händer oftast med aktiekursen på X-dagen?", "o": ["Den sjunker ungefär med utdelningen", "Den stiger med utdelningen", "Den blir noll", "Den fördubblas"]}, {"q": "Aktien kostar 200 kr och delar ut 8 kr. Ungefär vad öppnar den på X-dagen?", "o": ["192 kr", "208 kr", "200 kr", "100 kr"], "why": "200 − 8 = 192 kr, allt annat lika."}, {"q": "Varifrån kommer utdelningen?", "o": ["Från företagets vinst", "Från börsen", "Från staten", "Från andra aktieägare"]}, {"q": "Måste alla företag dela ut pengar?", "o": ["Nej, många växande bolag behåller vinsten", "Ja, enligt lag", "Ja, varje månad", "Bara på fredagar"]}, {"m": [["Utdelning", "Del av vinsten till ägarna"], ["X-dag", "Aktien handlas utan utdelning"], ["Avstämningsdag", "Dag då ägarna räknas"], ["Direktavkastning", "Utdelning delat med pris"]]}]}, "x41": {"t": "Splittar och emissioner", "c": [{"t": "Split", "d": "Vid en split delas varje aktie i flera. Vid 2:1 får du dubbelt så många aktier till halva priset. Värdet du äger är detsamma."}, {"t": "Omvänd split", "d": "Vid en omvänd split slås flera aktier ihop till en. Det görs ofta när priset har blivit mycket lågt."}, {"t": "Nyemission", "d": "Vid en nyemission ger företaget ut nya aktier för att få in pengar. Varje gammal aktie blir då en mindre del av företaget, det kallas utspädning."}], "q": [{"q": "Du har 10 aktier à 100 kr. Det blir en split 2:1. Vad har du sedan?", "o": ["20 aktier à 50 kr", "20 aktier à 100 kr", "10 aktier à 50 kr", "5 aktier à 200 kr"], "why": "Antalet dubblas och priset halveras. 10 × 100 = 20 × 50 = 1 000 kr."}, {"q": "Blir du rikare av en split?", "o": ["Nej, värdet är detsamma", "Ja, dubbelt så rik", "Ja, alltid lite", "Nej, du förlorar hälften"]}, {"q": "Vad är utspädning?", "o": ["Varje aktie blir en mindre del av företaget", "Aktien blir värd mer", "Företaget går i konkurs", "Spreaden försvinner"]}, {"q": "Varför gör företag en nyemission?", "o": ["För att få in pengar", "För att sänka skatten", "För att stänga börsen", "För skojs skull"]}, {"m": [["Split", "Fler aktier, lägre pris"], ["Omvänd split", "Färre aktier, högre pris"], ["Nyemission", "Nya aktier för nya pengar"], ["Utspädning", "Mindre del per aktie"]]}]}, "x42": {"t": "Börsens aktörer", "c": [{"t": "Privatpersoner och fonder", "d": "På börsen handlar både privatpersoner och stora aktörer som fonder, pensionsbolag och banker. De stora står för det mesta av handeln."}, {"t": "Algoritmer", "d": "En stor del av handeln görs av datorer som följer regler, ibland tusentals affärer per sekund. Det kallas algoritmhandel."}, {"t": "Insynshandel", "d": "Personer med insyn i ett företag, som chefer och styrelse, måste rapportera sina affärer i aktien. Att handla på hemlig information är förbjudet."}], "q": [{"q": "Vem står för det mesta av handeln på börsen?", "o": ["Stora aktörer som fonder och banker", "Skolbarn", "Bara privatpersoner", "Staten ensam"]}, {"q": "Vad är algoritmhandel?", "o": ["Datorer som handlar efter regler", "Att handla med papper och penna", "En sorts utdelning", "Att handla bara på fredagar"]}, {"q": "Vad är förbjudet?", "o": ["Att handla på hemlig information", "Att köpa aktier", "Att läsa rapporter", "Att använda stop-loss"]}, {"q": "Vilka måste rapportera sina affärer i bolagets aktie?", "o": ["Chefer och styrelse med insyn", "Alla kunder i butiken", "Ingen", "Bara utländska ägare"]}, {"m": [["Institution", "Stor aktör som en fond"], ["Algoritm", "Dator som följer regler"], ["Insider", "Person med insyn i bolaget"], ["Insiderbrott", "Handla på hemlig information"]]}]}, "x43": {"t": "Resultaträkningen", "c": [{"t": "Intäkter och kostnader", "d": "Resultaträkningen visar vad företaget har sålt för, intäkterna, och vad det har kostat. Det som blir kvar är resultatet."}, {"t": "Rörelseresultat", "d": "Rörelseresultatet, även kallat EBIT, är vinsten från själva verksamheten innan räntor och skatt."}, {"t": "Vinst per aktie", "d": "Vinst per aktie är nettoresultatet efter skatt delat med antalet aktier. Det visar hur mycket vinst varje aktie står för."}], "q": [{"q": "Nettoresultatet är 100 miljoner kr och det finns 50 miljoner aktier. Vad är vinsten per aktie?", "o": ["2 kr", "50 kr", "0,5 kr", "150 kr"], "why": "100 ÷ 50 = 2 kr per aktie."}, {"q": "Vad är rörelseresultat?", "o": ["Vinsten från verksamheten före räntor och skatt", "Pengarna på banken", "Aktiens pris", "Antalet anställda"]}, {"q": "Vad visar resultaträkningen?", "o": ["Intäkter, kostnader och resultat", "Vem som äger företaget", "Börsens öppettider", "Aktiens graf"]}, {"q": "Ett företag säljer för 500 och har kostnader på 420. Vad blir resultatet?", "o": ["80", "920", "420", "−80"]}, {"m": [["Intäkter", "Det företaget säljer för"], ["Rörelseresultat", "Vinst före räntor och skatt"], ["Nettoresultat", "Vinst efter skatt"], ["Vinst per aktie", "Nettoresultat delat med antal aktier"]]}]}, "x44": {"t": "Balansräkningen", "c": [{"t": "Tillgångar och skulder", "d": "Balansräkningen visar vad företaget äger, tillgångarna, och vad det är skyldigt, skulderna, vid ett visst datum."}, {"t": "Eget kapital", "d": "Eget kapital är tillgångarna minus skulderna. Det är den del som tillhör ägarna. Tillgångar = skulder + eget kapital."}, {"t": "Soliditet", "d": "Soliditet är eget kapital delat med totala tillgångar. Hög soliditet betyder att företaget har lite skulder och tål motgångar bättre."}], "q": [{"q": "Tillgångar 1 000 och skulder 600. Vad är eget kapital?", "o": ["400", "1 600", "600", "0"], "why": "1 000 − 600 = 400."}, {"q": "Eget kapital 400 och totala tillgångar 1 000. Vad är soliditeten?", "o": ["40 %", "60 %", "4 %", "250 %"]}, {"q": "Vad betyder hög soliditet?", "o": ["Lite skulder i förhållande till tillgångarna", "Mycket skulder", "Höga utdelningar", "Snabb tillväxt"]}, {"q": "Vilken likhet stämmer alltid i balansräkningen?", "o": ["Tillgångar = skulder + eget kapital", "Tillgångar = intäkter", "Skulder = vinst", "Eget kapital = aktiekurs"]}, {"m": [["Tillgångar", "Det företaget äger"], ["Skulder", "Det företaget är skyldigt"], ["Eget kapital", "Ägarnas del"], ["Soliditet", "Eget kapital delat med tillgångar"]]}]}, "x45": {"t": "Kassaflödet", "c": [{"t": "Kassaflöde", "d": "Kassaflödet visar hur mycket pengar som faktiskt kommer in och går ut. Ett företag kan visa vinst men ändå ha slut på pengar."}, {"t": "Operativt kassaflöde", "d": "Det operativa kassaflödet är pengarna som den vanliga verksamheten drar in. Det är ofta mer pålitligt än vinsten på papperet."}, {"t": "Fritt kassaflöde", "d": "Fritt kassaflöde är det operativa kassaflödet minus investeringarna. Det är pengarna som kan gå till utdelningar, återköp eller att betala skulder."}], "q": [{"q": "Operativt kassaflöde 300 och investeringar 120. Vad är det fria kassaflödet?", "o": ["180", "420", "120", "300"], "why": "300 − 120 = 180."}, {"q": "Kan ett företag visa vinst men ha slut på pengar?", "o": ["Ja, om pengarna inte kommer in i tid", "Nej, aldrig", "Bara på helger", "Bara om den har utdelning"], "why": "Vinsten räknas när något säljs, men kunden kanske betalar långt senare."}, {"q": "Vad kan fritt kassaflöde användas till?", "o": ["Utdelningar, återköp eller skuldbetalning", "Bara till skatt", "Ingenting", "Att höja aktiekursen direkt"]}, {"q": "Vilket mått är ofta mer pålitligt än vinsten på papperet?", "o": ["Operativt kassaflöde", "Antal anställda", "Logotypen", "Aktiens färg i grafen"]}, {"m": [["Kassaflöde", "Pengar in och ut"], ["Operativt kassaflöde", "Pengar från verksamheten"], ["Investeringar", "Pengar till maskiner och liknande"], ["Fritt kassaflöde", "Kvar efter investeringar"]]}]}, "x46": {"t": "P/E-tal", "c": [{"t": "P/E-tal", "d": "P/E-talet är aktiens pris delat med vinsten per aktie. P/E 20 betyder att du betalar 20 kr för varje krona i årlig vinst."}, {"t": "Högt och lågt P/E", "d": "Högt P/E betyder ofta att marknaden väntar sig stark tillväxt. Lågt P/E kan betyda att aktien är billig, eller att marknaden ser problem."}, {"t": "Jämför rätt", "d": "Jämför P/E med liknande företag i samma bransch. En bank och ett teknikbolag har ofta helt olika P/E."}], "q": [{"q": "Aktien kostar 150 kr och vinsten per aktie är 10 kr. Vad är P/E?", "o": ["15", "1 500", "160", "10"], "why": "150 ÷ 10 = 15."}, {"q": "Vad kan ett högt P/E betyda?", "o": ["Att marknaden väntar sig stark tillväxt", "Att företaget saknar vinst helt", "Att aktien är gratis", "Att börsen är stängd"]}, {"q": "Är ett lågt P/E alltid ett fynd?", "o": ["Nej, marknaden kan se problem", "Ja, alltid", "Ja, om aktien är röd", "Bara i januari"]}, {"q": "Hur bör man jämföra P/E-tal?", "o": ["Med liknande företag i samma bransch", "Med väderprognosen", "Med alla företag i världen på en gång", "Man ska aldrig jämföra"]}, {"m": [["P/E", "Pris delat med vinst per aktie"], ["Högt P/E", "Höga förväntningar"], ["Lågt P/E", "Billig eller problem"], ["Bransch", "Jämför inom samma"]]}]}, "x47": {"t": "Fler nyckeltal", "c": [{"t": "P/S-tal", "d": "P/S är aktiens pris delat med försäljningen per aktie. Det används ofta för företag som ännu inte går med vinst."}, {"t": "P/B-tal", "d": "P/B är priset delat med eget kapital per aktie. Ett P/B under 1 betyder att aktien kostar mindre än det bokförda värdet."}, {"t": "EV/EBIT", "d": "EV är företagets totala värde, börsvärdet plus skulder minus kassa. EV/EBIT jämför det med rörelseresultatet och tar hänsyn till skulderna."}], "q": [{"q": "Vilket nyckeltal passar för ett företag som ännu inte har vinst?", "o": ["P/S", "P/E", "Direktavkastning", "Utdelningsandel"]}, {"q": "Vad betyder ett P/B under 1?", "o": ["Aktien kostar mindre än bokfört värde", "Företaget har ingen skuld", "Aktien är förbjuden", "Vinsten är dubbel"]}, {"q": "Börsvärde 800, skulder 300 och kassa 100. Vad är EV?", "o": ["1 000", "1 200", "800", "600"], "why": "800 + 300 − 100 = 1 000."}, {"q": "Varför används EV i stället för bara börsvärdet?", "o": ["EV tar hänsyn till skulder och kassa", "EV är alltid lägre", "EV visar utdelningen", "Det finns ingen skillnad"]}, {"m": [["P/S", "Pris mot försäljning"], ["P/B", "Pris mot eget kapital"], ["EV", "Börsvärde plus skulder minus kassa"], ["EV/EBIT", "Värde mot rörelseresultat"]]}]}, "x48": {"t": "Direktavkastning", "c": [{"t": "Direktavkastning", "d": "Direktavkastning är utdelningen delat med aktiens pris, i procent. Utdelning 5 kr och pris 100 kr ger 5 %."}, {"t": "Utdelningsandel", "d": "Utdelningsandelen är hur stor del av vinsten som delas ut. Delar ett företag ut mer än det tjänar kan utdelningen behöva sänkas."}, {"t": "Fällan", "d": "Hög direktavkastning kan bero på att priset har rasat för att företaget har problem. Kolla alltid varför avkastningen är hög."}], "q": [{"q": "Utdelning 6 kr och aktiepris 150 kr. Vad är direktavkastningen?", "o": ["4 %", "6 %", "25 %", "0,4 %"], "why": "6 ÷ 150 = 0,04, alltså 4 %."}, {"q": "Vinst per aktie 10 kr och utdelning 4 kr. Vad är utdelningsandelen?", "o": ["40 %", "4 %", "250 %", "14 %"]}, {"q": "Varför kan en mycket hög direktavkastning vara en varning?", "o": ["Priset kan ha rasat på grund av problem", "Det betyder alltid gratis pengar", "Det är olagligt", "Det är aldrig en varning"]}, {"q": "Ett företag delar ut 120 % av vinsten år efter år. Vad är risken?", "o": ["Utdelningen kan behöva sänkas", "Ingen risk alls", "Aktien delas automatiskt", "Skatten försvinner"]}, {"m": [["Direktavkastning", "Utdelning delat med pris"], ["Utdelningsandel", "Del av vinsten som delas ut"], ["Utdelningsfälla", "Hög avkastning på grund av problem"], ["Hållbar utdelning", "Täcks av vinsten"]]}]}, "x49": {"t": "Tillväxt och marginaler", "c": [{"t": "Tillväxt", "d": "Tillväxt visar hur mycket försäljningen eller vinsten ökar från ett år till nästa. Från 100 till 120 är en tillväxt på 20 %."}, {"t": "Rörelsemarginal", "d": "Rörelsemarginalen är rörelseresultatet delat med omsättningen. Den visar hur många ören av varje krona som blir vinst i verksamheten."}, {"t": "Stigande marginaler", "d": "När marginalerna stiger tjänar företaget mer på varje försäljning. Det är ofta ett tecken på styrka."}], "q": [{"q": "Försäljningen ökar från 200 till 250. Hur stor är tillväxten?", "o": ["25 %", "50 %", "20 %", "250 %"], "why": "Ökningen är 50. 50 ÷ 200 = 0,25, alltså 25 %."}, {"q": "Omsättning 1 000 och rörelseresultat 150. Vad är rörelsemarginalen?", "o": ["15 %", "150 %", "85 %", "1,5 %"]}, {"q": "Vad betyder stigande marginaler?", "o": ["Företaget tjänar mer på varje försäljning", "Företaget säljer mindre", "Aktien delas", "Skulderna ökar"]}, {"q": "Ett företag växer snabbt men marginalerna faller hela tiden. Vad bör man fundera på?", "o": ["Om tillväxten är lönsam", "Ingenting, tillväxt är allt", "Om logotypen är snygg", "Om börsen är öppen"]}, {"m": [["Tillväxt", "Ökning från förra året"], ["Omsättning", "Total försäljning"], ["Rörelsemarginal", "Rörelseresultat delat med omsättning"], ["Bruttomarginal", "Marginal före övriga kostnader"]]}]}, "x50": {"t": "Kvartalsrapporter", "c": [{"t": "Kvartalsrapport", "d": "Börsnoterade företag rapporterar sina siffror ungefär var tredje månad. Rapporterna berättar hur det går för verksamheten."}, {"t": "Förväntningar", "d": "Priset rör sig mest av överraskningen, alltså skillnaden mellan utfallet och vad marknaden väntade sig. En bra rapport kan få aktien att falla om den var sämre än väntat."}, {"t": "Prognos", "d": "Många företag ger en prognos för framtiden. Förändringar i prognosen kan påverka priset mer än själva siffrorna."}], "q": [{"q": "Hur ofta rapporterar börsbolag oftast?", "o": ["Ungefär var tredje månad", "Varje dag", "Vart tionde år", "Aldrig"]}, {"q": "Vinsten steg 10 %, men marknaden väntade sig 20 %. Vad kan hända med aktien?", "o": ["Den kan falla", "Den måste stiga", "Den slutar handlas", "Inget alls"], "why": "Priset reagerar på överraskningen. Sämre än väntat kan ge en nedgång även om siffrorna är bra."}, {"q": "Vad är en prognos?", "o": ["Företagets egen bedömning av framtiden", "Gårdagens pris", "En avgift", "En sorts order"]}, {"q": "Varför kan det vara riskabelt att hålla en stor position över en rapport?", "o": ["Priset kan hoppa kraftigt", "Rapporter sänker alltid priset", "Aktien raderas", "Det är inte riskabelt"]}, {"m": [["Kvartalsrapport", "Siffror var tredje månad"], ["Förväntning", "Det marknaden räknar med"], ["Överraskning", "Utfall minus förväntning"], ["Prognos", "Bedömning av framtiden"]]}]}, "x51": {"t": "Värdering", "c": [{"t": "Pris och värde", "d": "Priset är vad aktien kostar just nu. Värdet är vad företaget egentligen är värt. De två kan skilja sig mycket under lång tid."}, {"t": "Säkerhetsmarginal", "d": "Säkerhetsmarginal betyder att köpa en bra bit under det värde du räknat fram. Om du har räknat lite fel finns det ändå utrymme."}, {"t": "Framtida pengar", "d": "En krona om tio år är värd mindre än en krona i dag. Därför räknar man ner framtida kassaflöden till dagens värde. Metoden kallas DCF."}], "q": [{"q": "Du räknar fram att aktien är värd 100 kr. Vid vilket pris har du störst säkerhetsmarginal?", "o": ["70 kr", "95 kr", "100 kr", "120 kr"]}, {"q": "Vad är skillnaden mellan pris och värde?", "o": ["Pris är vad det kostar, värde vad det är värt", "Det finns ingen skillnad", "Värde är alltid högre", "Pris är alltid rätt"]}, {"q": "Varför är pengar i framtiden värda mindre än pengar i dag?", "o": ["Pengar i dag kan växa och framtiden är osäker", "Sedlar blir gamla", "Det är en lag", "Det är de inte"]}, {"q": "Vad kallas metoden där man räknar ner framtida kassaflöden?", "o": ["DCF", "RSI", "ATR", "VWAP"]}, {"m": [["Pris", "Vad aktien kostar nu"], ["Värde", "Vad företaget är värt"], ["Säkerhetsmarginal", "Köpa långt under värdet"], ["DCF", "Räkna ner framtida pengar"]]}]}, "x52": {"t": "Branscher och konjunktur", "c": [{"t": "Cykliska bolag", "d": "Cykliska bolag, som bilar, industri och råvaror, säljer mycket när ekonomin går bra och lite när den går dåligt."}, {"t": "Defensiva bolag", "d": "Defensiva bolag, som mat, läkemedel och el, säljer ungefär lika mycket oavsett läget. Folk behöver deras varor ändå."}, {"t": "Jämför inom branschen", "d": "Olika branscher har olika marginaler, tillväxt och nyckeltal. Jämför därför ett bolag med andra i samma bransch."}], "q": [{"q": "Vilket bolag är mest cykliskt?", "o": ["En biltillverkare", "En livsmedelskedja", "Ett elbolag", "Ett läkemedelsbolag"]}, {"q": "Varför klarar sig defensiva bolag bättre i en lågkonjunktur?", "o": ["Folk behöver deras varor ändå", "De betalar ingen skatt", "De har inga kunder", "De är förbjudna att falla"]}, {"q": "Vad är klokast när du bedömer ett bolags P/E?", "o": ["Jämföra med bolag i samma bransch", "Jämföra med en annan bransch", "Strunta i det", "Fråga sociala medier"]}, {"q": "Ekonomin går in i en högkonjunktur. Vilka bolag brukar gynnas mest?", "o": ["Cykliska bolag", "Defensiva bolag", "Inga bolag", "Bara banker i Japan"]}, {"m": [["Cykliskt", "Följer ekonomins svängningar"], ["Defensivt", "Stabilt i alla lägen"], ["Högkonjunktur", "Ekonomin går starkt"], ["Lågkonjunktur", "Ekonomin går svagt"]]}]}, "x53": {"t": "Räntor och centralbanker", "c": [{"t": "Styrränta", "d": "Centralbanken bestämmer styrräntan, som påverkar alla andra räntor. I Sverige är det Riksbanken, i USA Fed och i euroområdet ECB."}, {"t": "Högre ränta", "d": "När räntan höjs blir lån dyrare. Företag och hushåll spenderar mindre, och aktiekurser pressas ofta, särskilt för bolag som växer på lånade pengar."}, {"t": "Räntebesked", "d": "Dagarna då centralbanken meddelar räntan kan priserna röra sig kraftigt. Marknaden reagerar mest på det som inte var väntat."}], "q": [{"q": "Vem bestämmer styrräntan i Sverige?", "o": ["Riksbanken", "Börsen", "Skatteverket", "Bankerna själva"]}, {"q": "Vad händer ofta när räntan höjs?", "o": ["Lån blir dyrare och aktier pressas", "Lån blir gratis", "Alla aktier stiger", "Inget alls"]}, {"q": "Vilken centralbank styr räntan i USA?", "o": ["Fed", "ECB", "Riksbanken", "Nasdaq"]}, {"q": "Räntan höjdes precis som alla väntat. Hur reagerar marknaden ofta?", "o": ["Ganska lugnt, det var redan inprisat", "Med en krasch", "Börsen stänger", "Alla aktier fördubblas"]}, {"m": [["Riksbanken", "Sveriges centralbank"], ["Fed", "USA:s centralbank"], ["ECB", "Euroområdets centralbank"], ["Styrränta", "Ränta som styr andra räntor"]]}]}, "x54": {"t": "Inflation", "c": [{"t": "Inflation", "d": "Inflation betyder att priserna i allmänhet stiger. Då kan du köpa mindre för samma pengar."}, {"t": "Inflationsmålet", "d": "Riksbanken har som mål att inflationen ska vara ungefär 2 % per år. Blir den högre brukar räntan höjas för att bromsa."}, {"t": "KPI", "d": "Inflationen mäts ofta med konsumentprisindex, KPI, som följer priset på en korg av vanliga varor och tjänster."}], "q": [{"q": "Vad betyder inflation?", "o": ["Att priserna i allmänhet stiger", "Att priserna sjunker", "Att börsen stänger", "Att lönerna halveras"]}, {"q": "Ungefär vilket inflationsmål har Riksbanken?", "o": ["2 % per år", "10 % per år", "0 % per år", "50 % per år"]}, {"q": "Inflationen är mycket hög. Vad gör centralbanken ofta?", "o": ["Höjer räntan", "Sänker räntan till noll", "Stänger börsen", "Ingenting"]}, {"q": "Vad mäter KPI?", "o": ["Priset på en korg av vanliga varor", "Aktiekurser", "Antalet företag", "Vädret"]}, {"m": [["Inflation", "Priserna stiger"], ["Deflation", "Priserna sjunker"], ["KPI", "Mått på prisökningar"], ["Köpkraft", "Vad pengarna räcker till"]]}]}, "x55": {"t": "BNP och konjunkturcykler", "c": [{"t": "BNP", "d": "BNP, bruttonationalprodukten, är värdet av allt som produceras i ett land under en period. Växer BNP går ekonomin framåt."}, {"t": "Konjunkturcykeln", "d": "Ekonomin går i vågor: uppgång, topp, nedgång och botten. Krympande BNP två kvartal i rad brukar kallas recession."}, {"t": "Börsen ligger före", "d": "Börsen försöker prisa in framtiden. Därför vänder den ofta upp innan ekonomin har nått botten, och ner innan toppen."}], "q": [{"q": "Vad mäter BNP?", "o": ["Värdet av allt som produceras i ett land", "Antalet aktier", "Räntan", "Inflationen"]}, {"q": "Vad kallas det ofta när BNP krymper två kvartal i rad?", "o": ["Recession", "Högkonjunktur", "Utdelning", "Split"]}, {"q": "Varför kan börsen stiga trots att ekonomin fortfarande är svag?", "o": ["Den prisar in en framtida förbättring", "Börsen är alltid fel", "Det kan den inte", "Staten köper alla aktier"]}, {"q": "Vilken ordning har konjunkturcykeln?", "o": ["Uppgång, topp, nedgång, botten", "Topp, topp, topp, topp", "Botten, split, utdelning", "Den har ingen ordning"]}, {"m": [["BNP", "Allt som produceras"], ["Recession", "Krympande ekonomi"], ["Topp", "Ekonomin är som starkast"], ["Botten", "Ekonomin är som svagast"]]}]}, "x56": {"t": "Arbetsmarknaden", "c": [{"t": "Arbetslöshet", "d": "Arbetslösheten visar hur stor del av dem som vill jobba som saknar jobb. Låg arbetslöshet betyder ofta en stark ekonomi."}, {"t": "Jobbrapporten i USA", "d": "USA:s jobbrapport kommer oftast första fredagen i månaden. Den kan få hela världens börser att röra sig."}, {"t": "Löner och inflation", "d": "När många har jobb stiger ofta lönerna. Det är bra för konsumtionen men kan driva upp inflationen och därmed räntorna."}], "q": [{"q": "Vad betyder låg arbetslöshet ofta?", "o": ["En stark ekonomi", "En krasch", "Att börsen stänger", "Att räntan är noll"]}, {"q": "När kommer USA:s jobbrapport oftast?", "o": ["Första fredagen i månaden", "Varje söndag", "En gång vart tionde år", "På julafton"]}, {"q": "Varför kan väldigt starka jobbsiffror ibland få börsen att falla?", "o": ["Marknaden räknar med högre räntor", "Jobb är dåligt för företag", "Det kan aldrig hända", "Siffrorna är alltid falska"]}, {"q": "Vad händer ofta med lönerna när nästan alla har jobb?", "o": ["De stiger", "De sjunker", "De försvinner", "De blir aktier"]}, {"m": [["Arbetslöshet", "Andel som saknar jobb"], ["Jobbrapport", "Nya jobb i USA varje månad"], ["Löneökning", "Kan driva inflation"], ["Konsumtion", "Det hushållen köper"]]}]}, "x57": {"t": "Valutor och kronan", "c": [{"t": "Valutakurs", "d": "Valutakursen är priset på en valuta i en annan, till exempel hur många kronor en dollar kostar."}, {"t": "Valutarisk", "d": "Äger du en amerikansk aktie påverkas du av dollarn. Om kronan stärks blir din aktie värd mindre i kronor, även om priset i dollar står still."}, {"t": "Exportbolag", "d": "En svag krona är ofta bra för svenska exportbolag, eftersom de får in fler kronor när de säljer utomlands."}], "q": [{"q": "Du äger en amerikansk aktie. Kronan stärks mot dollarn. Vad händer med värdet i kronor?", "o": ["Den minskar", "Den ökar", "Den står still", "Den blir noll"]}, {"q": "Vem gynnas ofta av en svag krona?", "o": ["Svenska exportbolag", "Svenskar som reser utomlands", "Importörer", "Ingen"]}, {"q": "Vad är en valutakurs?", "o": ["Priset på en valuta i en annan", "En sorts ränta", "En avgift på börsen", "Ett mönster"]}, {"q": "En dollar kostade 10 kr och kostar nu 11 kr. Vad har hänt med kronan?", "o": ["Den har försvagats", "Den har stärkts", "Inget", "Den har delats"], "why": "Du behöver fler kronor för att köpa en dollar. Kronan är alltså svagare."}, {"m": [["Valutakurs", "Pris på en valuta"], ["Stark krona", "Utländskt blir billigare"], ["Svag krona", "Bra för export"], ["Valutarisk", "Värdet påverkas av valutan"]]}]}, "x58": {"t": "Olja och guld", "c": [{"t": "Oljepriset", "d": "Olja används till transporter och industri. Ett högt oljepris ökar kostnaderna för många företag och kan driva upp inflationen."}, {"t": "Guld", "d": "Guld ses ofta som en säker hamn. När oron är stor köper många guld, och priset kan stiga när aktierna faller."}, {"t": "Vinnare och förlorare", "d": "När oljan stiger tjänar oljebolagen, medan flygbolag och åkerier får högre kostnader. Samma nyhet kan vara bra för ett bolag och dålig för ett annat."}], "q": [{"q": "Oljepriset stiger kraftigt. Vilket bolag drabbas troligen mest?", "o": ["Ett flygbolag", "Ett oljebolag", "En guldgruva", "Ingen"]}, {"q": "Varför kallas guld ofta en säker hamn?", "o": ["Många köper det när oron är stor", "Det kan aldrig falla", "Det ger hög utdelning", "Det är gratis"]}, {"q": "Hur kan ett högt oljepris påverka inflationen?", "o": ["Driva upp den", "Sänka den till noll", "Inte alls", "Göra den negativ för alltid"]}, {"q": "Kan guld falla i pris?", "o": ["Ja, guld kan också falla", "Nej, aldrig", "Bara på måndagar", "Bara i Sverige"]}, {"m": [["Olja", "Påverkar transporter och inflation"], ["Guld", "Säker hamn vid oro"], ["Råvara", "Vara som olja, metall eller vete"], ["Flygbolag", "Drabbas av dyr olja"]]}]}, "x59": {"t": "Ekonomisk kalender", "c": [{"t": "Ekonomisk kalender", "d": "En ekonomisk kalender visar när viktiga siffror och beslut kommer: räntebesked, inflation, jobbsiffror och företagsrapporter."}, {"t": "Svängigt runt siffror", "d": "Precis när viktiga siffror släpps kan priset hoppa fram och tillbaka och spreaden bli stor. Många väntar tills det lugnat sig."}, {"t": "Planera i förväg", "d": "Kolla kalendern innan du går in i en affär. Då blir du inte överraskad av en stor nyhet mitt i affären."}], "q": [{"q": "Vad visar en ekonomisk kalender?", "o": ["När viktiga siffror och beslut kommer", "Aktiekurser för i morgon", "Börsens semestrar", "Väderprognosen"]}, {"q": "Vad kan hända precis när viktiga siffror släpps?", "o": ["Priset hoppar och spreaden blir stor", "Allt står helt still", "Courtaget försvinner", "Alla vinner"]}, {"q": "Varför ska man kolla kalendern innan man handlar?", "o": ["För att inte bli överraskad av en stor nyhet", "För att få lägre skatt", "Det behövs aldrig", "För att börsen kräver det"]}, {"q": "Vilket av dessa finns i en ekonomisk kalender?", "o": ["Räntebesked", "En doji", "En trendlinje", "Din stop-loss"]}, {"m": [["Räntebesked", "Centralbankens beslut"], ["Inflationssiffra", "Hur mycket priserna stigit"], ["Rapportsäsong", "Många bolag rapporterar"], ["Kalender", "Planera runt viktiga datum"]]}]}, "x60": {"t": "Nyheter och marknaden", "c": [{"t": "Inprisat", "d": "Det som alla redan väntar sig finns ofta redan i priset. Därför rör sig priset mest när något oväntat händer."}, {"t": "Köp ryktet, sälj nyheten", "d": "Ofta stiger en aktie på förväntningar inför en nyhet och faller sedan när nyheten väl kommer. Uttrycket kallas köp ryktet, sälj nyheten."}, {"t": "Lugn inför rubriker", "d": "Rubriker är skrivna för att få uppmärksamhet. Läs hela nyheten och fundera på om den verkligen ändrar något för företaget."}], "q": [{"q": "Vad betyder att något är inprisat?", "o": ["Marknaden har redan räknat med det", "Det är gratis", "Det är förbjudet", "Priset är fel"]}, {"q": "En aktie steg i veckor inför en produktlansering och föll sedan när den kom. Vad kallas mönstret?", "o": ["Köp ryktet, sälj nyheten", "Gyllene kors", "Short squeeze", "Huvud och axlar"]}, {"q": "Vad är klokt när du ser en dramatisk rubrik?", "o": ["Läsa hela nyheten och tänka efter", "Sälja allt direkt", "Köpa med hävstång", "Dela den utan att läsa"]}, {"q": "När rör sig priset oftast mest?", "o": ["När något oväntat händer", "När allt går som väntat", "På natten när börsen är stängd", "Aldrig"]}, {"m": [["Inprisat", "Redan i priset"], ["Överraskning", "Får priset att röra sig"], ["Rykte", "Obekräftad uppgift"], ["Rubrik", "Skriven för uppmärksamhet"]]}]}, "x61": {"t": "Geopolitik", "c": [{"t": "Osäkerhet", "d": "Krig, val och konflikter mellan länder skapar osäkerhet. Osäkerhet gör att många säljer först och tänker sedan."}, {"t": "Handelskrig", "d": "När länder sätter tullar på varandras varor blir handeln dyrare. Det drabbar särskilt bolag som säljer mycket utomlands."}, {"t": "Sprid riskerna", "d": "Ingen kan förutse politiken. Att sprida pengarna på olika länder och branscher gör att en enskild händelse inte slår ut allt."}], "q": [{"q": "Vad skapar ofta krig och politiska konflikter på börsen?", "o": ["Osäkerhet", "Garanterade vinster", "Lägre courtage", "Ingenting"]}, {"q": "Vad är en tull?", "o": ["En avgift på importerade varor", "En sorts aktie", "En ränta", "En order"]}, {"q": "Vilket skydd fungerar bäst mot politiska överraskningar?", "o": ["Att sprida pengarna", "Att gissa vad politikerna gör", "Att satsa allt på ett land", "Att använda mer hävstång"]}, {"q": "Vilka bolag drabbas oftast mest av ett handelskrig?", "o": ["De som säljer mycket utomlands", "Den lokala frisören", "Inga bolag", "Bara banker"]}, {"m": [["Geopolitik", "Politik mellan länder"], ["Tull", "Avgift på import"], ["Sanktion", "Straff mot ett land"], ["Spridning", "Pengar på flera ställen"]]}]}, "x62": {"t": "Sektorrotation", "c": [{"t": "Sektorrotation", "d": "Pengarna på börsen flyttar mellan branscher beroende på läget. Det kallas sektorrotation."}, {"t": "Tidigt och sent", "d": "När ekonomin börjar återhämta sig går pengarna ofta till cykliska bolag. När den börjar mattas av söker många sig till defensiva bolag."}, {"t": "Relativ styrka", "d": "Genom att jämföra hur olika branscher går mot hela börsen kan man se vart pengarna är på väg. Det kallas relativ styrka."}], "q": [{"q": "Vad är sektorrotation?", "o": ["Pengar som flyttar mellan branscher", "Att börsen roterar sina öppettider", "En sorts split", "Ett ljusmönster"]}, {"q": "Ekonomin börjar återhämta sig efter en kris. Vart går pengarna ofta?", "o": ["Till cykliska bolag", "Bara till guld", "Till kontanter under madrassen", "Ingenstans"]}, {"q": "Vad visar relativ styrka?", "o": ["Hur en bransch går jämfört med hela börsen", "Hur stark en aktie är fysiskt", "Räntan", "Antalet anställda"]}, {"q": "Ekonomin börjar mattas av. Vilka bolag söker sig många till?", "o": ["Defensiva bolag", "Bara biltillverkare", "Nystartade bolag utan intäkter", "Inga alls"]}, {"m": [["Sektorrotation", "Pengar byter bransch"], ["Relativ styrka", "Jämfört med hela börsen"], ["Återhämtning", "Gynnar ofta cykliska"], ["Avmattning", "Gynnar ofta defensiva"]]}]}, "x63": {"t": "Fonder och ETF:er", "c": [{"t": "Fond", "d": "En fond är en korg med många värdepapper som många sparare äger tillsammans. Med en enda fond sprider du pengarna på många bolag."}, {"t": "ETF", "d": "En ETF är en fond som handlas på börsen som en aktie, hela dagen. En vanlig fond köps och säljs oftast en gång per dag till fondkursen."}, {"t": "Avgift", "d": "Fonder tar en årlig avgift, som dras från fondens värde. Även en liten skillnad i avgift blir stor efter många år."}], "q": [{"q": "Vad är en fond?", "o": ["En korg med många värdepapper", "En enda aktie", "Ett lån till staten", "En sorts order"]}, {"q": "Vad skiljer en ETF från en vanlig fond?", "o": ["Den handlas på börsen hela dagen", "Den har ingen risk", "Den ger alltid utdelning", "Den kan bara köpas på söndagar"]}, {"q": "Fond A tar 1,5 % per år och fond B 0,2 %. De har samma innehåll. Vilken är bäst för dig?", "o": ["Fond B", "Fond A", "De är lika bra", "Ingen av dem"], "why": "Med samma innehåll blir avkastningen före avgift lika. Lägre avgift ger mer kvar till dig."}, {"q": "Varför sprider en fond risken?", "o": ["Den äger många olika bolag", "Den äger bara ett bolag", "Den kan inte falla", "Staten garanterar den"]}, {"m": [["Fond", "Korg med många värdepapper"], ["ETF", "Fond som handlas som en aktie"], ["Fondkurs", "Fondens pris en gång per dag"], ["Förvaltningsavgift", "Årlig kostnad för fonden"]]}]}, "x64": {"t": "Indexfonder", "c": [{"t": "Index", "d": "Ett index mäter hur en grupp aktier utvecklas, till exempel de 30 mest handlade aktierna i Stockholm i OMXS30."}, {"t": "Indexfond", "d": "En indexfond köper helt enkelt alla aktier i ett index. Ingen försöker välja vinnare, så avgiften blir låg."}, {"t": "Svårt att slå index", "d": "Över lång tid misslyckas många aktiva fonder med att slå sitt index efter avgifter. Därför väljer många sparare indexfonder."}], "q": [{"q": "Vad gör en indexfond?", "o": ["Köper alla aktier i ett index", "Väljer ut de bästa aktierna", "Handlar bara krypto", "Lånar ut pengar"]}, {"q": "Varför har indexfonder ofta låga avgifter?", "o": ["Ingen behöver välja aktier", "De är olagliga", "De har inga aktier", "Staten betalar"]}, {"q": "Vad mäter OMXS30?", "o": ["De 30 mest handlade aktierna i Stockholm", "30 länders valutor", "Räntan i 30 år", "30 sorters råvaror"]}, {"q": "Vad säger erfarenheten om aktiva fonder över lång tid?", "o": ["Många slår inte sitt index efter avgifter", "Alla slår index", "De har ingen avgift", "De är garanterade"]}, {"m": [["Index", "Mått på en grupp aktier"], ["Indexfond", "Följer ett index"], ["Aktiv fond", "Förvaltare väljer aktier"], ["OMXS30", "Index för Stockholmsbörsen"]]}]}, "x65": {"t": "Obligationer", "c": [{"t": "Obligation", "d": "En obligation är ett lån till en stat eller ett företag. Du får ränta, kallad kupong, och pengarna tillbaka när lånet löper ut."}, {"t": "Ränta och pris", "d": "När räntorna i samhället stiger faller priset på gamla obligationer, eftersom nya obligationer ger mer ränta."}, {"t": "Kreditrisk", "d": "Kreditrisk är risken att den som lånat inte kan betala tillbaka. Högre risk ger högre ränta."}], "q": [{"q": "Vad är en obligation?", "o": ["Ett lån till en stat eller ett företag", "En del av ett företag", "En kryptovaluta", "En avgift"]}, {"q": "Räntorna i samhället stiger. Vad händer med priset på gamla obligationer?", "o": ["Det faller", "Det stiger", "Det står still", "Det blir noll"], "why": "Nya obligationer ger mer ränta, så de gamla blir mindre attraktiva och priset sjunker."}, {"q": "Varför ger ett riskabelt företag högre ränta?", "o": ["Långivaren vill ha betalt för risken", "Det är en lag", "Riskabla företag är rika", "Det gör det inte"]}, {"q": "Vad kallas räntan du får på en obligation?", "o": ["Kupong", "Utdelning", "Spread", "Courtage"]}, {"m": [["Obligation", "Lån till stat eller företag"], ["Kupong", "Räntan på obligationen"], ["Löptid", "Hur länge lånet gäller"], ["Kreditrisk", "Risk att lånet inte betalas"]]}]}, "x66": {"t": "Råvaror som investering", "c": [{"t": "Råvaror", "d": "Råvaror är saker som olja, guld, koppar och vete. Deras pris styrs av utbud och efterfrågan i hela världen."}, {"t": "Hur man investerar", "d": "Privatpersoner investerar oftast via fonder, ETF:er eller certifikat, inte genom att köpa fysiska tunnor olja."}, {"t": "Inget kassaflöde", "d": "En råvara ger ingen vinst eller utdelning. Du tjänar bara om priset stiger, så avkastningen beror helt på prisrörelser."}], "q": [{"q": "Vilket av dessa är en råvara?", "o": ["Koppar", "En aktie i en bank", "En obligation", "En indexfond"]}, {"q": "Hur investerar privatpersoner oftast i råvaror?", "o": ["Via fonder, ETF:er eller certifikat", "Genom att köpa oljetunnor hem", "Genom att starta en gruva", "Det går inte"]}, {"q": "Vad saknar en råvara jämfört med en aktie?", "o": ["Vinst och utdelning", "Ett pris", "Köpare", "Risk"]}, {"q": "Vad styr råvarupriserna?", "o": ["Utbud och efterfrågan i världen", "Bara svensk lag", "Börsens öppettider", "Ingenting"]}, {"m": [["Olja", "Energiråvara"], ["Guld", "Ädelmetall"], ["Vete", "Jordbruksråvara"], ["Koppar", "Industrimetall"]]}]}, "x67": {"t": "Valutahandel", "c": [{"t": "Valutapar", "d": "Valutor handlas i par, till exempel EUR/USD. Priset visar hur många dollar en euro kostar."}, {"t": "Världens största marknad", "d": "Valutamarknaden är den största marknaden i världen och har öppet dygnet runt på vardagar."}, {"t": "Hög hävstång", "d": "Valutor rör sig oftast lite per dag, så många handlar med hög hävstång. Det gör valutahandel mycket riskabel för nybörjare."}], "q": [{"q": "EUR/USD är 1,10. Vad betyder det?", "o": ["En euro kostar 1,10 dollar", "En dollar kostar 1,10 euro", "Båda kostar 110 kr", "Räntan är 1,10 %"]}, {"q": "När har valutamarknaden öppet?", "o": ["Dygnet runt på vardagar", "Bara 09.00–17.30", "Bara på helger", "En timme per dag"]}, {"q": "Varför är valutahandel extra riskabel för nybörjare?", "o": ["Många använder hög hävstång", "Valutor står alltid still", "Det är förbjudet", "Det finns ingen risk"]}, {"q": "Hur handlas valutor?", "o": ["I par, en mot en annan", "En och en utan jämförelse", "Bara mot guld", "Bara på Stockholmsbörsen"]}, {"m": [["Valutapar", "Två valutor mot varandra"], ["EUR", "Euro"], ["USD", "Amerikansk dollar"], ["Forex", "Valutamarknaden"]]}]}, "x68": {"t": "Kryptovalutor", "c": [{"t": "Kryptovaluta", "d": "En kryptovaluta är digitala pengar som registreras i en blockkedja, en sorts gemensam bokföring på många datorer. Bitcoin är den mest kända."}, {"t": "Dygnet runt", "d": "Kryptovalutor handlas dygnet runt, alla dagar. Priset kan röra sig väldigt mycket även när du sover."}, {"t": "Mycket svängigt", "d": "Priserna kan stiga eller falla med tiotals procent på kort tid. Det ger stora möjligheter men också mycket stor risk."}], "q": [{"q": "Vad är en blockkedja?", "o": ["En gemensam bokföring på många datorer", "En bank i Sverige", "En sorts aktie", "Ett ljusmönster"]}, {"q": "När handlas kryptovalutor?", "o": ["Dygnet runt, alla dagar", "Bara på vardagar", "09.00–17.30", "En gång per månad"]}, {"q": "Vilken kryptovaluta är mest känd?", "o": ["Bitcoin", "Kronan", "Guld", "OMXS30"]}, {"q": "Vad är typiskt för kryptopriser?", "o": ["De svänger mycket", "De står alltid still", "De är garanterade", "De följer räntan exakt"]}, {"m": [["Kryptovaluta", "Digitala pengar"], ["Blockkedja", "Gemensam digital bokföring"], ["Bitcoin", "Den första kryptovalutan"], ["Volatil", "Svänger mycket"]]}]}, "x69": {"t": "Risker med krypto", "c": [{"t": "Plattformsrisk", "d": "Kryptobörser kan hackas eller gå i konkurs. Då kan kundernas pengar försvinna, och det finns ofta ingen insättningsgaranti."}, {"t": "Privata nycklar", "d": "Den som har den privata nyckeln äger kryptot. Tappar du nyckeln eller lurar någon till sig den kan pengarna vara borta för alltid."}, {"t": "Bluffar", "d": "Krypto är vanligt i bedrägerier: falska plattformar, löften om garanterad avkastning och personer som vill att du skickar krypto. I EU finns nya regler, MiCA, men var alltid försiktig."}], "q": [{"q": "Vad kan hända om en kryptobörs går i konkurs?", "o": ["Kundernas pengar kan försvinna", "Staten ersätter alltid allt", "Priset blir garanterat högre", "Ingenting"]}, {"q": "Vem äger kryptot?", "o": ["Den som har den privata nyckeln", "Den som har störst dator", "Banken", "Ingen"]}, {"q": "Någon på sociala medier lovar 5 % om dagen om du skickar krypto. Vad är det?", "o": ["Nästan säkert ett bedrägeri", "En bra affär", "En indexfond", "En statsobligation"]}, {"q": "Vad heter EU:s nya regler för krypto?", "o": ["MiCA", "OMXS30", "ISK", "RSI"]}, {"m": [["Privat nyckel", "Ger tillgång till kryptot"], ["Plattformsrisk", "Börsen kan hackas eller gå i konkurs"], ["MiCA", "EU:s regler för krypto"], ["Bedrägeri", "Löften om garanterad vinst"]]}]}, "x70": {"t": "Optioner", "c": [{"t": "Option", "d": "En option ger rätten, men inte skyldigheten, att köpa eller sälja något till ett bestämt pris före ett visst datum. Rätten kostar en premie."}, {"t": "Köp- och säljoption", "d": "En köpoption, call, tjänar på att priset stiger. En säljoption, put, tjänar på att priset faller. Det bestämda priset kallas lösenpris."}, {"t": "Kan bli värdelös", "d": "Om priset inte rör sig åt rätt håll före slutdagen kan optionen bli värdelös. Då förlorar köparen hela premien."}], "q": [{"q": "Vilken option tjänar på att priset stiger?", "o": ["Köpoption, call", "Säljoption, put", "Båda", "Ingen"]}, {"q": "Vad kallas det bestämda priset i en option?", "o": ["Lösenpris", "Utdelning", "Spread", "Kupong"]}, {"q": "Vad är det mesta en köpare av en option kan förlora?", "o": ["Premien", "Obegränsat", "Inget alls", "Dubbla premien"]}, {"q": "Vad händer om priset inte rör sig rätt före slutdagen?", "o": ["Optionen kan bli värdelös", "Optionen förlängs gratis", "Du får pengarna tillbaka", "Den blir en aktie"]}, {"m": [["Köpoption", "Rätt att köpa"], ["Säljoption", "Rätt att sälja"], ["Premie", "Priset för optionen"], ["Lösenpris", "Det bestämda priset"]]}]}, "x71": {"t": "Terminer", "c": [{"t": "Termin", "d": "En termin är ett avtal om att köpa eller sälja något vid ett senare datum till ett pris som bestäms i dag. Båda parter måste fullfölja."}, {"t": "Säkring", "d": "Terminer uppfanns för att minska risk. En bonde kan låsa priset på sitt vete i förväg, så att ett prisfall inte förstör hela året."}, {"t": "Inbyggd hävstång", "d": "Du betalar bara en liten säkerhet för att handla en termin. Det ger hävstång, och förlusten kan bli större än det du satt in."}], "q": [{"q": "Vad är skillnaden mellan en termin och en option?", "o": ["En termin måste fullföljas", "En termin är gratis", "En option måste fullföljas", "Det finns ingen skillnad"]}, {"q": "Varför kan en bonde använda en termin?", "o": ["För att låsa priset på skörden", "För att slippa skatt", "För att få utdelning", "För att odla snabbare"]}, {"q": "Kan du förlora mer än du satt in på en termin?", "o": ["Ja, på grund av hävstången", "Nej, aldrig", "Bara på fredagar", "Bara om du vinner"]}, {"q": "Vad kallas det att använda en termin för att minska risk?", "o": ["Säkring", "Blankning", "Scalping", "Utspädning"]}, {"m": [["Termin", "Avtal om framtida affär"], ["Säkring", "Minska en risk"], ["Slutdag", "När avtalet ska fullföljas"], ["Säkerhet", "Pengar som krävs för att handla"]]}]}, "x72": {"t": "CFD:er och certifikat", "c": [{"t": "CFD", "d": "En CFD är ett avtal med en mäklare om prisskillnaden på något, till exempel en aktie, utan att du äger själva aktien. Den har nästan alltid hävstång."}, {"t": "De flesta förlorar", "d": "De flesta privatpersoner som handlar CFD:er förlorar pengar. I EU måste mäklare visa hur stor andel av kunderna som förlorar."}, {"t": "Hävstångscertifikat", "d": "Bull- och bear-certifikat har ofta daglig hävstång. Om priset svänger upp och ner utan riktning kan certifikatet tappa värde ändå."}], "q": [{"q": "Äger du aktien när du handlar en CFD på den?", "o": ["Nej, bara ett avtal om prisskillnaden", "Ja, alltid", "Ja, men bara halva", "Bara på helger"]}, {"q": "Hur går det för de flesta privatpersoner som handlar CFD:er?", "o": ["De förlorar pengar", "De blir rika", "De går jämnt ut", "De får utdelning"]}, {"q": "Ett certifikat med daglig hävstång. Priset går upp och ner i sidled i en månad och slutar där det började. Vad kan ha hänt med certifikatet?", "o": ["Det har tappat värde", "Det har fördubblats", "Det är exakt oförändrat", "Det har blivit en aktie"], "why": "Daglig hävstång räknas om varje dag. När priset svänger utan riktning äter det upp värdet."}, {"q": "Vad måste mäklare i EU visa för CFD-kunder?", "o": ["Hur stor andel av kunderna som förlorar", "Hur mycket vinst du garanterat får", "Mäklarens lön", "Ingenting"]}, {"m": [["CFD", "Avtal om prisskillnad"], ["Bull-certifikat", "Tjänar när priset stiger"], ["Bear-certifikat", "Tjänar när priset faller"], ["Daglig hävstång", "Räknas om varje dag"]]}]}, "x73": {"t": "Trendföljning", "c": [{"t": "Följ trenden", "d": "Trendföljare köper när trenden är uppåt och säljer när den bryts. De försöker inte gissa toppen eller botten.", "fig": "up"}, {"t": "Små förluster, stora vinster", "d": "Trendföljning ger ofta många små förluster och några få stora vinster. Det kräver tålamod att stå ut med förlusterna."}, {"t": "Låt vinsterna löpa", "d": "En viktig regel är att låta vinnarna fortsätta så länge trenden håller, men snabbt stänga affärer som går fel."}], "q": [{"q": "Vad gör en trendföljare?", "o": ["Köper i upptrend och säljer när den bryts", "Försöker pricka exakt toppen", "Köper bara när priset rasar", "Handlar aldrig"]}, {"q": "Hur ser resultaten ofta ut för trendföljning?", "o": ["Många små förluster och några stora vinster", "Bara vinster", "Bara förluster", "Exakt noll varje dag"]}, {"q": "Vad betyder att låta vinsterna löpa?", "o": ["Behålla vinnare så länge trenden håller", "Sälja direkt vid minsta vinst", "Ta bort stop-loss", "Köpa mer av förlorare"]}, {"q": "I vilken marknad fungerar trendföljning sämst?", "o": ["En marknad som går i sidled", "En stark upptrend", "En stark nedtrend", "Det fungerar lika bra överallt"]}, {"m": [["Trendföljning", "Gå med trenden"], ["Låt vinsterna löpa", "Behåll vinnare"], ["Klipp förlusterna", "Stäng förlorare snabbt"], ["Sidledsmarknad", "Svårt för trendföljare"]]}]}, "x74": {"t": "Breakout-trading", "c": [{"t": "Utbrott", "d": "Breakout-traders köper när priset bryter över ett motstånd, eller säljer när det bryter under ett stöd. Tanken är att en ny rörelse börjar.", "fig": "breakout"}, {"t": "Falska utbrott", "d": "Många utbrott misslyckas och priset faller tillbaka in i intervallet. Hög volym vid utbrottet gör det mer trovärdigt."}, {"t": "Stopp under nivån", "d": "En vanlig stopp läggs strax under den nivå som bröts. Faller priset tillbaka dit har utbrottet misslyckats."}], "q": [{"q": "När köper en breakout-trader?", "o": ["När priset bryter över motståndet", "Mitt i intervallet", "När priset faller under stödet", "Slumpmässigt"]}, {"q": "Vad gör ett utbrott mer trovärdigt?", "o": ["Hög volym", "Låg volym", "Att det sker på natten", "Att ingen märker det"]}, {"q": "Var läggs en vanlig stopp vid ett utbrott uppåt?", "o": ["Strax under nivån som bröts", "Långt över priset", "Ingen stopp behövs", "Vid noll kronor"]}, {"q": "Vad är ett falskt utbrott?", "o": ["När priset bryter ut men faller tillbaka", "Ett utbrott på hög volym", "En utdelning", "En sorts order"]}, {"m": [["Utbrott", "Priset bryter en nivå"], ["Falskt utbrott", "Priset faller tillbaka"], ["Volym", "Bekräftar utbrottet"], ["Intervall", "Där priset var innan"]]}]}, "x75": {"t": "Mean reversion", "c": [{"t": "Tillbaka till mitten", "d": "Mean reversion bygger på att priset ofta går tillbaka mot sitt medelvärde efter en stor rörelse. Man köper det som fallit för mycket och säljer det som stigit för mycket.", "fig": "side"}, {"t": "Bäst i intervall", "d": "Strategin fungerar bäst när priset rör sig i sidled. Då studsar det mellan stöd och motstånd."}, {"t": "Fallande kniv", "d": "I en stark nedtrend kan det som ser billigt ut bli ännu billigare. Att köpa då kallas att fånga en fallande kniv."}], "q": [{"q": "Vad bygger mean reversion på?", "o": ["Att priset går tillbaka mot medelvärdet", "Att trender varar för evigt", "Att nyheter inte spelar roll", "Att alla aktier är lika"]}, {"q": "I vilken marknad fungerar mean reversion bäst?", "o": ["En marknad i sidled", "En stark trend", "En krasch", "En stängd börs"]}, {"q": "Vad betyder att fånga en fallande kniv?", "o": ["Köpa i en stark nedtrend som fortsätter", "Sälja på toppen", "Laga mat", "Använda stop-loss"]}, {"q": "Priset har studsat mellan 90 och 110 i månader och står nu på 91. Vad skulle en mean reversion-trader överväga?", "o": ["Att köpa med stopp under 90", "Att blanka med stopp vid 50", "Att köpa med all hävstång", "Att aldrig göra något"]}, {"m": [["Mean reversion", "Priset söker sig till mitten"], ["Översålt", "Fallit för mycket"], ["Överköpt", "Stigit för mycket"], ["Fallande kniv", "Det billiga blir billigare"]]}]}, "x76": {"t": "Swingtrading", "c": [{"t": "Swingtrading", "d": "En swingtrader håller sina affärer i några dagar till några veckor och försöker fånga en sväng i priset."}, {"t": "Mindre skärmtid", "d": "Swingtrading kräver mindre tid framför skärmen än daytrading. Många kollar graferna en gång om dagen, till exempel på kvällen."}, {"t": "Risk över natten", "d": "Eftersom affärerna hålls över natten finns risken att priset hoppar på grund av nyheter. Mindre positioner minskar den risken."}], "q": [{"q": "Hur länge håller en swingtrader oftast en affär?", "o": ["Dagar till veckor", "Några sekunder", "Tio år", "Aldrig mer än en minut"]}, {"q": "Vilken risk har swingtrading som daytrading inte har?", "o": ["Risk över natten", "Ingen risk alls", "Risk att börsen försvinner", "Risk för för låg spread"]}, {"q": "Varför passar swingtrading många som har ett jobb?", "o": ["Det kräver mindre skärmtid", "Det är garanterat lönsamt", "Det kräver ingen plan", "Det är gratis"]}, {"q": "Hur kan en swingtrader minska risken för hopp över natten?", "o": ["Ta mindre positioner", "Ta större positioner", "Ta bort stop-loss", "Använda mer hävstång"]}, {"m": [["Swingtrading", "Dagar till veckor"], ["Daytrading", "Stängs samma dag"], ["Sväng", "En rörelse upp eller ner"], ["Risk över natten", "Nyheter när börsen är stängd"]]}]}, "x77": {"t": "Daytrading på riktigt", "c": [{"t": "Daytrading", "d": "En daytrader stänger alla affärer samma dag. Ingen position hålls över natten."}, {"t": "Verkligheten", "d": "Studier av riktiga konton visar att de allra flesta daytraders förlorar pengar över tid. Bara en liten andel tjänar mer än en vanlig lön."}, {"t": "Kostnaderna äter", "d": "Med många affärer per dag blir courtage och spread en stor kostnad. Du måste vinna mer än kostnaderna bara för att gå jämnt."}], "q": [{"q": "Vad kännetecknar en daytrader?", "o": ["Stänger alla affärer samma dag", "Håller aktier i tio år", "Handlar en gång per år", "Använder aldrig grafer"]}, {"q": "Vad visar studier om de flesta daytraders över tid?", "o": ["De förlorar pengar", "De blir miljonärer", "De går exakt jämnt ut", "Det finns inga studier"]}, {"q": "Varför spelar kostnaderna så stor roll för daytraders?", "o": ["De gör många affärer varje dag", "De betalar ingen spread", "De har inga kostnader", "Kostnader är bara för långsiktiga"]}, {"q": "Vad är klokast för en nybörjare som vill testa daytrading?", "o": ["Öva med låtsaspengar först", "Satsa hela sparkontot", "Låna pengar", "Säga upp sig från jobbet"]}, {"m": [["Daytrading", "Allt stängs samma dag"], ["Kostnader", "Courtage och spread"], ["Låtsaspengar", "Öva utan risk"], ["Verklighet", "De flesta förlorar"]]}]}, "x78": {"t": "Scalping", "c": [{"t": "Scalping", "d": "Scalpers gör väldigt korta affärer, från sekunder till några minuter, och försöker ta många små vinster."}, {"t": "Kostnader avgör", "d": "När vinsten per affär är liten kan spreaden och courtaget vara större än vinsten. Kostnaderna avgör om strategin fungerar."}, {"t": "Mot maskinerna", "d": "I de snabbaste tidsramarna tävlar man mot datorer som reagerar på bråkdelar av en sekund. Det är svårt för en privatperson."}], "q": [{"q": "Hur länge varar en typisk scalping-affär?", "o": ["Sekunder till minuter", "Månader", "År", "Exakt en dag"]}, {"q": "Du siktar på 0,10 kr vinst per aktie och spreaden är 0,12 kr. Vad är problemet?", "o": ["Kostnaden är större än vinsten", "Det finns inget problem", "Vinsten är för stor", "Spreaden ger dig pengar"]}, {"q": "Vem tävlar en privat scalper mot i de snabbaste tidsramarna?", "o": ["Snabba datorer och algoritmer", "Långsiktiga sparare", "Ingen", "Skatteverket"]}, {"q": "Vad avgör framför allt om scalping går med vinst?", "o": ["Kostnaderna per affär", "Färgen på grafen", "Vädret", "Logotypen"]}, {"m": [["Scalping", "Många mycket korta affärer"], ["Spread", "Kan äta upp vinsten"], ["Algoritm", "Snabb motståndare"], ["Liten vinst", "Målet per affär"]]}]}, "x79": {"t": "Positionstrading", "c": [{"t": "Positionstrading", "d": "En positionstrader håller sina affärer i månader och försöker fånga stora trender. Det dagliga bruset spelar mindre roll."}, {"t": "Teknik och fundamenta", "d": "Många positionstraders kombinerar grafen med fundamental analys, till exempel bolagets tillväxt och värdering."}, {"t": "Bredare stopp", "d": "Eftersom affärerna hålls länge behövs bredare stopp. Därför blir positionerna mindre, så att risken i kronor ändå är liten."}], "q": [{"q": "Hur länge håller en positionstrader sina affärer?", "o": ["Månader", "Sekunder", "Minuter", "Exakt en dag"]}, {"q": "Varför blir positionerna mindre med bredare stopp?", "o": ["För att risken i kronor ska vara densamma", "För att få mer utdelning", "För att börsen kräver det", "Det blir de inte"], "why": "Positionsstorlek = risk ÷ avstånd till stoppen. Längre avstånd betyder färre aktier för samma risk."}, {"q": "Vad kombinerar många positionstraders?", "o": ["Grafen och fundamental analys", "Väder och horoskop", "Bara rykten", "Ingenting"]}, {"q": "Vad spelar mindre roll för en positionstrader?", "o": ["Det dagliga bruset", "Den stora trenden", "Risken", "Planen"]}, {"m": [["Positionstrading", "Månader långa affärer"], ["Bred stopp", "Ger plats för brus"], ["Mindre position", "Håller risken liten"], ["Fundamenta", "Bolagets siffror"]]}]}, "x80": {"t": "Månadssparande", "c": [{"t": "Spara varje månad", "d": "Med månadssparande sätter du in ett fast belopp varje månad, till exempel i en indexfond. Du behöver inte välja rätt dag."}, {"t": "Genomsnittskostnad", "d": "När priset är lågt får du fler andelar och när det är högt färre. Det jämnar ut ditt inköpspris över tid."}, {"t": "Ränta på ränta", "d": "Avkastningen ger ny avkastning. Över många år kan det växa mycket, så tid i marknaden betyder mer än att hitta exakt rätt tillfälle."}], "q": [{"q": "Du sparar 500 kr i månaden. Priset per andel är 50 kr ena månaden och 100 kr nästa. Hur många andelar får du totalt?", "o": ["15", "10", "20", "5"], "why": "500 ÷ 50 = 10 andelar och 500 ÷ 100 = 5 andelar. Totalt 15."}, {"q": "Vad är ränta på ränta?", "o": ["Att avkastningen ger ny avkastning", "En avgift på lån", "En sorts order", "En skatt"]}, {"q": "Vad betyder mest för långsiktigt sparande?", "o": ["Tid i marknaden", "Att hitta exakt rätt dag", "Att handla varje minut", "Att följa rykten"]}, {"q": "Varför slipper du gissa rätt dag med månadssparande?", "o": ["Du köper jämnt över tid", "Priset är alltid detsamma", "Fonder kan inte falla", "Banken väljer åt dig"]}, {"m": [["Månadssparande", "Fast belopp varje månad"], ["Genomsnittskostnad", "Jämnar ut inköpspriset"], ["Ränta på ränta", "Avkastning på avkastning"], ["Andel", "En del av en fond"]]}]}, "x81": {"t": "Diversifiering och ombalansering", "c": [{"t": "Diversifiering", "d": "Att diversifiera betyder att sprida pengarna på olika bolag, branscher, länder och tillgångsslag. Då slår en enskild krasch inte ut allt."}, {"t": "Målfördelning", "d": "Många bestämmer en fördelning, till exempel 60 % aktier och 40 % räntor. Fördelningen styr hur mycket risk du tar."}, {"t": "Ombalansering", "d": "När aktierna har stigit utgör de en större del än planerat. Vid ombalansering säljer du lite av det som stigit och köper det som halkat efter."}], "q": [{"q": "Vad betyder diversifiering?", "o": ["Att sprida pengarna på olika tillgångar", "Att satsa allt på en aktie", "Att bara spara kontanter", "Att handla varje dag"]}, {"q": "Målet är 60 % aktier, men efter ett bra år är det 70 %. Vad gör du vid ombalansering?", "o": ["Säljer lite aktier och köper räntor", "Köper ännu mer aktier", "Säljer allt", "Gör ingenting någonsin"]}, {"q": "Varför skyddar diversifiering?", "o": ["En enskild krasch slår inte ut allt", "Den garanterar vinst", "Den tar bort alla avgifter", "Den gör aktier ofarliga"]}, {"q": "Vad styr hur mycket risk du tar?", "o": ["Fördelningen mellan tillgångsslag", "Färgen på appen", "Veckodagen", "Mäklarens logga"]}, {"m": [["Diversifiering", "Sprid riskerna"], ["Målfördelning", "Planerad fördelning"], ["Ombalansering", "Tillbaka till planen"], ["Tillgångsslag", "Till exempel aktier eller räntor"]]}]}, "x82": {"t": "Backtesting", "c": [{"t": "Backtest", "d": "Ett backtest prövar en strategi på gammal data för att se hur den skulle ha gått. Det är ett sätt att testa en idé utan att riskera pengar."}, {"t": "Överanpassning", "d": "Om du justerar reglerna tills de passar historien perfekt fungerar de ofta dåligt i framtiden. Det kallas överanpassning."}, {"t": "Räkna med kostnader", "d": "Ett backtest måste räkna med courtage, spread och slippage. Annars ser strategin bättre ut än den är."}], "q": [{"q": "Vad är ett backtest?", "o": ["Att testa en strategi på gammal data", "Att handla baklänges", "En sorts order", "En skatteregel"]}, {"q": "Strategin gav 300 % i backtestet efter att du justerat den hundra gånger. Vad är risken?", "o": ["Överanpassning till historien", "Ingen risk, den är perfekt", "Att den är för enkel", "Att börsen stänger"]}, {"q": "Vad måste ett backtest räkna med?", "o": ["Courtage, spread och slippage", "Bara vinsterna", "Vädret", "Inget särskilt"]}, {"q": "Betyder ett bra backtest att strategin fungerar i framtiden?", "o": ["Nej, framtiden kan bli annorlunda", "Ja, alltid", "Ja, om det gav över 50 %", "Bara på fredagar"]}, {"m": [["Backtest", "Test på gammal data"], ["Överanpassning", "Passar bara historien"], ["Slippage", "Sämre pris än väntat"], ["Pappershandel", "Testa i realtid utan pengar"]]}]}, "x83": {"t": "Förväntat värde", "c": [{"t": "Förväntat värde", "d": "Förväntat värde är vad en strategi ger i snitt per affär på lång sikt: chansen att vinna gånger snittvinsten, minus chansen att förlora gånger snittförlusten."}, {"t": "Positivt eller negativt", "d": "Är det förväntade värdet positivt tjänar strategin pengar över många affärer. Är det negativt förlorar du till slut, hur mycket tur du än har en tid."}, {"t": "Många affärer", "d": "En enskild affär säger nästan inget. Det förväntade värdet visar sig först efter många affärer."}], "q": [{"q": "Du vinner 40 % av gångerna med 300 kr i snitt och förlorar 60 % med 100 kr i snitt. Vad är förväntat värde per affär?", "o": ["+60 kr", "−60 kr", "+200 kr", "0 kr"], "why": "0,4 × 300 − 0,6 × 100 = 120 − 60 = 60 kr."}, {"q": "Vad händer på lång sikt med en strategi med negativt förväntat värde?", "o": ["Den förlorar pengar", "Den vinner till slut", "Den går alltid jämnt", "Det beror bara på tur"]}, {"q": "Du vann fem affärer i rad. Bevisar det att strategin är bra?", "o": ["Nej, det behövs många fler affärer", "Ja, helt säkert", "Ja, om du känner dig säker", "Ja, öka insatsen direkt"]}, {"q": "Vad behöver du veta för att räkna förväntat värde?", "o": ["Vinstchans, snittvinst och snittförlust", "Bara antalet affärer", "Aktiens färg", "Mäklarens namn"]}, {"m": [["Förväntat värde", "Snittresultat per affär"], ["Positivt", "Tjänar över tid"], ["Negativt", "Förlorar över tid"], ["Urval", "Antal affärer att bedöma"]]}]}, "x84": {"t": "Vinstfrekvens och payoff", "c": [{"t": "Vinstfrekvens", "d": "Vinstfrekvensen är hur stor andel av affärerna som går med vinst. 4 vinster av 10 affärer är 40 %."}, {"t": "Payoff", "d": "Payoff är snittvinsten delat med snittförlusten. En payoff på 2 betyder att vinnarna i snitt är dubbelt så stora som förlorarna."}, {"t": "Båda räknas", "d": "Du kan tjäna pengar trots att du förlorar oftare än du vinner, om vinnarna är tillräckligt stora. Hög vinstfrekvens med små vinster kan ändå förlora."}], "q": [{"q": "Snittvinst 300 kr och snittförlust 100 kr. Vad är payoff?", "o": ["3", "0,33", "200", "400"]}, {"q": "Med payoff 3, vilken vinstfrekvens behövs för att gå jämnt utan avgifter?", "o": ["25 %", "50 %", "75 %", "10 %"], "why": "1 ÷ (1 + 3) = 0,25. En vinst på 3 tar ut tre förluster på 1."}, {"q": "Kan man tjäna pengar med 35 % vinstfrekvens?", "o": ["Ja, om vinnarna är tillräckligt stora", "Nej, aldrig", "Bara med hävstång", "Bara i krypto"]}, {"q": "Du vinner 80 % av gångerna men förlusterna är fem gånger större än vinsterna. Hur går det?", "o": ["Du förlorar pengar", "Du blir rik", "Du går exakt jämnt", "Det går inte att räkna"], "why": "0,8 × 1 − 0,2 × 5 = 0,8 − 1 = −0,2. Förväntat värde är negativt."}, {"m": [["Vinstfrekvens", "Andel vinnande affärer"], ["Payoff", "Snittvinst delat med snittförlust"], ["Break-even", "Varken vinst eller förlust"], ["Snittförlust", "Typisk förlust per affär"]]}]}, "x85": {"t": "Drawdown", "c": [{"t": "Drawdown", "d": "Drawdown är hur mycket kontot har fallit från sin högsta nivå. Faller kontot från 10 000 till 8 000 kr är drawdown 20 %."}, {"t": "Max drawdown", "d": "Max drawdown är det största fallet som har skett. Det visar hur ont det kan göra att följa strategin."}, {"t": "Svårt att ta igen", "d": "Efter 20 % drawdown behövs 25 % uppgång för att komma tillbaka. Efter 50 % behövs 100 %. Små drawdowns är mycket lättare att reparera."}], "q": [{"q": "Kontot har varit uppe på 20 000 kr och står nu på 15 000 kr. Vad är drawdown?", "o": ["25 %", "33 %", "5 %", "15 %"], "why": "Fallet är 5 000 kr. 5 000 ÷ 20 000 = 25 %."}, {"q": "Efter 20 % drawdown, hur stor uppgång behövs för att komma tillbaka?", "o": ["25 %", "20 %", "10 %", "40 %"], "why": "Från 80 till 100 är en ökning på 20, och 20 ÷ 80 = 25 %."}, {"q": "Vad visar max drawdown?", "o": ["Det största fallet som har skett", "Den största vinsten", "Antalet affärer", "Courtaget"]}, {"q": "Varför är det viktigt att hålla drawdowns små?", "o": ["Stora fall är mycket svårare att ta igen", "Små fall ger skatteavdrag", "Det spelar ingen roll", "Mäklaren kräver det"]}, {"m": [["Drawdown", "Fall från högsta nivån"], ["Max drawdown", "Det största fallet"], ["Återhämtning", "Tillbaka till toppen"], ["−50 %", "Kräver +100 % tillbaka"]]}]}, "x86": {"t": "Positionsstorlek med ATR", "c": [{"t": "Stopp efter volatilitet", "d": "I stället för ett fast avstånd kan stoppen läggas till exempel 2 ATR från köppriset. Då anpassas stoppen till hur mycket aktien brukar svänga."}, {"t": "Formeln", "d": "Antal aktier = belopp du riskerar ÷ avståndet till stoppen. Med 2 ATR blir avståndet 2 × ATR."}, {"t": "Lika risk", "d": "En svängig aktie får en mindre position och en lugn aktie en större. Då riskerar du ungefär lika mycket i varje affär."}], "q": [{"q": "Du riskerar 400 kr, ATR är 2 kr och stoppen ligger 2 ATR bort. Hur många aktier köper du?", "o": ["100", "200", "50", "800"], "why": "Avståndet är 2 × 2 = 4 kr. 400 ÷ 4 = 100 aktier."}, {"q": "Aktie A har ATR 1 kr och aktie B har ATR 4 kr. Vilken får störst position med samma risk?", "o": ["Aktie A", "Aktie B", "Lika stora", "Ingen av dem"]}, {"q": "Varför används ATR för positionsstorlek?", "o": ["För att risken ska bli ungefär lika i varje affär", "För att alltid köpa fler aktier", "För att slippa stop-loss", "För att det är billigare"]}, {"q": "ATR är 3 kr och du köper på 60 kr. Var ligger en stopp på 2 ATR?", "o": ["54 kr", "57 kr", "66 kr", "58 kr"], "why": "2 × 3 = 6 kr. 60 − 6 = 54 kr."}, {"m": [["ATR", "Typisk svängning per dag"], ["2 ATR-stopp", "Stopp två ATR bort"], ["Svängig aktie", "Mindre position"], ["Lugn aktie", "Större position"]]}]}, "x87": {"t": "Korrelation", "c": [{"t": "Korrelation", "d": "Korrelation visar hur två saker rör sig tillsammans, från −1 till 1. Nära 1 rör de sig åt samma håll, nära −1 åt olika håll."}, {"t": "Dold risk", "d": "Om du äger fem banker har du egentligen nästan en stor affär. De påverkas av samma saker och faller ofta samtidigt."}, {"t": "I kriser", "d": "I kriser brukar korrelationen öka och många tillgångar faller samtidigt. Spridning skyddar, men inte alltid lika mycket som man tror."}], "q": [{"q": "Två aktier har korrelation 0,95. Vad betyder det?", "o": ["De rör sig nästan likadant", "De rör sig helt olika", "De har inget samband", "De kostar lika mycket"]}, {"q": "Du äger fem bankaktier. Vad är risken?", "o": ["De kan falla samtidigt av samma skäl", "Ingen risk, fem är många", "Banker kan inte falla", "Det ger extra utdelning"]}, {"q": "Vad händer ofta med korrelationen i en kris?", "o": ["Den ökar", "Den försvinner", "Den blir alltid −1", "Inget"]}, {"q": "Vilken korrelation ger bäst skydd mellan två innehav?", "o": ["Låg eller negativ", "Nära 1", "Exakt 1", "Det spelar ingen roll"]}, {"m": [["Korrelation 1", "Rör sig exakt likadant"], ["Korrelation 0", "Inget samband"], ["Korrelation −1", "Rör sig motsatt"], ["Klusterrisk", "Många liknande innehav"]]}]}, "x88": {"t": "Portföljrisk", "c": [{"t": "Öppen risk", "d": "Den öppna risken är vad du skulle förlora om alla dina stopp slog till samtidigt. Den bör ha en övre gräns."}, {"t": "Taket", "d": "Många sätter ett tak, till exempel högst 5–6 % öppen risk totalt. Även om varje affär bara riskerar 1 % kan tio affärer bli för mycket."}, {"t": "Samma sak flera gånger", "d": "Flera affärer i samma bransch eller med samma idé räknas som en större affär. Räkna ihop risken för dem."}], "q": [{"q": "Du har 8 affärer som var och en riskerar 1 % av kontot. Vad är den öppna risken?", "o": ["8 %", "1 %", "0,125 %", "80 %"]}, {"q": "Vad är öppen risk?", "o": ["Förlusten om alla stopp slår till samtidigt", "Vinsten om alla mål nås", "Avgiften för kontot", "Börsens öppettider"]}, {"q": "Du har tre affärer i olika techbolag med samma idé. Hur bör du se på risken?", "o": ["Som en större samlad affär", "Som tre helt separata risker", "Som riskfritt", "Som en utdelning"]}, {"q": "Varför bör den totala öppna risken ha ett tak?", "o": ["Så att en dålig dag inte skadar kontot för mycket", "För att få mer utdelning", "För att börsen kräver det", "Det behövs inte"]}, {"m": [["Öppen risk", "Summan av alla stopp"], ["Tak", "Högsta tillåtna risk"], ["Samma idé", "Räknas ihop"], ["Portfölj", "Alla innehav tillsammans"]]}]}, "x89": {"t": "Kelly-kriteriet", "c": [{"t": "Kelly", "d": "Kelly-kriteriet är en formel som räknar ut hur stor del av kontot man borde satsa för att växa snabbast i teorin: vinstchans minus förlustchans delat med payoff."}, {"t": "Stora svängningar", "d": "Full Kelly ger ofta väldigt stora insatser och djupa fall. Många använder därför halva Kelly eller ännu mindre."}, {"t": "Osäkra siffror", "d": "Formeln kräver att du vet din exakta vinstchans och payoff. I verkligheten är de osäkra, så det är klokt att satsa mindre än formeln säger."}], "q": [{"q": "Vinstchans 50 % och payoff 2. Vad säger Kelly (0,5 − 0,5 ÷ 2)?", "o": ["25 % av kontot", "50 % av kontot", "2 % av kontot", "100 % av kontot"], "why": "0,5 − 0,25 = 0,25, alltså 25 %. Det är mycket, därför använder många en bråkdel av Kelly."}, {"q": "Varför använder många halva Kelly eller mindre?", "o": ["Full Kelly ger stora svängningar", "Halva Kelly är olagligt", "Formeln fungerar inte alls", "För att få mer courtage"]}, {"q": "Vad måste du veta för att använda Kelly?", "o": ["Vinstchans och payoff", "Bara aktiens pris", "Mäklarens namn", "Inget"]}, {"q": "Varför är det klokt att satsa mindre än Kelly säger?", "o": ["Dina siffror är osäkra", "Kelly är alltid för lågt", "Det ger högre skatt", "Det är inte klokt"]}, {"m": [["Kelly", "Formel för insatsstorlek"], ["Halv Kelly", "Försiktigare insats"], ["Vinstchans", "Hur ofta du vinner"], ["Överinsats", "Satsa för mycket"]]}]}, "x90": {"t": "Stop-strategier", "c": [{"t": "Olika stopp", "d": "En stopp kan läggas på flera sätt: under ett stöd eller mönster, en fast procent bort, eller efter ATR. Det viktiga är att den läggs där idén är fel."}, {"t": "Tidsstopp", "d": "Ett tidsstopp stänger affären om inget har hänt efter en viss tid. Pengarna kan göra bättre nytta någon annanstans."}, {"t": "Flytta aldrig bort", "d": "Du kan flytta stoppen närmare för att skydda vinst, men aldrig längre bort för att slippa förlusten. Då växer risken utan att du märker det."}], "q": [{"q": "Var bör en stopp ligga?", "o": ["Där din idé visar sig vara fel", "Där det känns bekvämt", "Så långt bort som möjligt", "Ingenstans"]}, {"q": "Priset närmar sig din stopp. Vad ska du inte göra?", "o": ["Flytta stoppen längre bort", "Låta stoppen ligga", "Följa planen", "Andas lugnt"]}, {"q": "Vad gör ett tidsstopp?", "o": ["Stänger affären om inget hänt efter en viss tid", "Stänger börsen", "Väcker dig på morgonen", "Köper fler aktier"]}, {"q": "När är det okej att flytta stoppen?", "o": ["Närmare, för att skydda vinst", "Längre bort, för att slippa förlust", "Alltid när man är nervös", "Aldrig, inte ens närmare"]}, {"m": [["Stopp under stöd", "Idén är fel om stödet bryts"], ["ATR-stopp", "Efter normal svängning"], ["Tidsstopp", "Stäng om inget händer"], ["Trailing stop", "Följer med vinsten"]]}]}, "x91": {"t": "Risk med hävstång", "c": [{"t": "Snabbare fall", "d": "Hävstång förstärker drawdowns. Med tre gånger hävstång blir ett fall på 20 % i aktien ett fall på 60 % i din insats."}, {"t": "Tvångsförsäljning", "d": "Om kontot faller under kravet kan mäklaren sälja dina positioner, ofta på botten. Då förlorar du chansen att vänta ut fallet."}, {"t": "Mindre är mer", "d": "Om du använder hävstång, ta mindre positioner. Risken i kronor per affär ska vara lika liten som utan hävstång."}], "q": [{"q": "Med tre gånger hävstång faller aktien 20 %. Hur mycket faller din insats?", "o": ["60 %", "20 %", "23 %", "6 %"], "why": "20 % × 3 = 60 %."}, {"q": "Vad kan mäklaren göra om kontot faller under kravet?", "o": ["Sälja dina positioner", "Ge dig en bonus", "Pausa börsen", "Ingenting"]}, {"q": "Hur bör du ändra positionsstorleken om du använder hävstång?", "o": ["Ta mindre positioner", "Ta större positioner", "Inte alls", "Satsa allt"]}, {"q": "Varför är tvångsförsäljning extra dåligt?", "o": ["Den sker ofta nära botten", "Den ger alltid vinst", "Den är gratis", "Den händer aldrig"]}, {"m": [["Hävstång", "Förstärker fall"], ["Tvångsförsäljning", "Mäklaren säljer åt dig"], ["Mindre position", "Samma risk i kronor"], ["Krav", "Lägsta tillåtna värde"]]}]}, "x92": {"t": "Svarta svanar", "c": [{"t": "Svart svan", "d": "En svart svan är en sällsynt och oväntad händelse med enorm effekt, som en plötslig krasch eller pandemi. Ingen modell förutsåg den."}, {"t": "Tjocka svansar", "d": "Extrema rörelser händer oftare på börsen än många räknemodeller säger. Det kallas tjocka svansar."}, {"t": "Överlev", "d": "Du kan inte förutse svarta svanar, men du kan överleva dem: sprid riskerna, undvik stor hävstång och ha en buffert som inte är investerad."}], "q": [{"q": "Vad är en svart svan?", "o": ["En sällsynt oväntad händelse med enorm effekt", "En vanlig dag på börsen", "Ett ljusmönster", "En fågel i parken"]}, {"q": "Vad betyder tjocka svansar?", "o": ["Extrema rörelser händer oftare än modeller säger", "Priset rör sig aldrig mycket", "Grafen är tjock", "Avgifterna är höga"]}, {"q": "Hur skyddar du dig bäst mot svarta svanar?", "o": ["Sprida riskerna och undvika stor hävstång", "Förutse dem exakt", "Satsa allt på en aktie", "Låna så mycket som möjligt"]}, {"q": "Varför är det bra med en buffert som inte är investerad?", "o": ["Du slipper sälja när allt rasar", "Den ger hög avkastning", "Den är skattefri för alltid", "Det är den inte"]}, {"m": [["Svart svan", "Sällsynt chockhändelse"], ["Tjock svans", "Extremer är vanligare"], ["Buffert", "Pengar vid sidan av"], ["Överlevnad", "Viktigare än maxvinst"]]}]}, "x93": {"t": "Tankefällor", "c": [{"t": "Bekräftelsebias", "d": "Vi letar gärna efter information som stödjer det vi redan tror och ignorerar resten. Leta medvetet efter skäl till att du kan ha fel."}, {"t": "Överkonfidens", "d": "Efter några vinster tror många att de är bättre än de är. Då tar de större risker, precis när de borde vara försiktiga."}, {"t": "Efterklokhet", "d": "I efterhand känns det som att man borde ha vetat. Men det var inte lika tydligt när det hände. Döm inte dig själv efter facit."}], "q": [{"q": "Du läser bara inlägg som säger att din aktie ska stiga. Vilken tankefälla är det?", "o": ["Bekräftelsebias", "Förlustaversion", "Diversifiering", "Ombalansering"]}, {"q": "Efter fem vinster i rad dubblar du insatsen. Vad kan det vara?", "o": ["Överkonfidens", "Disciplin", "Försiktighet", "En bra plan"]}, {"q": "Hur motverkar du bekräftelsebias?", "o": ["Leta medvetet efter motargument", "Läsa ännu fler inlägg som håller med", "Sluta tänka", "Köpa mer"]}, {"q": "Vad är efterklokhet?", "o": ["Att i efterhand tro att man borde ha vetat", "Att planera i förväg", "Att använda stop-loss", "Att sova gott"]}, {"m": [["Bekräftelsebias", "Söka stöd för det man tror"], ["Överkonfidens", "Tro sig bättre än man är"], ["Efterklokhet", "Allt verkar uppenbart efteråt"], ["Ankring", "Fastna vid ett gammalt pris"]]}]}, "x94": {"t": "Förlustaversion", "c": [{"t": "Förluster gör mer ont", "d": "Forskning visar att en förlust ofta känns ungefär dubbelt så stark som en lika stor vinst. Det påverkar våra beslut mer än vi tror."}, {"t": "Dispositionseffekten", "d": "Många säljer vinnare för tidigt för att säkra vinsten, och behåller förlorare för länge i hopp om att de ska vända. Det är ofta tvärtom mot vad som lönar sig."}, {"t": "Lösningen", "d": "Bestäm stopp och mål innan du går in. Då fattar du beslutet med lugnt huvud i stället för när känslorna tar över."}], "q": [{"q": "Ungefär hur mycket starkare känns en förlust än en lika stor vinst?", "o": ["Ungefär dubbelt så stark", "Lika stark", "Hälften så stark", "Tio gånger starkare"]}, {"q": "Vad är dispositionseffekten?", "o": ["Sälja vinnare för tidigt och behålla förlorare för länge", "Att köpa på botten", "Att följa planen", "Att sprida riskerna"]}, {"q": "Hur minskar du effekten av förlustaversion?", "o": ["Bestäm stopp och mål innan du går in", "Ta bort stoppen när det går dåligt", "Titta på kursen hela tiden", "Köpa mer av förlorare"]}, {"q": "Din aktie har fallit 30 % och du väntar på att den ska komma tillbaka utan plan. Vad kan det vara?", "o": ["Förlustaversion", "Disciplin", "Diversifiering", "Trendföljning"]}, {"m": [["Förlustaversion", "Förluster känns starkare"], ["Dispositionseffekt", "Behålla förlorare för länge"], ["Förhandsbeslut", "Stopp och mål i förväg"], ["Hopp", "Ingen strategi"]]}]}, "x95": {"t": "Disciplin och rutiner", "c": [{"t": "Regler", "d": "Disciplin betyder att följa dina regler även när det känns jobbigt. Reglerna skyddar dig mot impulsbeslut."}, {"t": "Checklista", "d": "En kort checklista innan varje affär hjälper: trend, nivå, bekräftelse, stopp, positionsstorlek. Bocka av allt innan du klickar."}, {"t": "Samma rutin", "d": "Gör samma saker i samma ordning varje dag, till exempel kolla kalendern, gå igenom grafer och skriv ner planen. Rutiner minskar stress."}], "q": [{"q": "Vad betyder disciplin i trading?", "o": ["Att följa sina regler även när det är jobbigt", "Att handla så ofta som möjligt", "Att aldrig förlora", "Att följa sin känsla"]}, {"q": "Vilket hör hemma på en checklista före en affär?", "o": ["Stopp och positionsstorlek", "Vad vännerna tycker", "Väderprognosen", "Inget, bara klicka"]}, {"q": "Varför hjälper rutiner?", "o": ["De minskar stress och impulsbeslut", "De garanterar vinst", "De tar bort all risk", "De gör börsen snällare"]}, {"q": "Allt på checklistan är inte uppfyllt, men det känns bra. Vad gör en disciplinerad trader?", "o": ["Avstår från affären", "Köper ändå", "Köper dubbelt", "Struntar i stoppen"]}, {"m": [["Disciplin", "Följa reglerna"], ["Checklista", "Bocka av före affär"], ["Rutin", "Samma steg varje dag"], ["Impuls", "Beslut utan plan"]]}]}, "x96": {"t": "Tradingdagboken", "c": [{"t": "Skriv ner allt", "d": "I en tradingdagbok skriver du varje affär: varför du gick in, var stoppen låg, hur det gick och hur du kände dig."}, {"t": "Hitta mönster", "d": "Efter många affärer kan du se dina egna mönster, till exempel att du förlorar mest på fredagar eller när du är trött."}, {"t": "Lär av misstagen", "d": "Dagboken gör förluster till lektioner. Utan den upprepar många samma misstag om och om igen."}], "q": [{"q": "Vad skriver man i en tradingdagbok?", "o": ["Varför, stopp, resultat och känsla", "Bara vinsterna", "Inköpslistan", "Ingenting"]}, {"q": "Varför är dagboken nyttig?", "o": ["Du ser dina egna mönster och misstag", "Den ger skatteavdrag", "Börsen kräver den", "Den förutser framtiden"]}, {"q": "Dagboken visar att du förlorar mest när du är trött. Vad är klokt?", "o": ["Låta bli att handla när du är trött", "Handla mer när du är trött", "Sluta skriva dagbok", "Strunta i det"]}, {"q": "Vad händer ofta utan dagbok?", "o": ["Man upprepar samma misstag", "Man vinner alltid", "Man slipper skatt", "Ingenting"]}, {"m": [["Dagbok", "Logg över alla affärer"], ["Varför", "Skälet till affären"], ["Känsla", "Hur du mådde"], ["Utvärdering", "Läs och lär"]]}]}, "x97": {"t": "Stress och sömn", "c": [{"t": "Trötthet", "d": "När du är trött eller stressad fattar du sämre och mer impulsiva beslut. Sömn är en del av riskhanteringen."}, {"t": "Pauser", "d": "Korta pauser hjälper hjärnan att återhämta sig. Res dig, rör på dig och titta bort från skärmen en stund."}, {"t": "Förlustgräns för dagen", "d": "Bestäm i förväg hur mycket du högst får förlora på en dag. Når du gränsen slutar du för dagen, hur det än känns."}], "q": [{"q": "Hur påverkar trötthet dina beslut?", "o": ["De blir sämre och mer impulsiva", "De blir bättre", "Inte alls", "De blir långsammare men smartare"]}, {"q": "Vad gör du när du når din förlustgräns för dagen?", "o": ["Slutar för dagen", "Dubblar insatsen", "Höjer gränsen", "Tar bort stoppen"]}, {"q": "Varför är sömn en del av riskhanteringen?", "o": ["Utvilad fattar du bättre beslut", "Börsen är stängd på natten", "Det är inte det", "Mäklaren kräver det"]}, {"q": "Vad är en bra paus?", "o": ["Resa sig, röra på sig och titta bort från skärmen", "Kolla fler grafer på mobilen", "Läsa forum om aktier", "Handla snabbare"]}, {"m": [["Sömn", "Ger bättre beslut"], ["Paus", "Låter hjärnan vila"], ["Förlustgräns", "Sluta för dagen"], ["Stress", "Ger impulsbeslut"]]}]}, "x98": {"t": "Sociala medier och hype", "c": [{"t": "Pump and dump", "d": "Vissa köper en liten aktie, hajpar den på nätet och säljer när andra köper. Kvar blir de som köpte sist, med förluster."}, {"t": "Vem tjänar på tipset?", "d": "Fråga alltid vem som tjänar på att du följer ett tips. Många som visar upp stora vinster tjänar mest på kurser, reklam eller provisioner."}, {"t": "Du ser bara vinnarna", "d": "De som förlorade pengar lägger sällan upp det. Därför ser trading lättare ut på nätet än det är. Det kallas överlevnadsbias."}], "q": [{"q": "Vad är pump and dump?", "o": ["Hajpa en aktie och sälja när andra köper", "En sorts indexfond", "Ett ljusmönster", "En lugn strategi"]}, {"q": "En influencer visar stora vinster och säljer en kurs. Vad bör du fundera på?", "o": ["Vem som tjänar på att du köper", "Att köpa kursen direkt", "Att låna pengar till den", "Ingenting"]}, {"q": "Varför ser trading lättare ut på nätet än det är?", "o": ["De som förlorar visar det sällan", "Det är lätt", "Alla vinner på nätet", "Börsen ljuger"]}, {"q": "En okänd aktie rusar 200 % på en dag efter inlägg på sociala medier. Vad är klokast?", "o": ["Hålla dig borta", "Köpa allt du kan", "Låna och köpa", "Dela inlägget"]}, {"m": [["Pump and dump", "Hajpa och sälja"], ["Överlevnadsbias", "Man ser bara vinnarna"], ["Hype", "Överdriven uppmärksamhet"], ["Intressekonflikt", "Tipsaren tjänar på dig"]]}]}, "x99": {"t": "Följa planen", "c": [{"t": "Om–så-regler", "d": "Skriv planen som om–så-regler: om priset bryter under stödet, så säljer jag. Då vet du vad du ska göra innan det händer."}, {"t": "Ändra inte mitt i", "d": "Ändra planen när marknaden är stängd och du är lugn, inte mitt i en affär när känslorna är starka."}, {"t": "Process före resultat", "d": "En affär som följde planen men förlorade var ändå en bra affär. En vinst utan plan var tur. Bedöm processen, inte bara resultatet."}], "q": [{"q": "Vilken är en bra om–så-regel?", "o": ["Om priset bryter under stödet, så säljer jag", "Om det känns rätt, så köper jag", "Om någon tipsar, så köper jag allt", "Om jag förlorar, så tar jag bort stoppen"]}, {"q": "När är det bäst att ändra sin plan?", "o": ["När marknaden är stängd och du är lugn", "Mitt i en förlustaffär", "När du är arg", "Aldrig, under några omständigheter"]}, {"q": "Du följde planen men förlorade 1 %. Hur bör du se på affären?", "o": ["Som en bra affär som gav förlust", "Som ett stort misslyckande", "Som ett skäl att slänga planen", "Som ett skäl att dubbla"]}, {"q": "Vad är en vinst utan plan?", "o": ["Tur", "Skicklighet", "En bra process", "Ett bevis på att du är bäst"]}, {"m": [["Om–så-regel", "Beslut i förväg"], ["Process", "Hur du fattar beslut"], ["Resultat", "Hur det gick"], ["Tur", "Vinst utan plan"]]}]}, "x100": {"t": "När man ska sluta", "c": [{"t": "Paus efter förluster", "d": "Efter flera förluster i rad är det lätt att börja jaga pengarna tillbaka. Ta en paus i stället, till exempel resten av dagen."}, {"t": "Strategin fungerar inte", "d": "Om strategin förlorar under lång tid trots att du följer den, sluta och utvärdera. Fortsätt inte bara för att du redan lagt ner mycket."}, {"t": "Livet först", "d": "Om trading påverkar sömn, ekonomi, skola, jobb eller relationer negativt är det ett tydligt tecken på att det är dags att sluta eller ta en lång paus."}], "q": [{"q": "Du har förlorat fyra affärer i rad och vill vinna tillbaka direkt. Vad är klokt?", "o": ["Ta en paus resten av dagen", "Dubbla nästa insats", "Låna pengar", "Ta bort alla stopp"]}, {"q": "Strategin har förlorat i ett år trots att du följt den. Vad bör du göra?", "o": ["Sluta och utvärdera", "Satsa mer för att ta igen", "Fortsätta för att du lagt ner mycket", "Inte tänka på det"]}, {"q": "Vilket är ett tecken på att det är dags att sluta trada?", "o": ["Det påverkar sömn och relationer negativt", "Du har en tradingdagbok", "Du följer din plan", "Du tar pauser"]}, {"q": "Vad kallas det att fortsätta bara för att man redan lagt ner mycket?", "o": ["Sunk cost-fällan", "Diversifiering", "Ombalansering", "Trendföljning"]}, {"m": [["Paus", "Bryter en förlustspiral"], ["Utvärdering", "Se vad som inte fungerar"], ["Sunk cost", "Pengar som redan är borta"], ["Varningstecken", "Trading skadar livet"]]}]}, "x101": {"t": "Spel och varningssignaler", "c": [{"t": "När trading blir spel", "d": "Utan plan och med stor risk blir trading mer som spel än som ett hantverk. Snabba vinster och förluster kan påverka hjärnan på samma sätt som spel."}, {"t": "Varningssignaler", "d": "Exempel på varningssignaler: du jagar förluster, döljer dem för andra, lånar pengar för att handla eller tänker på det hela tiden."}, {"t": "Det finns hjälp", "d": "Känner du igen dig, prata med någon du litar på. I Sverige kan du ringa Stödlinjen för spelare och anhöriga på 020-81 91 00. Det är gratis."}], "q": [{"q": "Vilket är ett varningstecken?", "o": ["Du lånar pengar för att handla", "Du skriver tradingdagbok", "Du följer en plan", "Du tar pauser"]}, {"q": "När blir trading mer som spel?", "o": ["Utan plan och med stor risk", "Med en tydlig plan och liten risk", "När man månadssparar", "När man läser rapporter"]}, {"q": "Du döljer dina förluster för familjen. Vad är klokt?", "o": ["Prata med någon du litar på", "Försöka vinna tillbaka allt i hemlighet", "Låna mer", "Handla mer på natten"]}, {"q": "Vad gör Stödlinjen?", "o": ["Hjälper spelare och anhöriga gratis", "Ger aktietips", "Lånar ut pengar", "Säljer kurser"]}, {"m": [["Jaga förluster", "Försöka vinna tillbaka direkt"], ["Dölja", "Hemlighålla förluster"], ["Låna för att handla", "Tydligt varningstecken"], ["Stödlinjen", "Gratis hjälp i Sverige"]]}]}, "x102": {"t": "Långsiktigt tänkande", "c": [{"t": "Små steg", "d": "Att bli bättre på trading tar tid. Små förbättringar varje vecka blir stora efter ett år."}, {"t": "Tålamod", "d": "De bästa tillfällena kommer inte varje dag. Att vänta på rätt läge är också ett beslut, och ofta ett klokt sådant."}, {"t": "Kunskap växer", "d": "Precis som pengar kan kunskap växa med ränta på ränta. Allt du lär dig gör nästa sak lättare att förstå."}], "q": [{"q": "Vad leder små förbättringar varje vecka till?", "o": ["Stora förbättringar över tid", "Ingenting", "Snabb rikedom", "Mer stress"]}, {"q": "Det finns inget bra läge i dag. Vad gör en tålmodig trader?", "o": ["Väntar", "Handlar ändå för att ha något att göra", "Tar större risk", "Följer ett tips på nätet"]}, {"q": "Hur kan kunskap växa med ränta på ränta?", "o": ["Allt du lär dig gör nästa sak lättare", "Den kan inte det", "Genom att låna böcker", "Genom att handla mer"]}, {"q": "Vad är viktigast i början?", "o": ["Att lära sig och skydda pengarna", "Att tjäna så mycket som möjligt snabbt", "Att ta stora risker", "Att följa alla tips"]}, {"m": [["Tålamod", "Vänta på rätt läge"], ["Små steg", "Blir stora över tid"], ["Kunskap", "Växer som ränta på ränta"], ["Långsiktighet", "Tänka i år, inte dagar"]]}]}, "x103": {"t": "Välja mäklare", "c": [{"t": "Vad gör en mäklare?", "d": "En nätmäklare eller bank låter dig köpa och sälja aktier och fonder. Du behöver ett konto hos någon för att kunna handla på börsen."}, {"t": "Jämför avgifter", "d": "Titta på courtage (avgift per affär), valutaväxling och eventuella månadsavgifter. Små avgifter blir stora om du handlar ofta."}, {"t": "Tillstånd från FI", "d": "Välj en mäklare som har tillstånd från Finansinspektionen (FI). Du kan söka i FI:s företagsregister innan du öppnar konto."}], "q": [{"q": "Vad är courtage?", "o": ["En avgift per affär", "En sorts aktie", "En skatt på lön", "En utdelning"]}, {"q": "Vad bör du kontrollera innan du väljer mäklare?", "o": ["Att den har tillstånd från FI", "Att den har snyggast logga", "Att en influencer gillar den", "Att den lovar hög avkastning"]}, {"q": "Varför spelar små avgifter roll?", "o": ["De blir stora om du handlar ofta", "De spelar ingen roll", "De ger dig ränta", "De sänker skatten"]}, {"q": "Vilken avgift kan tillkomma när du köper utländska aktier?", "o": ["Valutaväxlingsavgift", "Parkeringsavgift", "Tv-licens", "Ingen alls, någonsin"]}, {"m": [["Mäklare", "Låter dig handla"], ["Courtage", "Avgift per affär"], ["FI", "Svensk tillsynsmyndighet"], ["Valutaväxling", "Avgift för utländskt"]]}]}, "x104": {"t": "ISK, KF och AF", "c": [{"t": "ISK", "d": "Investeringssparkonto. Du betalar ingen skatt på vinster eller utdelningar. I stället betalar du en liten schablonskatt varje år, beräknad på kontots värde."}, {"t": "KF", "d": "Kapitalförsäkring. Beskattas ungefär som ISK med schablonskatt, men tekniskt sett är det en försäkring och någon annan äger värdepapperen."}, {"t": "AF och skattefri nivå", "d": "På ett vanligt aktie- och fondkonto (AF) betalar du 30 % skatt på vinsten när du säljer. Från 2026 är sparande på ISK och KF skattefritt upp till 300 000 kr per person sammanlagt."}], "q": [{"q": "Hur beskattas ett ISK?", "o": ["Med en liten schablonskatt på värdet varje år", "30 % på varje vinst", "Det beskattas aldrig", "Med moms"]}, {"q": "Hur mycket skatt betalar du på vinsten på ett AF-konto?", "o": ["30 %", "0 %", "50 %", "10 %"]}, {"q": "Hur stor är den skattefria nivån för ISK och KF från 2026?", "o": ["300 000 kr per person", "300 000 kr per konto", "Ingen gräns", "10 000 kr"]}, {"q": "Vem äger värdepapperen i en KF?", "o": ["Försäkringsbolaget", "Du själv", "Staten", "Börsen"]}, {"m": [["ISK", "Schablonskatt, eget konto"], ["KF", "Försäkring med schablonskatt"], ["AF", "30 % på vinsten"], ["Skattefri nivå", "300 000 kr per person"]]}]}, "x105": {"t": "Skatt på aktier", "c": [{"t": "Vinst och förlust", "d": "På ett AF-konto räknar du vinst som försäljningspris minus anskaffningsvärde. Courtage räknas in. Vinsten beskattas med 30 %."}, {"t": "Genomsnittsmetoden", "d": "Köper du samma aktie flera gånger räknar du ut ett genomsnittligt inköpspris. Det används sedan när du säljer."}, {"t": "Deklarationen", "d": "Försäljningar på AF redovisas i deklarationen. Mäklaren lämnar ofta uppgifter till Skatteverket, men du ansvarar för att det blir rätt. På ISK behöver du inte redovisa varje affär."}], "q": [{"q": "Du köper för 10 000 kr och säljer för 12 000 kr på AF. Hur stor är skatten (utan courtage)?", "o": ["600 kr", "2 000 kr", "3 600 kr", "0 kr"], "why": "Vinsten är 2 000 kr och 30 % av det är 600 kr."}, {"q": "Du köper 10 aktier för 100 kr och 10 för 200 kr. Vad är genomsnittspriset?", "o": ["150 kr", "100 kr", "200 kr", "300 kr"]}, {"q": "Vem ansvarar för att deklarationen blir rätt?", "o": ["Du själv", "Börsen", "Företaget du äger aktier i", "Ingen"]}, {"q": "Behöver du redovisa varje affär på ett ISK i deklarationen?", "o": ["Nej", "Ja, varje affär", "Bara förlusterna", "Bara på fredagar"]}, {"m": [["Anskaffningsvärde", "Vad du betalade"], ["Genomsnittsmetod", "Snittpris på flera köp"], ["Skatteverket", "Svenska skattemyndigheten"], ["Kapitalvinst", "Beskattas med 30 %"]]}]}, "x106": {"t": "Fondavgifter", "c": [{"t": "Årlig avgift", "d": "Fonder tar en årlig avgift i procent av ditt sparande. Den dras automatiskt, så du ser den inte på något kvitto."}, {"t": "Index eller aktiv", "d": "Indexfonder följer ett index och har oftast låga avgifter. Aktiva fonder kostar mer, och många av dem slår inte index över tid."}, {"t": "Avgiften växer", "d": "En avgift på 1,5 % i stället för 0,2 % kan kosta tiotusentals kronor över många år, eftersom den tas varje år på ett växande belopp."}], "q": [{"q": "Hur tas fondens årliga avgift?", "o": ["Automatiskt från fondens värde", "Med en faktura i brevlådan", "Kontant på banken", "Den tas aldrig"]}, {"q": "Vilken fondtyp har oftast lägst avgift?", "o": ["Indexfond", "Aktiv fond", "Hedgefond", "Alla kostar lika"]}, {"q": "Varför kan en skillnad på ett par procent bli så dyr?", "o": ["Den tas varje år på ett växande belopp", "Den tas bara en gång", "Den kan inte bli dyr", "Den betalas av staten"]}, {"q": "Vad gäller för många aktiva fonder över tid?", "o": ["De slår inte index", "De slår alltid index", "De är gratis", "De är riskfria"]}, {"m": [["Årlig avgift", "Procent varje år"], ["Indexfond", "Följer index billigt"], ["Aktiv fond", "Förvaltare väljer, dyrare"], ["Ränta på ränta", "Gäller även avgifter"]]}]}, "x107": {"t": "Pension", "c": [{"t": "Tre delar", "d": "Svensk pension består ofta av tre delar: allmän pension från staten, tjänstepension från arbetsgivaren och ditt eget privata sparande."}, {"t": "Premiepension", "d": "En liten del av den allmänna pensionen är premiepensionen. Där kan du själv välja fonder, eller låta pengarna ligga i statens förvalda alternativ."}, {"t": "Tid är din vän", "d": "Pensionen sparas under hela arbetslivet. Ju tidigare pengarna börjar växa, desto mer hinner ränta på ränta göra. Du kan se din samlade pension på minPension.se."}], "q": [{"q": "Vilka är pensionens tre delar?", "o": ["Allmän pension, tjänstepension och eget sparande", "Lön, semester och bonus", "Aktier, guld och krypto", "Bara statens pension"]}, {"q": "Var kan du själv välja fonder i den allmänna pensionen?", "o": ["I premiepensionen", "I lönen", "I sparkontot på banken", "Ingenstans"]}, {"q": "Vem betalar in tjänstepension?", "o": ["Arbetsgivaren", "Börsen", "Banken av välvilja", "Ingen"]}, {"q": "Var kan du se hela din pension samlad?", "o": ["minPension.se", "På sociala medier", "I ett aktieforum", "Det går inte"]}, {"m": [["Allmän pension", "Från staten"], ["Tjänstepension", "Från arbetsgivaren"], ["Premiepension", "Du kan välja fonder"], ["Privat sparande", "Ditt eget"]]}]}, "x108": {"t": "Konsumentskydd", "c": [{"t": "Finansinspektionen", "d": "FI är myndigheten som har tillsyn över banker, mäklare och fondbolag i Sverige. De har också en varningslista över bolag som saknar tillstånd."}, {"t": "Investerarskydd", "d": "Om en svensk mäklare går i konkurs och dina värdepapper saknas kan investerarskyddet ersätta upp till 250 000 kr. Det skyddar inte mot att aktierna faller."}, {"t": "Hjälp och klagomål", "d": "Konsumenternas Bank- och finansbyrå ger gratis råd. Är du missnöjd kan du först klaga hos företaget och sedan vända dig till Allmänna reklamationsnämnden (ARN)."}], "q": [{"q": "Vad gör Finansinspektionen?", "o": ["Har tillsyn över finansiella företag", "Ger aktietips", "Garanterar vinster", "Driver börsen"]}, {"q": "Vad skyddar investerarskyddet mot?", "o": ["Att mäklaren går i konkurs och dina värdepapper saknas", "Att aktierna faller", "Dåliga affärer", "Höga avgifter"]}, {"q": "Hur mycket kan investerarskyddet ersätta som mest?", "o": ["250 000 kr", "Allt, utan gräns", "1 000 kr", "Ingenting"]}, {"q": "Du är missnöjd med din bank. Vad gör du först?", "o": ["Klagar hos banken", "Skriver på sociala medier", "Slutar betala räkningar", "Gör ingenting"]}, {"m": [["FI", "Tillsyn och varningslista"], ["Investerarskydd", "Upp till 250 000 kr"], ["ARN", "Prövar tvister"], ["Konsumenternas", "Gratis råd"]]}]}, "x109": {"t": "Bedrägerier på djupet", "c": [{"t": "Vanliga upplägg", "d": "Falska plattformar, påhittade kändisreklam, kryptobedrägerier och romansbedrägerier där någon bygger förtroende och sedan ber dig investera."}, {"t": "Röda flaggor", "d": "Löfte om hög och säker avkastning, tidspress, krav på att installera ett fjärrstyrningsprogram eller att du ska legitimera dig med BankID åt någon annan."}, {"t": "Om det har hänt", "d": "Kontakta din bank direkt så att de kan försöka stoppa betalningar, och polisanmäl. Skäms inte, bedragare är skickliga och lurar många."}], "q": [{"q": "Någon ringer och ber dig logga in med BankID för att 'skydda ditt konto'. Vad gör du?", "o": ["Lägger på och ringer banken själv", "Loggar in direkt", "Ger dem koden", "Installerar deras program"]}, {"q": "Vilket är en röd flagga?", "o": ["Löfte om hög och säker avkastning", "Tillstånd från FI", "Tydliga avgifter", "Tid att tänka"]}, {"q": "Vad är ett romansbedrägeri?", "o": ["Någon bygger förtroende och ber dig sedan investera", "En vanlig indexfond", "En sorts utdelning", "Ett ljusmönster"]}, {"q": "Du har blivit lurad. Vad gör du först?", "o": ["Kontaktar banken direkt och polisanmäler", "Skickar mer pengar för att få tillbaka", "Säger inget till någon", "Väntar några månader"]}, {"m": [["Fjärrstyrning", "Låt aldrig okända styra datorn"], ["Kändisreklam", "Ofta påhittad"], ["Tidspress", "Röd flagga"], ["Polisanmälan", "Gör det direkt"]]}]}, "x110": {"t": "Hållbara investeringar", "c": [{"t": "ESG", "d": "ESG står för miljö (Environmental), socialt ansvar (Social) och bolagsstyrning (Governance). Det är ett sätt att bedöma hur ansvarsfullt ett bolag sköts."}, {"t": "Välja bort och välja in", "d": "Vissa fonder väljer bort branscher som vapen eller tobak. Andra väljer aktivt in bolag som gör bra saker, till exempel inom förnybar energi."}, {"t": "Grönmålning", "d": "Att kalla något hållbart betyder inte att det är det. Läs vad fonden faktiskt äger och vilka regler den följer. Det kallas grönmålning när ett bolag överdriver."}], "q": [{"q": "Vad står G i ESG för?", "o": ["Bolagsstyrning", "Guld", "Garanti", "Grafer"]}, {"q": "Vad är grönmålning?", "o": ["Att överdriva hur hållbart något är", "Att måla kontoret grönt", "En sorts indexfond", "Ett köpsignal"]}, {"q": "En fond som inte äger vapen- eller tobaksbolag använder vilken metod?", "o": ["Väljer bort", "Hävstång", "Blankning", "Daytrading"]}, {"q": "Hur kontrollerar du om en fond verkligen är hållbar?", "o": ["Läser vad den faktiskt äger", "Litar på namnet", "Tittar på färgen i reklamen", "Frågar en influencer"]}, {"m": [["E", "Miljö"], ["S", "Socialt ansvar"], ["G", "Bolagsstyrning"], ["Grönmålning", "Överdriven hållbarhet"]]}]}, "x111": {"t": "Din egen plan", "c": [{"t": "Buffert först", "d": "Innan du investerar: ha en buffert för oväntade utgifter och betala av dyra lån. Pengar du snart behöver ska inte ligga i aktier."}, {"t": "Mål och tid", "d": "Skriv ner vad du sparar till och när du behöver pengarna. Lång tid gör att du kan ta mer risk, kort tid kräver mindre risk."}, {"t": "Kärna och lek", "d": "Många har en stor kärna i breda indexfonder och en liten del, till exempel 5–10 %, för att öva trading. Då riskerar du aldrig hela sparandet."}], "q": [{"q": "Vad bör du ha innan du börjar investera?", "o": ["En buffert för oväntade utgifter", "Ett dyrt lån", "Ett tips från nätet", "Ingenting"]}, {"q": "Du behöver pengarna om sex månader. Hur mycket risk passar?", "o": ["Låg risk", "Så hög som möjligt", "Hävstång", "Bara krypto"]}, {"q": "Vad är tanken med 'kärna och lek'?", "o": ["Att aldrig riskera hela sparandet", "Att satsa allt på en aktie", "Att bara leka och inte spara", "Att låna till trading"]}, {"q": "Vad bör du göra med dyra lån innan du investerar?", "o": ["Betala av dem", "Ta fler", "Ignorera dem", "Investera lånade pengar"]}, {"m": [["Buffert", "Pengar för oväntat"], ["Mål", "Vad du sparar till"], ["Kärna", "Breda indexfonder"], ["Lekdel", "Liten del för att öva"]]}]}, "x112": {"t": "Slutprov", "c": [{"t": "Allt hänger ihop", "d": "Du har lärt dig om ljus, mönster, indikatorer, risk, psykologi och svenska regler. Ett bra beslut använder flera delar samtidigt."}, {"t": "Risk före vinst", "d": "Det viktigaste av allt: bestäm hur mycket du kan förlora innan du tänker på hur mycket du kan vinna."}, {"t": "Fortsätt lära", "d": "Slutprovet är inte slutet. Repetera, öva med låtsaspengar och skriv dagbok. Wicki finns kvar här när du vill fräscha upp något."}], "q": [{"q": "Vad visar ett grönt ljus?", "o": ["Att priset stängde högre än det öppnade", "Att priset föll", "Att börsen är stängd", "Att man ska köpa direkt"]}, {"q": "Du har 50 000 kr och riskerar 1 % per affär. Hur mycket får du förlora på en affär?", "o": ["500 kr", "5 000 kr", "50 kr", "50 000 kr"]}, {"q": "RSI ligger på 80. Vad betyder det oftast?", "o": ["Att det är överköpt", "Att det är översålt", "Att volymen är noll", "Ingenting"]}, {"q": "Du har förlorat tre gånger i rad och vill dubbla insatsen. Vad är klokt?", "o": ["Ta en paus och följ planen", "Dubbla", "Låna pengar", "Ta bort stoppen"]}, {"q": "Vilket konto ger schablonskatt i stället för skatt på varje vinst?", "o": ["ISK", "AF", "Lönekonto", "Inget konto"]}, {"m": [["Stop-loss", "Begränsar förlusten"], ["Diversifiering", "Sprider risken"], ["Tradingdagbok", "Lär av misstag"], ["Stödlinjen", "Hjälp vid spelproblem"]]}]}, "x113": {"t": "Första lönen och budget", "c": [{"t": "Brutto och netto", "d": "Bruttolön är lönen före skatt. Nettolön är det som faktiskt kommer in på kontot. Tjänar du 10 000 kr brutto på sommarjobbet får du ofta runt 7 000–8 000 kr netto, beroende på kommun och hur mycket du tjänar under året."}, {"t": "Budget", "d": "En budget är en plan för pengarna: vad som kommer in och vad som går ut. Skriv upp mobil, mat, nöjen och resor. Då ser du var pengarna faktiskt tar vägen."}, {"t": "Betala dig själv först", "d": "Flytta en del till sparande direkt när lönen kommer, till exempel 10 %. Det som blir kvar får du använda. Sparar du bara det som blir över blir det ofta ingenting."}], "q": [{"q": "Vad är nettolön?", "o": ["Det som kommer in på kontot efter skatt", "Lönen före skatt", "Semesterersättningen", "Skatten"]}, {"q": "Du får 8 000 kr netto och sparar 10 % direkt. Hur mycket sparar du?", "o": ["800 kr", "80 kr", "8 000 kr", "1 000 kr"]}, {"q": "Vad betyder 'betala dig själv först'?", "o": ["Spara en del direkt när lönen kommer", "Köpa något kul först", "Betala räkningar sist", "Låna till nöjen"]}, {"q": "Varför hjälper en budget?", "o": ["Du ser var pengarna tar vägen", "Du får högre lön", "Du slipper skatt", "Den gör aktier säkra"]}, {"m": [["Brutto", "Före skatt"], ["Netto", "Efter skatt"], ["Budget", "Plan för pengarna"], ["Spara först", "Innan du spenderar"]]}]}, "x114": {"t": "Buffert och sparmål", "c": [{"t": "Buffert", "d": "En buffert är pengar för oväntade saker, som en trasig mobil eller cykel. Ha den på ett vanligt sparkonto, inte i aktier, så att du kan ta ut den direkt."}, {"t": "Sparmål", "d": "Ett tydligt mål gör det lättare att spara. Vill du ha 6 000 kr till körkortslektioner om ett år behöver du spara 500 kr i månaden."}, {"t": "Kort eller lång tid", "d": "Pengar du behöver inom ett par år ska ligga tryggt. Pengar du inte behöver på många år kan du spara i till exempel en indexfond, där värdet går upp och ner på vägen."}], "q": [{"q": "Var passar en buffert bäst?", "o": ["På ett vanligt sparkonto", "I en enda aktie", "I krypto", "I en CFD"]}, {"q": "Du vill ha 3 600 kr om ett år. Hur mycket sparar du per månad?", "o": ["300 kr", "360 kr", "100 kr", "3 600 kr"], "why": "3 600 delat med 12 månader är 300 kr."}, {"q": "Du behöver pengarna om sex månader. Var är det klokt att ha dem?", "o": ["På ett sparkonto", "I en populär aktie", "I krypto", "Med hävstång"]}, {"q": "Vad är en buffert till för?", "o": ["Oväntade utgifter", "Att trada med", "Att låna ut", "Att köpa kläder varje vecka"]}, {"m": [["Buffert", "Pengar för oväntat"], ["Sparmål", "Vad du sparar till"], ["Kort tid", "Spara tryggt"], ["Lång tid", "Kan tåla svängningar"]]}]}, "x115": {"t": "Lån och krediter", "c": [{"t": "Köp nu, betala sen", "d": "När du väljer att betala senare i en nätbutik tar du ett lån. Missar du att betala kommer avgifter och ränta, och skulden kan gå till inkasso."}, {"t": "Effektiv ränta", "d": "Den effektiva räntan visar vad lånet verkligen kostar per år, med alla avgifter. Den är bättre att jämföra än den vanliga räntan."}, {"t": "Avbetalning på en mobil", "d": "En mobil för 12 000 kr på avbetalning med höga avgifter kan kosta flera tusen kronor extra. Att spara ihop först gör den billigare."}], "q": [{"q": "Du väljer 'betala senare' i en nätbutik. Vad har du gjort?", "o": ["Tagit ett lån", "Fått något gratis", "Sparat pengar", "Investerat"]}, {"q": "Vilken ränta ska du jämföra mellan lån?", "o": ["Den effektiva räntan", "Den lägsta siffran i reklamen", "Ingen, alla lån är lika", "Månadsbeloppet"]}, {"q": "Vad kan hända om du missar en betalning?", "o": ["Avgifter, ränta och inkasso", "Ingenting", "Skulden försvinner", "Du får rabatt"]}, {"q": "Vilket är oftast billigast?", "o": ["Spara ihop och betala direkt", "Avbetalning med avgifter", "Sms-lån", "Kreditkort som inte betalas"]}, {"m": [["Betala senare", "Ett lån"], ["Effektiv ränta", "Hela kostnaden per år"], ["Inkasso", "Obetald skuld drivs in"], ["Spara först", "Oftast billigast"]]}]}, "x116": {"t": "Ränta på ränta i praktiken", "c": [{"t": "Små belopp växer", "d": "Om du sparar 300 kr i månaden i 10 år har du satt in 36 000 kr. Med en tänkt avkastning på 6 % per år kan det ha växt till ungefär 49 000 kr. Avkastningen är aldrig garanterad."}, {"t": "Tid slår belopp", "d": "Den som börjar vid 18 har många fler år av ränta på ränta än den som börjar vid 35. Att börja tidigt med lite kan slå att börja sent med mer."}, {"t": "Ränta på ränta på skulder", "d": "Ränta på ränta fungerar också åt andra hållet. En obetald skuld med hög ränta växer snabbt. Betala dyra skulder innan du investerar."}], "q": [{"q": "Du sparar 300 kr i månaden i 10 år. Hur mycket har du satt in själv?", "o": ["36 000 kr", "3 000 kr", "49 000 kr", "300 000 kr"], "why": "300 kr gånger 12 månader gånger 10 år är 36 000 kr."}, {"q": "Vem får oftast mest ränta på ränta?", "o": ["Den som börjar tidigt", "Den som börjar sent", "Den som byter fond varje vecka", "Ingen skillnad"]}, {"q": "Är avkastningen på en indexfond garanterad?", "o": ["Nej", "Ja, alltid 6 %", "Ja, om du väntar en månad", "Ja, på ISK"]}, {"q": "Du har ett dyrt lån och 2 000 kr över. Vad är ofta klokast?", "o": ["Betala av lånet", "Köpa aktier", "Köpa krypto", "Ta ett nytt lån"]}, {"m": [["Insatt belopp", "Det du själv sparat"], ["Avkastning", "Det pengarna tjänat"], ["Tid", "Viktigast för ränta på ränta"], ["Dyr skuld", "Växer också med ränta på ränta"]]}]}, "x117": {"t": "Ditt första sparande", "c": [{"t": "Börja enkelt", "d": "Ett vanligt första steg är ett månadssparande i en bred, billig indexfond på ett ISK. Du behöver inte välja aktier själv."}, {"t": "Automatiskt", "d": "Ställ in att pengarna dras automatiskt samma dag varje månad, till exempel dagen efter lönen. Då slipper du bestämma dig varje gång."}, {"t": "Låt det vara", "d": "När börsen faller känns det jobbigt. Den som säljer i panik låser in förlusten. Långsiktiga sparare fortsätter oftast månadsspara även när det går ner."}], "q": [{"q": "Vilket är ett vanligt och enkelt första sparande?", "o": ["Månadsspara i en bred indexfond", "Daytrading med hävstång", "Ett tips från TikTok", "Allt i en kryptovaluta"]}, {"q": "Varför spara automatiskt?", "o": ["Du slipper bestämma dig varje gång", "Det ger garanterad vinst", "Banken betalar dig extra", "Det är förbjudet annars"]}, {"q": "Börsen faller 15 %. Vad gör en långsiktig sparare ofta?", "o": ["Fortsätter månadsspara", "Säljer allt i panik", "Lånar för att köpa mer", "Byter till krypto"]}, {"q": "Vad händer om du säljer i panik när börsen fallit?", "o": ["Du låser in förlusten", "Förlusten försvinner", "Du får tillbaka allt", "Ingenting"]}, {"m": [["Indexfond", "Bred och billig"], ["Månadsspara", "Samma belopp varje månad"], ["Panikförsäljning", "Låser in förlusten"], ["ISK", "Vanligt sparkonto för fonder"]]}]}, "x118": {"t": "Under 18: vad gäller?", "c": [{"t": "Omyndig", "d": "Under 18 är du omyndig. Det betyder att du i regel inte själv får ingå avtal om pengar. Dina vårdnadshavare bestämmer över dina tillgångar."}, {"t": "Pengar du tjänat själv", "d": "Är du 16 eller 17 får du själv bestämma över pengar du tjänat genom eget arbete, till exempel lön från sommarjobbet. Det står i föräldrabalken."}, {"t": "Konto och sparande", "d": "För att öppna ett ISK eller ett konto hos en mäklare som omyndig behövs oftast vårdnadshavarnas medgivande. Prata med dem och banken. Hävstång, CFD:er och liknande är inte till för dig som är under 18."}], "q": [{"q": "Du är 17 och har tjänat 5 000 kr på sommarjobbet. Vem bestämmer över pengarna?", "o": ["Du själv", "Bara banken", "Skolan", "Ingen"]}, {"q": "Vad behövs oftast för att du som är 16 ska öppna ett konto hos en mäklare?", "o": ["Vårdnadshavarnas medgivande", "Ett lån", "Ett tips från en vän", "Ingenting"]}, {"q": "Vad betyder omyndig?", "o": ["Att du är under 18", "Att du saknar pengar", "Att du inte får spara", "Att du inte får jobba"]}, {"q": "Vilket passar inte för dig som är under 18?", "o": ["CFD:er med hävstång", "Att göra en budget", "Att ha en buffert", "Att lära sig om aktier"]}, {"m": [["Omyndig", "Under 18 år"], ["Vårdnadshavare", "Bestämmer över tillgångarna"], ["Egen arbetsinkomst", "Din från 16 år"], ["Medgivande", "Behövs ofta för konto"]]}]}, "x119": {"t": "Finfluencers", "c": [{"t": "Vad är en finfluencer?", "d": "En finfluencer pratar om pengar och investeringar på sociala medier. Vissa är kunniga, andra säljer kurser, signaler eller får betalt av plattformar för att locka dig."}, {"t": "Lyxbilden", "d": "Bilar, resor och skärmdumpar på vinster bevisar ingenting. Bilen kan vara hyrd och vinsterna kan vara utvalda. Förlusterna visas nästan aldrig."}, {"t": "Fråga dig själv", "d": "Hur tjänar personen pengar? Visar den risker och förluster? Lovar den snabba eller säkra vinster? Ju mer den säljer, desto mer försiktig ska du vara."}], "q": [{"q": "En finfluencer visar en lyxbil och säljer en kurs för 2 990 kr. Vad bevisar bilen?", "o": ["Ingenting om hans trading", "Att kursen fungerar", "Att han aldrig förlorar", "Att du blir rik"]}, {"q": "Vilken fråga är viktigast att ställa?", "o": ["Hur tjänar personen pengar?", "Hur många följare har den?", "Vilken bil kör den?", "Hur snygg är videon?"]}, {"q": "Någon lovar 'säkra 20 % i månaden'. Vad är det?", "o": ["En stor varningssignal", "En vanlig avkastning", "En indexfond", "En bra affär"]}, {"q": "Varför ser du sällan förlusterna i sådana videor?", "o": ["De som förlorar visar det sällan", "Det finns inga förluster", "Förluster är olagliga att visa", "Börsen döljer dem"]}, {"m": [["Finfluencer", "Pratar pengar på nätet"], ["Lyxbild", "Bevisar ingenting"], ["Säker vinst", "Finns inte"], ["Intressekonflikt", "Tjänar på att du köper"]]}]}, "x120": {"t": "Kryptohype", "c": [{"t": "Stora svängningar", "d": "Kryptovalutor kan stiga eller falla 50 % på kort tid. Många nya mynt försvinner helt. Satsa aldrig pengar du inte har råd att förlora."}, {"t": "FOMO", "d": "FOMO betyder rädsla att missa något. När alla pratar om ett mynt som rusat har ofta de första redan tjänat pengar, och de som köper sist riskerar mest."}, {"t": "Skydd och regler", "d": "Inom EU finns nya regler för kryptoföretag, men skyddet är inte detsamma som för bankkonton. Kontrollera att plattformen har tillstånd och var beredd på att pengarna kan försvinna."}], "q": [{"q": "Vad betyder FOMO?", "o": ["Rädsla att missa något", "En sorts kryptovaluta", "En säker strategi", "En bankavgift"]}, {"q": "Ett nytt mynt har stigit 400 % på en vecka och alla pratar om det. Vem riskerar oftast mest?", "o": ["De som köper sist", "De som köpte först", "De som inte köper", "Ingen"]}, {"q": "Hur mycket kan du lägga i krypto?", "o": ["Bara pengar du har råd att förlora", "Hela bufferten", "Lånade pengar", "Pengar till hyran"]}, {"q": "Är krypto på en plattform skyddat som pengar på ett bankkonto?", "o": ["Nej, inte på samma sätt", "Ja, alltid", "Ja, om myntet är populärt", "Ja, staten garanterar allt"]}, {"m": [["FOMO", "Rädsla att missa"], ["Volatilitet", "Stora svängningar"], ["Nytt mynt", "Kan försvinna helt"], ["Tillstånd", "Kontrollera plattformen"]]}]}, "x121": {"t": "Bedrägerier i mobilen", "c": [{"t": "BankID är din namnteckning", "d": "När du legitimerar dig med BankID skriver du under. Gör det bara när du själv har startat det du gör. Ingen bank eller myndighet ringer och ber dig öppna BankID."}, {"t": "Swish och köp-sälj", "d": "En vanlig bluff är att 'köparen' ber dig skanna en QR-kod eller öppna Swish för att 'ta emot' pengar. För att ta emot pengar behöver du aldrig godkänna något."}, {"t": "Penningmålvakt", "d": "Om någon erbjuder dig snabba pengar för att låna ut ditt konto eller föra vidare pengar kan du bli penningmålvakt. Det är brottsligt och kan förstöra din ekonomi i många år."}], "q": [{"q": "Någon som säger sig vara från banken ringer och ber dig öppna BankID. Vad gör du?", "o": ["Lägger på och ringer banken själv", "Öppnar BankID", "Ger dem koden", "Frågar vad de vill köpa"]}, {"q": "En köpare vill att du skannar en QR-kod för att få betalt. Vad stämmer?", "o": ["För att ta emot pengar behöver du aldrig godkänna något", "Det är det vanliga sättet", "Det ger dubbel betalning", "Det är säkrare än Swish"]}, {"q": "Någon erbjuder 3 000 kr för att låna ditt bankkonto en dag. Vad är det?", "o": ["Ett försök att göra dig till penningmålvakt", "Ett vanligt extrajobb", "En investering", "En gåva"]}, {"q": "När ska du legitimera dig med BankID?", "o": ["Bara när du själv startat det du gör", "När någon ringer och ber dig", "När du får ett sms med länk", "Alltid när appen frågar"]}, {"m": [["BankID", "Din namnteckning"], ["QR-bluff", "Du betalar i stället för att få"], ["Penningmålvakt", "Lånar ut sitt konto"], ["Ring själv", "Använd bankens riktiga nummer"]]}]}, "x122": {"t": "Bedrägeri eller inte?", "c": [{"t": "Tre snabba tester", "d": "Kräver de att du skyndar dig? Lovar de hög och säker vinst? Ber de om BankID, koder eller att du installerar en app? Ett ja räcker för att stanna upp."}, {"t": "Kontrollera själv", "d": "Klicka inte på länken. Gå själv till företagets riktiga webbplats eller app och sök på Finansinspektionens varningslista."}, {"t": "Det är inte pinsamt", "d": "Bedragare är proffs och lurar även vuxna och experter. Har du blivit lurad: ring banken direkt och polisanmäl."}], "q": [{"q": "Sms: 'Ditt paket väntar! Betala 19 kr i tull här: bit.ly/…' Bedrägeri eller inte?", "o": ["Troligen bedrägeri", "Helt säkert", "Betala snabbt innan paketet skickas tillbaka", "Svara med ditt kortnummer"]}, {"q": "DM: 'Jag gör 5 000 kr om dagen med min botten. Skicka 1 000 kr så sätter jag igång dig!' Bedrägeri eller inte?", "o": ["Troligen bedrägeri", "En bra investering", "Ett vanligt jobb", "Säkert, han har många följare"]}, {"q": "Din bank-app visar att ditt månadssparande har dragits som vanligt. Bedrägeri eller inte?", "o": ["Inte bedrägeri, det är något du själv ställt in", "Bedrägeri, ring polisen", "Bedrägeri, byt bank", "Bedrägeri, skicka BankID"]}, {"q": "Reklam: 'Känd programledare avslöjar hemligheten bakom sin förmögenhet. Investera 2 500 kr i dag!' Bedrägeri eller inte?", "o": ["Troligen bedrägeri med falsk kändisreklam", "Sant, kändisar delar alltid sina hemligheter", "En vanlig fond", "Ett erbjudande från banken"]}, {"m": [["Tidspress", "Röd flagga"], ["Kortlänk i sms", "Klicka inte"], ["Kändisreklam", "Ofta falsk"], ["Varningslista", "Finns hos FI"]]}]}, "x123": {"t": "Marknadsstruktur", "c": [{"t": "Swingtoppar och swingbottnar", "d": "Varje gång priset vänder bildas en swingtopp eller en swingbotten. De är byggstenarna i all prisrörelse.", "fig": "line"}, {"t": "Upptrend", "d": "Högre toppar (HH) och högre bottnar (HL). Så länge den senaste högre botten håller är trenden upp."}, {"t": "Nedtrend och range", "d": "Lägre toppar (LH) och lägre bottnar (LL) betyder nedtrend. Rör sig priset mellan samma topp och botten är marknaden i en range."}], "q": [{"q": "Högre toppar och högre bottnar betyder…", "o": ["Upptrend", "Nedtrend", "Range", "Ingen trend"]}, {"q": "Vad är ett LH?", "o": ["En lägre topp", "En högre botten", "En stor volym", "En limitorder"]}, {"q": "När är en upptrend fortfarande intakt?", "o": ["Så länge senaste högre botten håller", "Så länge ljusen är gröna", "Bara på måndagar", "Tills volymen faller"]}, {"q": "Priset studsar mellan 100 och 110 i flera veckor. Vad kallas det?", "o": ["En range", "En upptrend", "En krasch", "Ett gap"]}, {"m": [["HH", "Högre topp"], ["HL", "Högre botten"], ["LH", "Lägre topp"], ["LL", "Lägre botten"]]}]}, "x124": {"t": "BOS och CHoCH", "c": [{"t": "Break of Structure (BOS)", "d": "När priset stänger förbi den senaste swingtoppen i en upptrend, eller swingbotten i en nedtrend. Ett BOS bekräftar att trenden fortsätter."}, {"t": "Change of Character (CHoCH)", "d": "Det första brottet mot trenden: i en upptrend när priset bryter under senaste högre botten. Kallas också Market Structure Shift (MSS)."}, {"t": "Stängning eller veke?", "d": "Många kräver att ett ljus stänger förbi nivån. Om bara veken sticker förbi och priset vänder kan det i stället vara ett svep av likviditet."}], "q": [{"q": "I en upptrend stänger priset över senaste swingtoppen. Vad är det?", "o": ["Ett BOS", "Ett CHoCH", "Ett gap", "En doji"]}, {"q": "Vad signalerar ett CHoCH?", "o": ["Att trenden kan vända", "Att trenden alltid fortsätter", "Att börsen stänger", "Att volymen är noll"]}, {"q": "Bara veken sticker över toppen och priset faller tillbaka. Vad kan det vara?", "o": ["Ett svep av likviditet", "Ett bekräftat BOS", "En utdelning", "En split"]}, {"q": "Ett annat namn för CHoCH är…", "o": ["Market Structure Shift", "Fair value gap", "Order block", "Stop-loss"]}, {"m": [["BOS", "Trenden fortsätter"], ["CHoCH", "Första brottet mot trenden"], ["Stängning", "Starkare bekräftelse"], ["Bara veke", "Kan vara ett svep"]]}]}, "x125": {"t": "Likviditet", "c": [{"t": "Buy-side liquidity", "d": "Ovanför toppar ligger stop-loss från blankare och köpordrar från dem som vill köpa ett utbrott. När de utlöses blir de köp."}, {"t": "Sell-side liquidity", "d": "Under bottnar ligger stop-loss från köpare och säljordrar från dem som vill sälja ett brott. När de utlöses blir de sälj."}, {"t": "Lika toppar och bottnar", "d": "När flera toppar eller bottnar ligger på samma nivå samlas extra mycket likviditet där. De blir ofta ett mål för priset."}], "q": [{"q": "Vad ligger ofta ovanför en tydlig topp?", "o": ["Buy-side liquidity", "Sell-side liquidity", "Utdelningar", "Ingenting"]}, {"q": "Vad blir en utlöst stop-loss på en köpposition?", "o": ["En säljorder", "En köporder", "En utdelning", "Ingenting"]}, {"q": "Varför dras priset ofta mot lika toppar?", "o": ["Där samlas mycket likviditet", "Där är börsen stängd", "Det är slumpen", "Där finns inga ordrar"]}, {"q": "Var ligger sell-side liquidity?", "o": ["Under bottnar", "Över toppar", "Mitt i en range", "I nyheterna"]}, {"m": [["BSL", "Över toppar"], ["SSL", "Under bottnar"], ["Lika toppar", "Extra mycket likviditet"], ["Stop-loss", "Blir en order när den utlöses"]]}]}, "x126": {"t": "Liquidity sweeps", "c": [{"t": "Vad är ett svep?", "d": "Priset sticker kort förbi en topp eller botten, tar likviditeten och vänder tillbaka. Det kallas också stop hunt."}, {"t": "Svep eller utbrott?", "d": "Ett riktigt utbrott stannar på andra sidan och fortsätter. Ett svep stänger snabbt tillbaka innanför nivån, ofta med en lång veke."}, {"t": "Svep plus CHoCH", "d": "Ett vanligt ICT-upplägg: priset sveper en botten och gör sedan ett CHoCH uppåt. Det tolkas som att säljarna fångats och köparna tar över."}], "q": [{"q": "Vad händer vid ett svep?", "o": ["Priset tar likviditeten och vänder", "Priset står still", "Börsen stänger", "Volymen försvinner"]}, {"q": "Hur skiljer man ett svep från ett riktigt utbrott?", "o": ["Svepet stänger snabbt tillbaka innanför nivån", "Svepet har alltid hög volym", "Det går inte", "Utbrott sker bara på fredagar"]}, {"q": "Priset sveper en botten och gör sedan CHoCH uppåt. Hur tolkas det ofta?", "o": ["Säljare fångade, köpare tar över", "Trenden nedåt fortsätter säkert", "Inget alls", "Börsen kraschar"]}, {"q": "Ett annat ord för svep är…", "o": ["Stop hunt", "Utdelning", "Ombalansering", "Courtage"]}, {"m": [["Svep", "Tar likviditet och vänder"], ["Utbrott", "Stannar och fortsätter"], ["Lång veke", "Vanlig vid svep"], ["Svep + CHoCH", "Vanligt ICT-upplägg"]]}]}, "x127": {"t": "Order blocks", "c": [{"t": "Vad är ett order block?", "d": "Det sista motsatta ljuset före en kraftig rörelse som bryter strukturen. I en uppgång: sista röda ljuset före impulsen."}, {"t": "Varför kan det fungera?", "d": "Tanken är att stora aktörer byggde positioner där och kan ha ordrar kvar. När priset kommer tillbaka kan de försvara nivån."}, {"t": "Bra och dåliga order blocks", "d": "Starkare om impulsen bröt strukturen, lämnade ett fair value gap och tog likviditet innan. Ett block som redan testats flera gånger är svagare."}], "q": [{"q": "Vad är ett bullish order block?", "o": ["Sista röda ljuset före en kraftig uppgång", "Första gröna ljuset på dagen", "Ett stort grönt ljus på toppen", "Ett ljus utan veke"]}, {"q": "Vad gör ett order block starkare?", "o": ["Impulsen bröt strukturen och lämnade ett FVG", "Det har testats tio gånger", "Det är rött", "Det syns på TikTok"]}, {"q": "Vad är tanken bakom order blocks?", "o": ["Stora aktörer kan ha ordrar kvar där", "Priset vänder alltid där", "Det är en sorts utdelning", "Börsen bestämmer dem"]}, {"q": "Var lägger man ofta stoppen vid ett köp i ett order block?", "o": ["Under blockets botten", "Över närmaste topp", "Ingen stopp behövs", "Mitt i blocket alltid"]}, {"m": [["Bullish OB", "Sista röda före uppgång"], ["Bearish OB", "Sista gröna före nedgång"], ["Impuls", "Kraftig rörelse"], ["Testat många gånger", "Svagare zon"]]}]}, "x128": {"t": "Fair value gaps", "c": [{"t": "Tre ljus", "d": "Ett fair value gap (FVG) finns när ljus ett och ljus tre inte överlappar. Glappet emellan visar att priset rörde sig så snabbt att nästan inget handlades.", "fig": "gap"}, {"t": "Obalans", "d": "FVG kallas också imbalance. Priset kommer ofta tillbaka för att fylla en del av glappet innan rörelsen fortsätter, men inte alltid."}, {"t": "Inversion FVG", "d": "Om priset stänger rakt igenom ett FVG kan zonen byta roll, som när stöd blir motstånd. Det kallas inversion FVG."}], "q": [{"q": "Hur hittar du ett FVG?", "o": ["Ljus ett och tre överlappar inte", "Tre röda ljus i rad", "Ett ljus utan kropp", "Hög RSI"]}, {"q": "Vad händer ofta med ett FVG?", "o": ["Priset kommer tillbaka och fyller en del", "Det försvinner aldrig", "Börsen stänger det", "Det blir en utdelning"]}, {"q": "Vad är ett annat ord för FVG?", "o": ["Imbalance", "Order block", "Doji", "Spread"]}, {"q": "Priset stänger rakt igenom ett FVG. Vad kan zonen bli?", "o": ["En inversion FVG", "Ett BOS", "En ny aktie", "Ingenting, alltid"]}, {"m": [["FVG", "Glapp mellan ljus 1 och 3"], ["Imbalance", "Snabb rörelse, lite handel"], ["Fyllas", "Priset återvänder in i glappet"], ["Inversion", "Zonen byter roll"]]}]}, "x129": {"t": "Premium och discount", "c": [{"t": "Mitten av rörelsen", "d": "Dra Fibonacci från botten till toppen i den senaste rörelsen. 50 procent är jämvikt, equilibrium.", "fig": "fib"}, {"t": "Discount", "d": "Under 50 procent är priset billigt i förhållande till rörelsen. I en upptrend letar man köp i discount."}, {"t": "Premium", "d": "Över 50 procent är priset dyrt. I en nedtrend letar man sälj i premium. Att köpa i premium i en upptrend är att köpa dyrt."}], "q": [{"q": "Rörelsen gick från 100 till 120. Var ligger equilibrium?", "o": ["110", "100", "120", "105"]}, {"q": "I en upptrend, var letar man helst köp?", "o": ["I discount, under 50 %", "I premium, över 50 %", "På toppen", "Var som helst"]}, {"q": "Vad betyder att köpa i premium i en upptrend?", "o": ["Att köpa dyrt", "Att köpa billigt", "Att få rabatt", "Att slippa courtage"]}, {"q": "I en nedtrend, var letar man sälj?", "o": ["I premium", "I discount", "Vid botten", "Ingenstans"]}, {"m": [["Equilibrium", "50 % av rörelsen"], ["Discount", "Under 50 %, billigt"], ["Premium", "Över 50 %, dyrt"], ["Fibonacci", "Verktyget man drar"]]}]}, "x130": {"t": "OTE och Fibonacci-ingångar", "c": [{"t": "Optimal Trade Entry", "d": "ICT kallar zonen mellan 62 och 79 procents rekyl för Optimal Trade Entry, OTE. Nivån 70,5 procent ses ofta som mitten av zonen.", "fig": "fib"}, {"t": "Hur man drar", "d": "I en upptrend drar du från botten till toppen. OTE ligger djupt i discount. Bäst om zonen sammanfaller med ett FVG eller order block."}, {"t": "Mål med Fibonacci", "d": "Många sätter första mål vid den gamla toppen och nästa vid förlängningar som −27 eller −62 procent, alltså bortom toppen."}], "q": [{"q": "Vilken zon kallar ICT OTE?", "o": ["62–79 % rekyl", "0–20 % rekyl", "Över toppen", "Exakt 50 %"]}, {"q": "Var ligger OTE i en upptrend?", "o": ["Djupt i discount", "I premium", "På toppen", "Under botten"]}, {"q": "När blir en OTE-zon starkare?", "o": ["När den sammanfaller med ett FVG eller OB", "När den är röd", "På helger", "Aldrig"]}, {"q": "Var sätter många sitt första mål?", "o": ["Vid den gamla toppen", "Vid ingången", "Under stoppen", "Ingenstans"]}, {"m": [["OTE", "62–79 % rekyl"], ["70,5 %", "Mitten av OTE"], ["−27 %", "Förlängning bortom toppen"], ["Sammanfall", "Flera skäl på samma nivå"]]}]}, "x131": {"t": "Sessioner och killzones", "c": [{"t": "Tre stora sessioner", "d": "Asien (ungefär 01–10 svensk tid), London (ungefär 09–18) och New York (ungefär 14–23). Tiderna flyttas när sommartiden ändras."}, {"t": "Killzones", "d": "ICT kallar de mest aktiva timmarna för killzones, till exempel London-öppningen och New York-öppningen. Då är volymen och rörelserna störst."}, {"t": "Asien-rangen", "d": "Under Asien rör sig priset ofta lite. Toppen och botten i den rangen blir likviditet som London eller New York ofta sveper."}], "q": [{"q": "Ungefär när öppnar London, svensk tid?", "o": ["Runt 09", "Runt 14", "Runt 22", "Runt 03"]}, {"q": "Vad är en killzone?", "o": ["En tid med mycket volym och rörelse", "En zon där man alltid förlorar", "En sorts stop-loss", "En helgdag"]}, {"q": "Vad händer ofta med Asien-rangens topp och botten?", "o": ["De sveps senare under dagen", "De blir permanenta", "Inget, aldrig", "De stänger börsen"]}, {"q": "När brukar det vara mest rörelse?", "o": ["När London och New York överlappar", "Mitt i natten i Europa", "På söndagar", "Alltid lika mycket"]}, {"m": [["Asien", "Ofta lugn range"], ["London", "Öppnar runt 09"], ["New York", "Öppnar runt 14–15"], ["Killzone", "Mest aktiva timmarna"]]}]}, "x132": {"t": "Ett helt ICT-upplägg", "c": [{"t": "Uppifrån och ner", "d": "Börja på dags- eller fyratimmarsgrafen för riktning och dragning mot likviditet. Gå sedan ner till 15 eller 5 minuter för ingången."}, {"t": "Checklistan", "d": "Riktning på hög tidsram, svep av likviditet, CHoCH på låg tidsram, ingång i FVG eller OB i discount, stopp bortom svepet, mål vid motsatt likviditet."}, {"t": "Ärligt", "d": "ICT är ett sätt att beskriva marknaden, inte ett bevisat system. Backtesta reglerna själv och riskera max 1 procent per trade."}], "q": [{"q": "Vilken tidsram används för riktningen?", "o": ["En hög, till exempel dag eller 4 timmar", "1 sekund", "Ingen, gissa", "Bara veckografen alltid"]}, {"q": "Var läggs stoppen i upplägget?", "o": ["Bortom svepet", "Mitt i FVG:t", "Vid målet", "Ingen stopp"]}, {"q": "Var ligger målet?", "o": ["Vid motsatt likviditet", "Vid ingången", "Under stoppen", "Var som helst"]}, {"q": "Är ICT ett bevisat system?", "o": ["Nej, backtesta själv", "Ja, alltid lönsamt", "Ja, om man köper en kurs", "Ja, på fredagar"]}, {"m": [["Hög tidsram", "Riktning"], ["Svep", "Likviditet tas"], ["CHoCH", "Bekräftelse på låg tidsram"], ["FVG/OB", "Ingångszon"]]}]}, "x133": {"t": "Tidsramar och top-down-analys", "c": [{"t": "Vad är en tidsram?", "d": "Tiden varje ljus visar: 1 minut, 15 minuter, 1 timme, 1 dag. Samma marknad kan se upp ut på en tidsram och ner på en annan."}, {"t": "Top-down", "d": "Börja på en hög tidsram för riktning och viktiga nivåer, gå sedan ner till en lägre för att hitta ingången. En vanlig kombination är dag, 1 timme och 5 minuter."}, {"t": "Faktor fyra till sex", "d": "En tumregel är att varje steg ner är ungefär fyra till sex gånger kortare, till exempel 4 timmar, 1 timme och 15 minuter."}], "q": [{"q": "Vad visar ett ljus på 1-timmesgrafen?", "o": ["En timmes handel", "En dags handel", "En minut", "En vecka"]}, {"q": "Vad används den höga tidsramen till?", "o": ["Riktning och viktiga nivåer", "Exakt ingång", "Att räkna courtage", "Ingenting"]}, {"q": "Dagsgrafen är i upptrend, 5-minutersgrafen faller. Vad är klokt?", "o": ["Vänta på att lilla grafen vänder upp och köp med dagstrenden", "Blanka hårt mot dagstrenden", "Ignorera dagsgrafen", "Köpa med hävstång direkt"]}, {"q": "Vilken kombination följer faktor fyra till sex?", "o": ["4 timmar, 1 timme, 15 minuter", "1 dag, 1 minut, 1 sekund", "1 månad, 1 år, 1 vecka", "Bara 1 minut"]}, {"m": [["Hög tidsram", "Riktning"], ["Mellan tidsram", "Upplägg och zon"], ["Låg tidsram", "Ingång"], ["Top-down", "Från stort till smått"]]}]}, "x134": {"t": "Handelssessioner", "c": [{"t": "Aktiemarknaden har öppettider", "d": "Stockholmsbörsen handlas ungefär 09.00–17.30 på vardagar. Amerikanska börser öppnar 15.30 svensk tid under större delen av året."}, {"t": "Forex och krypto", "d": "Valutor handlas dygnet runt måndag till fredag. Krypto handlas dygnet runt alla dagar, även helger."}, {"t": "Öppning och stängning", "d": "Första och sista timmen är ofta mest volatila. Nybörjare tjänar ofta på att vänta ut de första 15–30 minuterna."}], "q": [{"q": "När öppnar amerikanska börser, svensk tid, oftast?", "o": ["15.30", "09.00", "22.00", "06.00"]}, {"q": "Vilken marknad handlas även på helger?", "o": ["Krypto", "Stockholmsbörsen", "Forex", "Inga marknader"]}, {"q": "Varför vänta ut börsens första minuter?", "o": ["De är ofta mycket volatila", "Börsen är stängd då", "Courtaget är högre", "Det spelar ingen roll"]}, {"q": "När handlas forex?", "o": ["Dygnet runt måndag–fredag", "Bara 09–17", "Bara på helger", "En timme om dagen"]}, {"m": [["Stockholm", "Ungefär 09.00–17.30"], ["USA", "Öppnar 15.30 svensk tid"], ["Forex", "Dygnet runt vardagar"], ["Krypto", "Dygnet runt alla dagar"]]}]}, "x135": {"t": "Utbud och efterfrågan", "c": [{"t": "Efterfrågezon", "d": "En prisnivå där köpare tidigare tog över kraftigt, ofta en kort paus följd av en stark uppgång. Priset kan studsa där igen."}, {"t": "Utbudszon", "d": "Motsatsen: en nivå där säljare tog över och priset föll kraftigt. Priset kan vända ner där igen."}, {"t": "Färska zoner", "d": "En zon som inte har testats än anses starkast. Varje nytt test förbrukar ordrar och gör zonen svagare."}], "q": [{"q": "Vad är en efterfrågezon?", "o": ["Där köpare tidigare tog över kraftigt", "Där säljare tog över", "Mitt i ingenstans", "En nyhetssida"]}, {"q": "Vilken zon anses starkast?", "o": ["En färsk, otestad zon", "En zon testad fem gånger", "En zon utan rörelse", "Alla är lika"]}, {"q": "Vad gör varje nytt test av en zon?", "o": ["Förbrukar ordrar och försvagar den", "Gör den starkare", "Ingenting", "Flyttar den"]}, {"q": "Priset föll kraftigt från 120. Vad kan 120 vara?", "o": ["En utbudszon", "En efterfrågezon", "En utdelning", "Ett FVG alltid"]}, {"m": [["Efterfrågan", "Köpare tog över"], ["Utbud", "Säljare tog över"], ["Färsk zon", "Starkast"], ["Många tester", "Svagare"]]}]}, "x136": {"t": "Volymprofil", "c": [{"t": "Volym per pris", "d": "Vanlig volym visar hur mycket som handlades per ljus. Volymprofilen visar hur mycket som handlades på varje prisnivå, som liggande staplar."}, {"t": "POC och value area", "d": "Point of Control (POC) är priset med mest handel. Value area är området där ungefär 70 procent av volymen skedde."}, {"t": "HVN och LVN", "d": "Högvolymnoder (HVN) fungerar ofta som magneter och stöd. Lågvolymnoder (LVN) är tunna områden som priset ofta rör sig snabbt igenom."}], "q": [{"q": "Vad visar volymprofilen?", "o": ["Handel per prisnivå", "Handel per dag", "Vinst per aktie", "Utdelningen"]}, {"q": "Vad är POC?", "o": ["Priset med mest handel", "Dagens högsta pris", "En ordertyp", "Ett mönster"]}, {"q": "Hur stor del av volymen ligger i value area?", "o": ["Ungefär 70 %", "10 %", "100 %", "50 % exakt"]}, {"q": "Vad gör priset ofta i en LVN?", "o": ["Rör sig snabbt igenom", "Står still länge", "Stänger börsen", "Betalar utdelning"]}, {"m": [["POC", "Mest handlade pris"], ["Value area", "Cirka 70 % av volymen"], ["HVN", "Magnet och stöd"], ["LVN", "Tunt område"]]}]}, "x137": {"t": "Wyckoff", "c": [{"t": "Fyra faser", "d": "Richard Wyckoff beskrev marknaden i fyra faser: ackumulation (köp i en range), uppgång, distribution (sälj i en range) och nedgång."}, {"t": "Spring", "d": "I slutet av en ackumulation sticker priset ofta under rangens botten och vänder snabbt upp. Det kallas spring och liknar ett svep av likviditet."}, {"t": "Upthrust", "d": "Motsatsen i en distribution: priset sticker över rangens topp och faller tillbaka. Ett tecken på att stora aktörer säljer."}], "q": [{"q": "Vad händer i ackumulationsfasen?", "o": ["Stora aktörer köper i en range", "Priset rusar uppåt", "Alla säljer i panik", "Börsen stänger"]}, {"q": "Vad är en spring?", "o": ["Priset sticker under rangen och vänder upp", "En årstid", "En sorts utdelning", "Ett stort grönt ljus på toppen"]}, {"q": "Vilken ordning har Wyckoffs faser?", "o": ["Ackumulation, uppgång, distribution, nedgång", "Uppgång, nedgång, uppgång, nedgång", "Distribution, ackumulation, krasch", "Det finns ingen ordning"]}, {"q": "Vad liknar en upthrust?", "o": ["Ett svep över en topp", "Ett äkta utbrott", "En räntehöjning", "En split"]}, {"m": [["Ackumulation", "Köp i en range"], ["Distribution", "Sälj i en range"], ["Spring", "Falskt brott nedåt"], ["Upthrust", "Falskt brott uppåt"]]}]}, "x138": {"t": "Elliottvågor", "c": [{"t": "Fem upp, tre ner", "d": "Elliotts teori säger att trender ofta rör sig i fem vågor med trenden (1–5) och tre vågor mot (A, B, C)."}, {"t": "Tre regler", "d": "Våg 2 går aldrig under början av våg 1. Våg 3 är aldrig den kortaste. Våg 4 går inte in i våg 1:s område."}, {"t": "Svårt i praktiken", "d": "Olika analytiker räknar ofta vågorna olika. Använd Elliott som en karta över möjliga scenarier, inte som en säker prognos."}], "q": [{"q": "Hur många vågor går med trenden enligt Elliott?", "o": ["Fem", "Tre", "Två", "Tio"]}, {"q": "Vilken våg är aldrig den kortaste?", "o": ["Våg 3", "Våg 1", "Våg 5", "Våg B"]}, {"q": "Vad heter vågorna mot trenden?", "o": ["A, B och C", "1, 2 och 3", "X, Y och Z", "De har inga namn"]}, {"q": "Hur bör man använda Elliottvågor?", "o": ["Som en karta över möjliga scenarier", "Som en säker prognos", "För att slippa stop-loss", "Inte alls, någonsin"]}, {"m": [["Våg 1–5", "Med trenden"], ["A–B–C", "Korrektion"], ["Våg 3", "Aldrig kortast"], ["Våg 2", "Aldrig under våg 1:s start"]]}]}, "x139": {"t": "Harmoniska mönster", "c": [{"t": "XABCD", "d": "Harmoniska mönster består av fem punkter, X, A, B, C och D. Förhållandet mellan benen mäts med Fibonacci."}, {"t": "Kända mönster", "d": "Gartley, Bat, Butterfly och Crab är vanligast. De skiljer sig i hur djupt punkt D går i förhållande till X."}, {"t": "Zonen vid D", "d": "Punkt D är en möjlig vändzon, inte en exakt punkt. Vänta på bekräftelse och lägg stoppen bortom zonen."}], "q": [{"q": "Hur många punkter har ett harmoniskt mönster?", "o": ["Fem", "Två", "Tre", "Tio"]}, {"q": "Vilket verktyg mäter benen?", "o": ["Fibonacci", "RSI", "Volym", "P/E-tal"]}, {"q": "Vilket är ett harmoniskt mönster?", "o": ["Gartley", "Doji", "Hammare", "Marubozu"]}, {"q": "Vad är punkt D?", "o": ["En möjlig vändzon", "En garanterad vändning", "Början av mönstret", "En utdelning"]}, {"m": [["X", "Startpunkt"], ["D", "Möjlig vändzon"], ["Gartley", "Klassiskt harmoniskt mönster"], ["Fibonacci", "Mäter benen"]]}]}, "x140": {"t": "Orderflöde", "c": [{"t": "Vem trycker priset?", "d": "Orderflöde handlar om att se vem som är aggressiv: köpare som köper direkt till säljarnas pris, eller säljare som säljer direkt till köparnas pris."}, {"t": "Delta", "d": "Delta är aggressiva köp minus aggressiva sälj. Positivt delta när priset faller kan visa att köpare absorberar säljtrycket."}, {"t": "Footprint", "d": "Ett footprint-diagram visar köp och sälj inne i varje ljus på varje pris. Det kräver ofta betalda verktyg och mycket övning."}], "q": [{"q": "Vad är delta?", "o": ["Aggressiva köp minus aggressiva sälj", "En grekisk aktie", "Skillnaden mellan två börser", "En avgift"]}, {"q": "Vad kan positivt delta när priset faller visa?", "o": ["Att köpare absorberar säljtrycket", "Att alla säljer", "Att börsen är stängd", "Ingenting"]}, {"q": "Vad visar ett footprint-diagram?", "o": ["Köp och sälj inne i varje ljus", "Bara stängningspriset", "Bolagets vinst", "Väderprognosen"]}, {"q": "Vad är en aggressiv köpare?", "o": ["Någon som köper direkt till säljarnas pris", "Någon som väntar med en limitorder", "Någon som är arg", "En bank"]}, {"m": [["Orderflöde", "Vem som är aggressiv"], ["Delta", "Köp minus sälj"], ["Footprint", "Handel inne i ljuset"], ["Absorption", "Ena sidan tar emot trycket"]]}]}, "x141": {"t": "Grafverktyg och TradingView", "c": [{"t": "En grafplattform", "d": "Många traders använder en separat grafplattform som TradingView för analys och mäklarens app för själva handeln."}, {"t": "Rita rent", "d": "Rita bara de viktigaste nivåerna, zonerna och trendlinjerna. En graf full av linjer och tio indikatorer gör beslutet svårare, inte lättare."}, {"t": "Larm", "d": "Sätt larm vid dina nivåer i stället för att stirra på skärmen. Då kan du göra annat och agera bara när priset når dit."}], "q": [{"q": "Vad används TradingView ofta till?", "o": ["Att analysera grafer", "Att betala skatt", "Att få utdelning", "Att öppna ISK"]}, {"q": "Varför rita rent?", "o": ["För många linjer gör beslutet svårare", "Det ser finare ut bara", "Plattformen kräver det", "Det spelar ingen roll"]}, {"q": "Varför sätta larm?", "o": ["För att slippa stirra på skärmen", "För att garantera vinst", "För att höja priset", "För att slippa stop-loss"]}, {"q": "Hur många indikatorer är lagom för en nybörjare?", "o": ["Få, till exempel ett eller två", "Tio eller fler", "Alla som finns", "Exakt sju"]}, {"m": [["Grafplattform", "Analys"], ["Mäklarapp", "Själva handeln"], ["Larm", "Säger till vid nivån"], ["Ren graf", "Lättare beslut"]]}]}, "x142": {"t": "Bygg din tradingplan", "c": [{"t": "Vad planen innehåller", "d": "Vilka marknader och tidsramar, vilka upplägg du handlar, exakta regler för ingång, stopp och mål, risk per trade och förlustgräns per dag."}, {"t": "Skriv ner den", "d": "En plan i huvudet ändras när känslorna tar över. En skriven plan på en sida går att följa och utvärdera."}, {"t": "Utvärdera varje månad", "d": "Gå igenom dagboken en gång i månaden. Behåll det som fungerar, ta bort upplägg som förlorar, och ändra bara en sak åt gången."}], "q": [{"q": "Vad hör hemma i en tradingplan?", "o": ["Regler för ingång, stopp, mål och risk", "Vad du ska äta", "Tips från TikTok", "Inget, improvisera"]}, {"q": "Varför skriva ner planen?", "o": ["Så att den inte ändras av känslor", "Det är lag", "För att få skatteavdrag", "Det behövs inte"]}, {"q": "Hur ofta bör planen utvärderas?", "o": ["Ungefär en gång i månaden", "Efter varje trade", "Aldrig", "Vart tionde år"]}, {"q": "Hur många saker ändrar du åt gången?", "o": ["En", "Allt", "Fem", "Ingenting någonsin"]}, {"m": [["Upplägg", "Vad du handlar"], ["Risk per trade", "Till exempel 1 %"], ["Förlustgräns", "Sluta för dagen"], ["Utvärdering", "En gång i månaden"]]}]}, "x143": {"t": "Forex: valutapar, pips och lotter", "c": [{"t": "Valutapar", "d": "I forex handlar du alltid en valuta mot en annan. EURUSD 1,10 betyder att en euro kostar 1,10 dollar. Köper du paret tror du att euron stärks mot dollarn."}, {"t": "Pips", "d": "En pip är den vanliga minsta rörelsen: 0,0001 för de flesta par och 0,01 för par med japanska yen."}, {"t": "Lotter", "d": "En standardlot är 100 000 enheter, en minilot 10 000 och en mikrolot 1 000. På EURUSD är en pip värd ungefär 10 dollar per standardlot."}], "q": [{"q": "Vad betyder EURUSD 1,10?", "o": ["En euro kostar 1,10 dollar", "En dollar kostar 1,10 euro", "Räntan är 1,10 %", "Spreaden är 1,10"]}, {"q": "Hur stor är en pip på EURUSD?", "o": ["0,0001", "0,01", "1,0", "10"]}, {"q": "Hur många enheter är en standardlot?", "o": ["100 000", "1 000", "10", "1 miljon"]}, {"q": "Du köper EURUSD. Vad tror du?", "o": ["Att euron stärks mot dollarn", "Att euron försvagas", "Att båda faller", "Ingenting"]}, {"m": [["Standardlot", "100 000 enheter"], ["Minilot", "10 000 enheter"], ["Mikrolot", "1 000 enheter"], ["Pip på yenpar", "0,01"]]}]}, "x144": {"t": "Spread, swap och hävstång", "c": [{"t": "Spread", "d": "Skillnaden mellan köp- och säljpriset. Den är en kostnad varje gång du öppnar en position och blir ofta större vid nyheter och på natten."}, {"t": "Swap", "d": "Om du håller en hävstångsposition över natten dras eller betalas en avgift som beror på räntan. Över tid kan den äta upp vinsten."}, {"t": "Hävstångsgränser i EU", "d": "För privatpersoner i EU gäller högst 30:1 på stora valutapar, 20:1 på andra par, guld och stora index, 10:1 på andra råvaror, 5:1 på aktier och 2:1 på krypto. Du kan inte förlora mer än kontot."}], "q": [{"q": "Vad är spread?", "o": ["Skillnaden mellan köp- och säljpris", "En sorts utdelning", "Bolagets vinst", "En indikator"]}, {"q": "När dras swap?", "o": ["När en hävstångsposition hålls över natten", "Vid varje klick i appen", "Bara på helger", "Aldrig"]}, {"q": "Max hävstång på krypto för privatpersoner i EU?", "o": ["2:1", "30:1", "100:1", "500:1"]}, {"q": "En sida erbjuder 500:1 hävstång. Vad betyder det?", "o": ["Den följer troligen inte EU:s regler för privatpersoner", "Den är extra säker", "Det garanterar vinst", "Det är standard i Sverige"]}, {"m": [["Stora valutapar", "30:1"], ["Guld", "20:1"], ["Aktier", "5:1"], ["Krypto", "2:1"]]}]}, "x145": {"t": "Kryptotrading", "c": [{"t": "Börs och plånbok", "d": "På en kryptobörs äger börsen nycklarna till dina mynt. I en egen plånbok har du nycklarna själv. Den som har nyckelfrasen styr pengarna."}, {"t": "Volatilitet dygnet runt", "d": "Krypto handlas alla dagar och kan röra sig 10 procent på en dag. Använd mindre positioner än i aktier."}, {"t": "Regler i EU", "d": "EU:s MiCA-förordning kräver att kryptobolag som riktar sig till EU har tillstånd. Kontrollera att börsen är godkänd innan du sätter in pengar."}], "q": [{"q": "Vem styr pengarna i en plånbok?", "o": ["Den som har nyckelfrasen", "Den som har appen", "Banken", "Ingen"]}, {"q": "Någon i en chatt ber om din nyckelfras. Vad gör du?", "o": ["Ger den aldrig, det är en bluff", "Ger den om han verkar snäll", "Ger halva", "Lägger upp den på nätet"]}, {"q": "Varför mindre positioner i krypto?", "o": ["Priset svänger mycket mer", "Det är förbjudet med stora", "Avgifterna är noll", "Det spelar ingen roll"]}, {"q": "Vad kräver MiCA?", "o": ["Att kryptobolag i EU har tillstånd", "Att alla köper bitcoin", "Att krypto är gratis", "Ingenting"]}, {"m": [["Börs", "Börsen har nycklarna"], ["Egen plånbok", "Du har nycklarna"], ["Nyckelfras", "Dela aldrig"], ["MiCA", "EU-regler för krypto"]]}]}, "x146": {"t": "Perpetuals och funding", "c": [{"t": "Perpetual futures", "d": "Kontrakt som följer kryptopriset utan slutdatum, med hävstång. Du kan gå både lång och kort. De flesta kryptoförluster med hävstång sker här."}, {"t": "Funding rate", "d": "För att hålla priset nära spot betalar longs och shorts varandra, ofta var åttonde timme. När många är långa betalar longs, och kostnaden växer om du håller länge."}, {"t": "Likvidation", "d": "Med 20 gångers hävstång räcker en rörelse på runt 5 procent mot dig för att hela insatsen ska stängas automatiskt. Likvidationspriset ska alltid ligga långt bortom din stopp."}], "q": [{"q": "Vad saknar en perpetual?", "o": ["Ett slutdatum", "Ett pris", "Hävstång", "En graf"]}, {"q": "Vem betalar funding när de flesta är långa?", "o": ["Longs", "Shorts", "Börsen", "Ingen"]}, {"q": "Ungefär hur stor rörelse likviderar en position med 20x hävstång?", "o": ["Cirka 5 %", "50 %", "100 %", "0,01 %"]}, {"q": "Var ska likvidationspriset ligga?", "o": ["Långt bortom din stopp", "Före din stopp", "Precis vid ingången", "Det spelar ingen roll"]}, {"m": [["Perpetual", "Inget slutdatum"], ["Funding", "Betalning mellan longs och shorts"], ["Likvidation", "Insatsen stängs automatiskt"], ["20x hävstång", "Cirka 5 % till likvidation"]]}]}, "x147": {"t": "Index och terminer", "c": [{"t": "Index", "d": "Ett index mäter en korg aktier. OMXS30 är de 30 mest omsatta på Stockholmsbörsen, S&P 500 är 500 stora amerikanska bolag och Nasdaq 100 är mest teknik."}, {"t": "Terminer", "d": "Ett avtal om att köpa eller sälja till ett pris vid ett datum. ES följer S&P 500 och NQ följer Nasdaq 100. Terminer har inbyggd hävstång."}, {"t": "Mikrokontrakt", "d": "MES och MNQ är en tiondel så stora som ES och NQ. Det gör det möjligt att handla terminer med mindre risk per punkt."}], "q": [{"q": "Vad är OMXS30?", "o": ["De 30 mest omsatta aktierna i Stockholm", "En kryptovaluta", "En amerikansk fond", "En ränta"]}, {"q": "Vilket index följer NQ?", "o": ["Nasdaq 100", "OMXS30", "DAX", "Guldpriset"]}, {"q": "Hur stort är MES jämfört med ES?", "o": ["En tiondel", "Dubbelt", "Lika stort", "Hälften"]}, {"q": "Vad har terminer inbyggt?", "o": ["Hävstång", "Garanterad vinst", "Utdelning", "Ingen risk"]}, {"m": [["OMXS30", "Stockholm"], ["ES", "S&P 500-termin"], ["NQ", "Nasdaq 100-termin"], ["MES", "Mikro-ES"]]}]}, "x148": {"t": "Råvaror: guld och olja", "c": [{"t": "Guld", "d": "Guld (XAUUSD) ses ofta som en trygg hamn vid oro. Det påverkas mycket av räntor och dollarn: högre realräntor brukar pressa guldet."}, {"t": "Olja", "d": "Oljepriset (Brent och WTI) styrs av utbud och efterfrågan: OPEC+-beslut, lager, konflikter och världsekonomin. Det kan röra sig kraftigt på en rubrik."}, {"t": "Volatilt och hävstång", "d": "Råvaror handlas oftast via CFD:er eller terminer med hävstång. Guld kan röra sig flera procent på en dag, så håll risken liten."}], "q": [{"q": "Vad ses guld ofta som?", "o": ["En trygg hamn", "En techaktie", "En kryptovaluta", "Riskfritt"]}, {"q": "Vad brukar pressa guldpriset?", "o": ["Högre realräntor", "Mer oro i världen", "Lägre räntor", "Ingenting"]}, {"q": "Vilket påverkar oljepriset?", "o": ["OPEC+-beslut och lager", "Bara vädret i Sverige", "Apples vinst", "Ingenting"]}, {"q": "Vad heter guld mot dollar som symbol?", "o": ["XAUUSD", "EURUSD", "BTCUSD", "OMXS30"]}, {"m": [["Guld", "Trygg hamn"], ["Olja", "OPEC+ och lager"], ["XAUUSD", "Guld mot dollar"], ["Brent", "Oljesort"]]}]}, "x149": {"t": "Trading kring rapporter", "c": [{"t": "Förväntningar styr", "d": "Det som rör aktien är resultatet jämfört med förväntningarna, inte om siffrorna är bra. En vinstökning kan ge ett ras om marknaden väntade sig mer."}, {"t": "Gap", "d": "Rapporter släpps ofta före öppning eller efter stängning, så aktien kan öppna långt från gårdagens pris. En stop-loss skyddar inte mot gapet, den kan fyllas mycket sämre."}, {"t": "IV crush", "d": "Före rapporten är optioner dyra eftersom marknaden väntar stor rörelse. Efteråt sjunker den implicita volatiliteten och optionerna tappar värde, även om du gissade rätt riktning."}], "q": [{"q": "Bolaget ökar vinsten men aktien faller. Varför kan det hända?", "o": ["Marknaden väntade sig mer", "Det är ett fel", "Börsen stängde", "Det kan aldrig hända"]}, {"q": "Skyddar en stop-loss mot ett gap?", "o": ["Nej, den kan fyllas mycket sämre", "Ja, alltid exakt", "Bara på fredagar", "Ja, om den är röd"]}, {"q": "Vad är IV crush?", "o": ["Optioner tappar värde när volatiliteten sjunker efter rapporten", "Att aktien alltid stiger", "En sorts utdelning", "Ett ljusmönster"]}, {"q": "Vad är klokt för en nybörjare inför en rapport?", "o": ["Minska positionen eller stå utanför", "Öka hävstången", "Ta bort stop-lossen", "Satsa allt"]}, {"m": [["Förväntningar", "Styr reaktionen"], ["Gap", "Öppnar långt från gårdagen"], ["IV crush", "Optioner tappar värde"], ["Rapportdag", "Mindre position"]]}]}, "x150": {"t": "Prop firms", "c": [{"t": "Hur det funkar", "d": "Du betalar en avgift för ett test på ett demokonto. Klarar du målet utan att bryta reglerna får du handla med företagets kapital och dela vinsten."}, {"t": "Typiska regler", "d": "Vanligt är ett vinstmål runt 8–10 procent, en daglig förlustgräns runt 5 procent och en total gräns runt 10 procent. Bryter du en regel är kontot borta."}, {"t": "De flesta misslyckas", "d": "En stor del av intäkterna kommer från avgifter för tester som inte klaras. Se det som en kostnad, kontrollera företagets rykte och lär dig lönsam trading på demo först."}], "q": [{"q": "Vad betalar du för hos en prop firm?", "o": ["Ett test på ett demokonto", "Aktier i företaget", "En garanterad lön", "Ingenting"]}, {"q": "Vad händer om du bryter den dagliga förlustgränsen?", "o": ["Kontot är förlorat", "Du får en bonus", "Ingenting", "Gränsen höjs"]}, {"q": "Var kommer mycket av intäkterna ifrån?", "o": ["Avgifter för tester som inte klaras", "Bara vinstdelning", "Statsbidrag", "Reklam"]}, {"q": "Vad bör du göra innan du köper ett test?", "o": ["Vara lönsam på demo och kolla ryktet", "Köpa tio tester direkt", "Låna pengar", "Lita på reklamen"]}, {"m": [["Vinstmål", "Cirka 8–10 %"], ["Daglig gräns", "Cirka 5 %"], ["Total gräns", "Cirka 10 %"], ["Testavgift", "En kostnad"]]}]}, "x151": {"t": "Copy trading och signalgrupper", "c": [{"t": "Copy trading", "d": "Du kopierar automatiskt en annan traders affärer. Titta på hela historiken, största nedgången och risken per trade, inte bara förra månadens vinst."}, {"t": "Signalgrupper", "d": "Betalda grupper på Telegram och Discord visar ofta bara vinsterna. Kräver de betalning för att visa resultat, eller lovar säkra pengar, är det en varningssignal."}, {"t": "Lär dig varför", "d": "Om du bara följer signaler lär du dig inget, och när signalerna slutar fungera vet du inte varför. Förstå upplägget bakom varje affär."}], "q": [{"q": "Vad ska du titta på innan du kopierar någon?", "o": ["Hela historiken och största nedgången", "Bara förra månadens vinst", "Antalet följare", "Profilbilden"]}, {"q": "En grupp lovar 90 % träffsäkerhet och säkra pengar. Vad är det?", "o": ["En varningssignal", "Ett säkert tips", "En bank", "Ett godkänt fondbolag"]}, {"q": "Varför räcker det inte att följa signaler?", "o": ["Du lär dig inte varför affären togs", "Signaler är olagliga", "De är alltid för dyra", "Det räcker gott"]}, {"q": "Vad visar betalda grupper ofta?", "o": ["Bara vinsterna", "Alla förluster tydligt", "Revisorns rapport", "Ingenting"]}, {"m": [["Copy trading", "Kopiera automatiskt"], ["Drawdown", "Största nedgången"], ["Säkra pengar", "Varningssignal"], ["Förstå upplägget", "Du lär dig själv"]]}]}, "x152": {"t": "Från demo till riktiga pengar", "c": [{"t": "Demo först", "d": "Handla på demo tills du har följt din plan i minst 50–100 affärer och har en positiv förväntan. Demo lär dig plattformen och reglerna utan kostnad."}, {"t": "Börja litet", "d": "Med riktiga pengar känns allt annorlunda. Börja med ett litet belopp som du har råd att förlora och lägsta möjliga risk per trade."}, {"t": "Skala upp långsamt", "d": "Öka storleken först efter en period med stabila resultat. Om du förlorar regler eller sömn, gå ner i storlek igen."}], "q": [{"q": "Hur länge bör du handla demo?", "o": ["Tills planen följts i 50–100 affärer", "En dag", "Inte alls", "Tills du har en bra känsla"]}, {"q": "Hur mycket ska du börja med?", "o": ["Ett litet belopp du har råd att förlora", "Alla sparpengar", "Lånade pengar", "Så mycket som möjligt"]}, {"q": "När ska du öka storleken?", "o": ["Efter en period med stabila resultat", "Efter en stor förlust", "Efter en enda vinst", "Direkt"]}, {"q": "Du börjar bryta regler och sover dåligt. Vad gör du?", "o": ["Går ner i storlek", "Dubblar storleken", "Tar bort stop-lossen", "Fortsätter som vanligt"]}, {"m": [["Demo", "Lär plattform och regler"], ["Litet konto", "Råd att förlora"], ["Skala upp", "Efter stabila resultat"], ["Stress", "Gå ner i storlek"]]}]}, "x153": {"t": "VIX: marknadens rädslomätare", "c": [{"t": "Vad VIX är", "d": "VIX är ett index som visar hur mycket marknaden tror att det amerikanska börsindexet S&P 500 kommer att svänga de närmaste 30 dagarna. Det räknas fram ur priserna på optioner och anges i procent per år."}, {"t": "Stiger när börsen faller", "d": "När börsen faller vill många skydda sig och köper optioner. Då blir optionerna dyrare och VIX stiger. Därför rör sig VIX oftast åt motsatt håll mot börsen."}, {"t": "Lugnt, nervöst eller panik", "d": "En grov tumregel: under 15 är marknaden lugn, 20 till 30 är den nervös och över 30 råder stor oro. Vid de värsta kriserna, som 2008 och våren 2020, var VIX över 80."}, {"t": "Storlek, inte riktning", "d": "VIX säger hur stora rörelser marknaden väntar sig, inte åt vilket håll. Ett högt VIX betyder större svängningar både uppåt och nedåt. Det är ingen köp- eller säljsignal."}], "q": [{"q": "Vad mäter VIX?", "o": ["Hur mycket marknaden väntar sig att S&P 500 svänger de närmaste 30 dagarna", "Priset på en aktie i Apple", "Hur många aktier som handlades i går", "Räntan i USA"]}, {"q": "Börsen faller kraftigt på en dag. Vad händer oftast med VIX?", "o": ["Det stiger", "Det faller", "Det står still", "Det slutar handlas"], "why": "Fler köper skydd i form av optioner, så de blir dyrare och VIX stiger."}, {"q": "VIX står på 35. Hur beskriver man marknaden?", "o": ["Stor oro", "Helt lugn", "Stängd", "På väg upp"]}, {"q": "Är ett högt VIX en signal att köpa?", "o": ["Nej, det visar bara att marknaden väntar sig stora rörelser åt båda hållen", "Ja, alltid", "Ja, om det är fredag", "Nej, det är en säljsignal"]}, {"m": [["VIX under 15", "Lugn marknad"], ["VIX 20–30", "Nervös marknad"], ["VIX över 30", "Stor oro"], ["VIX över 80", "Historisk kris"]]}]}, "x154": {"t": "VIX i praktiken: läsa en orolig dag", "c": [{"t": "Procent av procent", "d": "Står det VIX 18,95 och +10 % betyder det att indexet steg från ungefär 17,2 till 18,95 på en dag. Oron ökade märkbart, men 19 är fortfarande en ganska normal nivå."}, {"t": "Regeln om 16", "d": "Dela VIX med 16 så får du ungefär hur många procent S&P 500 väntas röra sig en vanlig dag. VIX 19 delat med 16 är cirka 1,2 % per dag, uppåt eller nedåt."}, {"t": "Toppar faller tillbaka", "d": "VIX kan rusa snabbt men brukar sjunka tillbaka mot sitt normala läge när oron lagt sig. Det kallas att VIX återgår mot medelvärdet. Man vet dock aldrig hur länge oron varar."}, {"t": "Vad du gör med VIX", "d": "Använd VIX som väderrapport: när det är högt, ta mindre positioner och räkna med större svängningar. Själva VIX går inte att köpa, och fonder som följer VIX tappar ofta värde över tid. De passar inte nybörjare."}], "q": [{"q": "VIX står på 18,95 och +10 %. Vad var det ungefär i går?", "o": ["Cirka 17,2", "Cirka 8,95", "Cirka 28,95", "Exakt 10"], "why": "18,95 delat med 1,10 är ungefär 17,2. Procenten gäller VIX-värdet, inte börsen."}, {"q": "Med regeln om 16: hur mycket väntas S&P 500 röra sig per dag när VIX är 32?", "o": ["Cirka 2 %", "Cirka 32 %", "Cirka 16 %", "Cirka 0,2 %"]}, {"q": "VIX har rusat till 40. Vad är ett klokt sätt att hantera risken?", "o": ["Ta mindre positioner och räkna med större svängningar", "Dubbla positionen eftersom priset rör sig mer", "Ta bort stop-lossen", "Köpa en VIX-fond och behålla den i flera år"]}, {"q": "Vad brukar hända med VIX efter en kraftig topp?", "o": ["Det sjunker så småningom tillbaka mot sitt normala läge", "Det stannar på toppen för alltid", "Det blir negativt", "Det dubblas varje vecka"]}, {"q": "Sätt stegen i rätt ordning.", "ord": ["Börsen faller snabbt", "Fler köper optioner som skydd", "Optionerna blir dyrare", "VIX stiger"]}]}};
